// Pokédex entries (PokeAPI), the Pokémon's name hidden: [English, French, [category EN, FR], nickname].
window.DLE_DESCRIPTIONS = {
  "bulbasaur": ["While it is young, it uses the nutrients that are stored in the seed on its back in order to grow.", "Quand il est jeune, il absorbe les nutriments conservés dans son dos pour grandir et se développer.", ["Seed Pokémon", "Pokémon Graine"], null],
  "ivysaur": ["Exposure to sunlight adds to its strength. Sunlight also makes the bud on its back grow larger.", "La lumière du soleil le rend plus fort et vigoureux. Le bulbe sur son dos grossit en conséquence.", ["Seed Pokémon", "Pokémon Graine"], null],
  "venusaur": ["A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.", "Une douce senteur émane de sa plante. Cette fragrance calme tous ceux qui sont engagés dans un combat.", ["Seed Pokémon", "Pokémon Graine"], null],
  "charmander": ["From the time it is born, a flame burns at the tip of its tail. Its life would end if the flame were to go out.", "Depuis sa naissance, une petite flamme brûle au bout de sa queue. Si cette flamme s’éteint, la vie de ce Pokémon s’éteindra elle aussi.", ["Lizard Pokémon", "Pokémon Lézard"], null],
  "charmeleon": ["If it becomes agitated during battle, it spouts intense flames, incinerating its surroundings.", "S’il s’excite pendant un combat, il crache de grandes flammes, brûlant tout ce qui se trouve aux alentours.", ["Flame Pokémon", "Pokémon Flamme"], null],
  "charizard": ["Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.", "Ses ailes lui permettent de voler à plus de 1 400 m d’altitude. Ce Pokémon crache du feu à des températures très élevées.", ["Flame Pokémon", "Pokémon Flamme"], null],
  "squirtle": ["When it feels threatened, it draws its limbs inside its shell and sprays water from its mouth.", "S’il se sent menacé, il rétracte ses pattes dans sa carapace pour se protéger et crache de l’eau.", ["Tiny Turtle Pokémon", "Pokémon Minitortue"], null],
  "wartortle": ["It cleverly controls its furry ears and tail to maintain its balance while swimming.", "Il se sert habilement de sa queue et de ses oreilles touffues pour garder son équilibre sous l’eau.", ["Turtle Pokémon", "Pokémon Tortue"], null],
  "blastoise": ["The rocket cannons on its shell fire jets of water capable of punching holes through thick steel.", "Les canons sur sa carapace tirent des jets d’eau capables de percer même de l’acier trempé.", ["Shellfish Pokémon", "Pokémon Carapace"], null],
  "caterpie": ["Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.", "Ses petites pattes munies de ventouses lui permettent de monter les pentes et de grimper aux murs sans se fatiguer.", ["Worm Pokémon", "Pokémon Ver"], null],
  "metapod": ["Even though it is encased in a sturdy shell, the body inside is tender. It can’t withstand a harsh attack.", "Bien que son corps soit entouré d’une carapace solide, l’intérieur est si mou qu’il ne résisterait pas à une attaque violente.", ["Cocoon Pokémon", "Pokémon Cocon"], null],
  "butterfree": ["It collects honey every day. It rubs honey onto the hairs on its legs to carry it back to its nest.", "Il ramasse du nectar chaque jour et l’agglutine sur les poils de ses pattes pour le transporter jusqu’à son nid.", ["Butterfly Pokémon", "Pokémon Papillon"], null],
  "weedle": ["Beware of the sharp stinger on its head. It hides in grass and bushes where it eats leaves.", "L’aiguillon sur son front est très pointu. Il se cache dans les bois et les hautes herbes, où il se gave de feuilles.", ["Hairy Bug Pokémon", "Pokémon Insectopic"], null],
  "kakuna": ["Able to move only slightly. When endangered, it may stick out its stinger and poison its enemy.", "Il peut à peine bouger. Quand il est menacé, il sort parfois son aiguillon pour empoisonner ses ennemis.", ["Cocoon Pokémon", "Pokémon Cocon"], null],
  "beedrill": ["It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.", "Il se sert de ses trois aiguillons empoisonnés situés sur les pattes avant et l’abdomen pour attaquer sans relâche ses adversaires.", ["Poison Bee Pokémon", "Pokémon Guêpoison"], null],
  "pidgey": ["Very docile. If attacked, it will often kick up sand to protect itself rather than fight back.", "De nature très docile, il préfère projeter du sable pour se défendre plutôt que contre-attaquer.", ["Tiny Bird Pokémon", "Pokémon Minoiseau"], null],
  "pidgeotto": ["This Pokémon is full of vitality. It constantly flies around its large territory in search of prey.", "Ce Pokémon est très endurant. Il survole en permanence son territoire pour chasser.", ["Bird Pokémon", "Pokémon Oiseau"], null],
  "pidgeot": ["This Pokémon flies at Mach 2 speed, seeking prey. Its large talons are feared as wicked weapons.", "Ce Pokémon vole à Mach 2 quand il chasse. Ses grandes serres sont des armes redoutables.", ["Bird Pokémon", "Pokémon Oiseau"], null],
  "rattata": ["Will chew on anything with its fangs. If you see one, you can be certain that 40 more live in the area.", "Il peut ronger n’importe quoi avec ses deux dents. Quand on en voit un, il y en a certainement 40 dans le coin.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "raticate": ["Its hind feet are webbed. They act as flippers, so it can swim in rivers and hunt for prey.", "Ses pattes arrière sont palmées. Il peut donc poursuivre sa proie dans les cours d’eau et les rivières.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "spearow": ["Inept at flying high. However, it can fly around very fast to protect its territory.", "Il est incapable de voler à haute altitude. Il se déplace très vite pour protéger son territoire.", ["Tiny Bird Pokémon", "Pokémon Minoiseau"], null],
  "fearow": ["A Pokémon that dates back many years. If it senses danger, it flies high and away, instantly.", "Un Pokémon très ancien. S’il perçoit un danger, il fuit instantanément à haute altitude.", ["Beak Pokémon", "Pokémon Bec-Oiseau"], null],
  "ekans": ["The older it gets, the longer it grows. At night, it wraps its long body around tree branches to rest.", "Plus il est âgé, plus son corps est long. La nuit, il s’enroule autour de branches d’arbres pour se reposer.", ["Snake Pokémon", "Pokémon Serpent"], null],
  "arbok": ["The frightening patterns on its belly have been studied. Six variations have been confirmed.", "Des études ont révélé que les marques effrayantes de son corps pouvaient former six motifs différents.", ["Cobra Pokémon", "Pokémon Cobra"], null],
  "pikachu": ["Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.", "Les ??? se disent bonjour en se frottant la queue et en y faisant passer du courant électrique.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "raichu": ["It can discharge bursts of electricity exceeding 100,000 volts— a single strike with that amount of power would incapacitate one of the Copperajah of my homeland.", "Si ses joues sont à court d’énergie, il lève la queue et capte l’électricité contenue dans l’atmosphère.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "sandshrew": ["It burrows into the ground to create its nest. If hard stones impede its tunneling, it uses its sharp claws to shatter them and then carries on digging.", "Il creuse le sol pour construire sa tanière. Rien n’arrête ses griffes acérées, pas même la roche la plus solide.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "sandslash": ["It climbs trees by hooking on with its sharp claws. ??? shares the berries it gathers, dropping them down to Sandshrew waiting below the tree.", "Il grimpe aux arbres grâce à ses griffes acérées et fait tomber des Baies pour les Sabelette qui attendent au sol.", ["Mouse Pokémon", "Pokémon Souris"], null],
  "nidoran-f": ["It uses its hard incisor teeth to crush and eat berries. The tip of a female Nidoran’s horn is a bit more rounded than the tip of a male’s horn.", "Ce Pokémon se nourrit de Baies en les ouvrant avec ses incisives. Le bout de sa corne est plus arrondi que celui du mâle.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "nidorina": ["If the group is threatened, these Pokémon will band together to assault enemies with a chorus of ultrasonic waves.", "Si un danger menace le groupe, ces Pokémon se réunissent et l’affrontent en émettant des ultrasons en chœur.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "nidoqueen": ["It pacifies offspring by placing them in the gaps between the spines on its back. The spines will never secrete poison while young are present.", "Ce Pokémon calme les petits de son espèce en les plaçant entre ses épines dorsales. Dans ce cas, elles ne libèrent pas de poison.", ["Drill Pokémon", "Pokémon Perceur"], null],
  "nidoran-m": ["Small but brave, this Pokémon will hold its ground and even risk its life in battle to protect the female it’s friendly with.", "Malgré sa petite taille, il est très téméraire. Afin de protéger sa compagne, il est prêt à se battre et à risquer sa vie.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "nidorino": ["It’s nervous and quick to act aggressively. The potency of its poison increases along with the level of adrenaline present in its body.", "D’un naturel nerveux, il est prompt à se battre. Lorsqu’il a une montée d’adrénaline, la concentration de son poison augmente.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "nidoking": ["??? prides itself on its strength. It’s forceful and spirited in battle, making use of its thick tail and diamond-crushing horn.", "Très fier de sa force, il se bat vigoureusement à l’aide de sa queue robuste et de sa corne capable de briser le diamant.", ["Drill Pokémon", "Pokémon Perceur"], null],
  "clefairy": ["It can be found in quiet mountain areas on a full moon's night. Its dancing and its tiny, faintly glowing wings confer upon it a lovely fairylike quality.", "Son comportement et son cri adorables font de lui un Pokémon très populaire. Malheureusement, il est difficile d’en croiser un spécimen.", ["Fairy Pokémon", "Pokémon Fée"], null],
  "clefable": ["Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.", "Capable d’entendre une aiguille tomber à plus d’un kilomètre, ce Pokémon préfère les endroits calmes et isolés.", ["Fairy Pokémon", "Pokémon Fée"], null],
  "vulpix": ["In its belly burns a fire, which ??? spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.", "Avec l’âge, la fourrure de ses six queues devient de plus en plus belle et soyeuse. Elle est chaude au toucher.", ["Fox Pokémon", "Pokémon Renard"], null],
  "ninetales": ["The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.", "Il est très intelligent et rancunier. Quiconque attrape une de ses queues se fera maudire pour 1 000 ans.", ["Fox Pokémon", "Pokémon Renard"], null],
  "jigglypuff": ["By freely changing the wavelength of its voice, ??? sings a mysterious melody sure to make any listener sleepy.", "Il module librement la longueur d’onde de sa voix pour chanter une étrange mélodie qui endort à tous les coups celui qui l’écoute.", ["Balloon Pokémon", "Pokémon Bouboule"], null],
  "wigglytuff": ["It’s proud of its fur, which is fine and delicate. In particular, the curl on its forehead has a texture that’s perfectly heavenly.", "Sa fourrure soyeuse fait sa fierté. La touffe sur son front est si douce que la caresser donne l’impression d’être sur un petit nuage.", ["Balloon Pokémon", "Pokémon Bouboule"], null],
  "zubat": ["Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.", "Ils vivent dans les grottes où la lumière du jour ne perce jamais. Le matin, ils se blottissent les uns contre les autres pour se réchauffer et dormir.", ["Bat Pokémon", "Pokémon Chovsouris"], null],
  "golbat": ["It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.", "Il se déplace habilement sur ses petites pattes, s’approche silencieusement de sa proie endormie, et lui suce le sang à l’aide de ses crocs.", ["Bat Pokémon", "Pokémon Chovsouris"], null],
  "oddish": ["During the day, it stays in the cold underground to avoid the sun. It grows by bathing in moonlight.", "Pendant la journée, il reste en sous-sol et évite le soleil. Il grandit en se baignant au clair de lune.", ["Weed Pokémon", "Pokémon Racine"], null],
  "gloom": ["What appears to be drool is actually sweet honey. It is very sticky and clings stubbornly if touched.", "Ce qui semble être sa bave est en fait du nectar très collant. Si on le touche, il est très difficile de s’en dépêtrer.", ["Weed Pokémon", "Pokémon Racine"], null],
  "vileplume": ["The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.", "Plus ses pétales sont grands, plus il produit de pollen toxique. Toutefois, le poids de sa tête le fatigue.", ["Flower Pokémon", "Pokémon Fleur"], null],
  "paras": ["Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as ??? matures.", "Il s’enfouit pour ronger des racines, mais ce sont les champignons sur son dos qui absorbent presque tous les nutriments.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "parasect": ["Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of ???'s actions.", "À force de voir son énergie aspirée, il semblerait que ce ne soit plus l’insecte qui réfléchisse, mais le champignon sur son dos.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "venonat": ["Its large eyes act as radar. In a bright place, you can see that they are clusters of many tiny eyes.", "Ses grands yeux lui servent de radar. En pleine lumière, on peut y distinguer des facettes.", ["Insect Pokémon", "Pokémon Vermine"], null],
  "venomoth": ["The powdery scales on its wings are hard to remove from skin. They also contain poison that leaks out on contact.", "Les écailles de ses ailes sont presque impossibles à retirer lorsqu’elles se collent à la peau, et elles libèrent un poison violent au contact.", ["Poison Moth Pokémon", "Pokémon Papipoison"], null],
  "diglett": ["It burrows through the ground at a shallow depth. It leaves raised earth in its wake, making it easy to spot.", "Ce Pokémon creuse sous terre à faible profondeur. La terre qu’il laisse dans son sillage le rend facile à repérer.", ["Mole Pokémon", "Pokémon Taupe"], null],
  "dugtrio": ["These Diglett triplets dig over 60 miles below sea level. No one knows what it’s like underground.", "Ce trio de Taupiqueur est capable de creuser jusqu’à 100 km sous terre, vers l’inconnu.", ["Mole Pokémon", "Pokémon Taupe"], null],
  "meowth": ["It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian ???.", "Tatillon sur la propreté de la pièce sur son front, il se lave la figure avec grand soin. Il ne s’entend pas avec les ??? de Galar.", ["Scratch Cat Pokémon", "Pokémon Chadégout"], null],
  "persian": ["Its elegant and refined behavior clashes with that of the barbaric Perrserker. The relationship between the two is one of mutual disdain.", "Il se comporte avec grâce et élégance, et ne s’entend pas avec les rustres Berserkatt : les deux espèces se méprisent.", ["Classy Cat Pokémon", "Pokémon Chadeville"], null],
  "psyduck": ["Suffers perpetual headaches. If the agony grows too great, ???'s latent power erupts, contrary to ???'s intent. Ergo, I am exploring ways to ease the pain.", "Sa migraine s’intensifie à mesure que son stress monte. Il libère une force psychique puissante qui terrasse tous ceux qui l’entourent.", ["Duck Pokémon", "Pokémon Canard"], null],
  "golduck": ["Its body is strong, and it has webbing on its hands and feet. ??? can swim easily through rough seas, clawing its way through the high waves.", "D’après de vieilles légendes, ce Pokémon entraînait au fond de l’eau tous ceux qui osaient souiller sa rivière.", ["Duck Pokémon", "Pokémon Canard"], null],
  "mankey": ["An agile Pokémon that lives in trees. It angers easily and will not hesitate to attack anything.", "Agile et rapide, ce Pokémon vit dans les arbres. Il s’énerve facilement et s’attaque à tout ce qui bouge quand il est en colère.", ["Pig Monkey Pokémon", "Pokémon Porsinge"], null],
  "primeape": ["It stops being angry only when nobody else is around. To view this moment is very difficult.", "Sa fureur prend fin quand il n’a plus personne à frapper. Il est difficile d’en être témoin.", ["Pig Monkey Pokémon", "Pokémon Porsinge"], null],
  "growlithe": ["They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.", "Très fidèle, il aboie de toutes ses forces pour protéger son Dresseur d’Origine quand un danger le guette.", ["Puppy Pokémon", "Pokémon Chiot"], null],
  "arcanine": ["Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.", "Ce Pokémon est admiré depuis toujours pour sa beauté. Il court avec tellement de légèreté qu’on dirait qu’il vole.", ["Legendary Pokémon", "Pokémon Légendaire"], null],
  "poliwag": ["In rivers with fast-flowing water, this Pokémon will cling to a rock by using its thick lips, which act like a suction cup.", "Dans les rivières au courant puissant, il se sert de ses lèvres épaisses comme d’une ventouse pour s’accrocher aux rochers.", ["Tadpole Pokémon", "Pokémon Têtard"], null],
  "poliwhirl": ["This Pokémon’s sweat is a slimy mucus. When captured, ??? can slither from its enemies’ grasp and escape.", "Il sécrète une sorte de mucus huileux qui lui permet d’échapper aux ennemis qui tentent de l’attraper.", ["Tadpole Pokémon", "Pokémon Têtard"], null],
  "poliwrath": ["??? is skilled at both swimming and martial arts. It uses its well-trained arms to dish out powerful punches.", "Aussi habile à la nage qu’au combat, il peut donner de vigoureux coups de poing avec ses bras musclés.", ["Tadpole Pokémon", "Pokémon Têtard"], null],
  "abra": ["Spends 18 hours of the day sleeping. Even while asleep, ??? can control its psychic powers—should danger approach, the Pokémon will simply teleport away.", "Il peut se téléporter en dormant. On dit que plus son sommeil est profond, plus il se téléporte loin.", ["Psi Pokémon", "Pokémon Psy"], null],
  "kadabra": ["There are rumors that a child with mystical powers became a ???; however, this remains unverified. I suspect that the spoon ??? holds enhances its brain waves.", "Incroyablement doué en télékinésie, il concentre son énergie psychique dans l’étoile sur son front en prévision de son évolution.", ["Psi Pokémon", "Pokémon Psy"], null],
  "alakazam": ["The longer ??? lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.", "Il dispose d’immenses pouvoirs psychiques. On raconte qu’il s’en est servi afin de créer les cuillères qu’il tient dans chaque main.", ["Psi Pokémon", "Pokémon Psy"], null],
  "machop": ["Though as small as a child, it has strength enough to easily throw a well-built adult. Striving to become ever stronger, ??? trains by carrying a Graveler on its shoulders.", "Il essaie de dépenser son énergie débordante en soulevant des rochers, ce qui le rend encore plus fort.", ["Superpower Pokémon", "Pokémon Colosse"], null],
  "machoke": ["A sturdy creature boasting a robust physique and boundless stamina. Loves training above all else and voluntarily assists with tasks such as construction and clearing land.", "Son corps robuste ne se fatigue jamais. Il n’hésite pas à aider les gens lorsqu’il s’agit de soulever des objets très lourds.", ["Superpower Pokémon", "Pokémon Colosse"], null],
  "machamp": ["In close combat, its four arms afford it offensive and defensive supremacy. In but a blink, this valiant Pokémon can overwhelm its foes with more than 1,000 blows from its fists.", "Il enchaîne les coups de poing avec ses quatre bras à une vitesse surprenante.", ["Superpower Pokémon", "Pokémon Colosse"], null],
  "bellsprout": ["Prefers hot and humid places. It ensnares tiny bugs with its vines and devours them.", "Il préfère les endroits chauds et humides. Il capture les Pokémon Insecte avec ses lianes pour les dévorer.", ["Flower Pokémon", "Pokémon Fleur"], null],
  "weepinbell": ["When hungry, it swallows anything that moves. Its hapless prey is dissolved by strong acids.", "Quand il a faim, il avale tout ce qui bouge, puis achève ses proies avec de l’acide.", ["Flycatcher Pokémon", "Pokémon Carnivore"], null],
  "victreebel": ["Lures prey with the sweet aroma of honey. Swallowed whole, the prey is dissolved in a day, bones and all.", "Il attire ses proies avec une odeur de miel et les avale tout entières. Il les digère en un jour seulement, les os y compris.", ["Flycatcher Pokémon", "Pokémon Carnivore"], null],
  "tentacool": ["They fire beams from the glassy, magenta orbs that resemble eyes atop their heads, and they drift in shallow seas. During low tide, they can sometimes be found on beaches, desiccated.", "Il est presque totalement composé d’eau. Lorsqu’il s’immerge dans les flots, son corps se fond dans l’eau, ce qui le rend presque invisible.", ["Jellyfish Pokémon", "Pokémon Mollusque"], null],
  "tentacruel": ["It has 80 tentacles, each with a venomous tip. These tentacles are also extendible, lengthening when ??? attempts to catch prey. Use caution.", "Il peut allonger ses 80 tentacules à volonté et les utiliser comme un filet pour attraper sa proie et la transpercer de ses pics empoisonnés.", ["Jellyfish Pokémon", "Pokémon Mollusque"], null],
  "geodude": ["Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.", "On en trouve près des sentiers de montagne. Si vous marchez dessus par inadvertance, ils s’énervent et attaquent.", ["Rock Pokémon", "Pokémon Roche"], null],
  "graveler": ["Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.", "Il dévale les sentiers de montagne et traverse les obstacles en les pulvérisant.", ["Rock Pokémon", "Pokémon Roche"], null],
  "golem": ["The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.", "Juste après la mue, son corps est blanc et tendre. Au contact de l’air, sa peau se solidifie et forme une armure.", ["Megaton Pokémon", "Pokémon Titanesque"], null],
  "ponyta": ["These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.", "Il semblerait qu’une fois qu’un Dresseur a gagné la confiance de ???, sa crinière enflammée ne le brûle plus au toucher.", ["Fire Horse Pokémon", "Pokémon Cheval Feu"], null],
  "rapidash": ["Fiery mane aglow, ??? darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.", "Au sein d’un troupeau, c’est le plus rapide qui devient le chef. Il choisit les lieux où se rendre et détermine la vitesse de galop.", ["Fire Horse Pokémon", "Pokémon Cheval Feu"], null],
  "slowpoke": ["When this Pokémon’s tail is soaked in water, sweetness seeps from it. ??? uses this trait to lure in and fish up other Pokémon.", "Lorsqu’il trempe le bout de sa queue dans l’eau, une substance sucrée s’en dégage. Il s’en sert pour appâter ses proies quand il pêche.", ["Dopey Pokémon", "Pokémon Crétin"], null],
  "slowbro": ["Being bitten by a Shellder shocked this Pokémon into standing on two legs. If the Shellder lets go, it seems ??? will turn back into a Slowpoke.", "La morsure du Kokiyas l’a tellement surpris qu’il est devenu bipède. Il paraît qu’il redevient un Ramoloss si le Kokiyas lâche prise.", ["Hermit Crab Pokémon", "Pokémon Symbiose"], null],
  "magnemite": ["A bizarre Pokémon with but a single eye embedded in an iron sphere. I suspect this creature levitates due to the magnetism it emits from its arms, which resemble horseshoe-shaped magnets.", "Il se nourrit d’électricité et flotte dans les airs en libérant des ondes électro???ques avec les aimants situés de part et d’autre de son corps.", ["Magnet Pokémon", "Pokémon Magnétique"], null],
  "magneton": ["Three Magnemite gathered to evolve into this Pokémon. The source of much vexation on my part, as its powerful magnetism destroys my research equipment.", "Il émet constamment une énergie magnétique puissante qui interfère avec la grande majorité des ordinateurs dont il s’approche.", ["Magnet Pokémon", "Pokémon Magnétique"], null],
  "farfetchd": ["They use a plant stalk as a weapon, but not all of them use it in the same way. Several distinct styles of stalk fighting have been observed.", "Il se bat à l’aide de sa tige. Il existe plusieurs écoles quant à son maniement.", ["Wild Duck Pokémon", "Pokémon Canard Fou"], null],
  "doduo": ["Its short wings make flying difficult. Instead, this Pokémon runs at high speed on developed legs.", "Ses petites ailes ne lui permettent pas de voler, mais grâce à ses puissantes pattes, il peut courir très rapidement.", ["Twin Bird Pokémon", "Pokémon Duoiseau"], null],
  "dodrio": ["One of Doduo’s two heads splits to form a unique species. It runs close to 40 mph in prairies.", "Quand une des têtes de Doduo se divise, il devient un ??? capable de courir à 60 km/h.", ["Triple Bird Pokémon", "Pokémon Trioiseau"], null],
  "seel": ["Loves freezing-cold conditions. Relishes swimming in a frigid climate of around 14 degrees Fahrenheit.", "Il est à l’aise dans les endroits gelés. Il nage avec plaisir dans de l’eau à -10 ºC.", ["Sea Lion Pokémon", "Pokémon Otarie"], null],
  "dewgong": ["Its entire body is a snowy white. Unharmed by even intense cold, it swims powerfully in icy waters.", "Son corps entier est aussi blanc que la neige. Il résiste bien au froid et peut même nager au milieu des icebergs.", ["Sea Lion Pokémon", "Pokémon Otarie"], null],
  "grimer": ["Made of congealed sludge. It smells too putrid to touch. Even weeds won’t grow in its path.", "Ce tas de fange sent si mauvais qu’il est impossible de le toucher. Plus rien ne pousse dans son sillage putride.", ["Sludge Pokémon", "Pokémon Dégueu"], null],
  "muk": ["Smells so awful, it can cause fainting. Through degeneration of its nose, it lost its sense of smell.", "Son odeur immonde provoque des évanouissements. Son odorat s’est atrophié à cause de sa propre puanteur.", ["Sludge Pokémon", "Pokémon Dégueu"], null],
  "shellder": ["Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.", "Sa coquille est si résistante qu’elle repousse toutes les attaques. En revanche, il est vulnérable quand celle-ci s’ouvre.", ["Bivalve Pokémon", "Pokémon Bivalve"], null],
  "cloyster": ["Once it slams its shell shut, it is impossible to open, even by those with superior strength.", "Quand il referme sa coquille, il est impossible de la rouvrir, même avec une force hors du commun.", ["Bivalve Pokémon", "Pokémon Bivalve"], null],
  "gastly": ["Gaseous and completely impalpable. Also highly dangerous— inhaling part of its poisonous body will cause one to faint instantly.", "Son corps gazéiforme lui permet de se glisser n’importe où, mais au moindre coup de vent, il s’envole.", ["Gas Pokémon", "Pokémon Gaz"], null],
  "haunter": ["This frightful, malevolent spirit can glide through walls, appearing wherever it likes. According to rumor, victims of a ???'s lick will wither to death day by day.", "On dit que lorsque quelqu’un a l’impression d’être surveillé dans le noir, c’est sûrement qu’un ??? se trouve dans les parages.", ["Gas Pokémon", "Pokémon Gaz"], null],
  "gengar": ["Possesses potential victims' shadows in an effort to steal away the victims' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!", "On dit qu’??? surgit parfois des ténèbres pour prendre la vie des personnes égarées en montagne.", ["Shadow Pokémon", "Pokémon Ombre"], null],
  "onix": ["This chain of immense stones resembles a giant serpent. Tremors shake the earth above as it burrows deep beneath the ground, feeding on boulders as it goes.", "Il creuse dans le sol à une vitesse de 80 km/h en contorsionnant son immense corps de pierre.", ["Rock Snake Pokémon", "Pokémon Serpenroc"], null],
  "drowzee": ["If you sleep by it all the time, it will sometimes show you dreams it had eaten in the past.", "Si vous dormez tout le temps près de lui, il partagera parfois avec vous les rêves qu’il a dévorés par le passé.", ["Hypnosis Pokémon", "Pokémon Hypnose"], null],
  "hypno": ["Avoid eye contact if you come across one. It will try to put you to sleep by using its pendulum.", "Évitez son regard quand vous en croisez un, ou il pourrait essayer de vous hypnotiser avec son pendule.", ["Hypnosis Pokémon", "Pokémon Hypnose"], null],
  "krabby": ["If it senses danger approaching, it cloaks itself with bubbles from its mouth so it will look bigger.", "S’il se sent menacé, il se cache derrière les bulles émises par sa bouche pour paraître plus gros.", ["River Crab Pokémon", "Pokémon Doux Crabe"], null],
  "kingler": ["Its oversized claw is very powerful, but when it’s not in battle, the claw just gets in the way.", "Sa pince gigantesque possède une puissance destructrice phénoménale, mais hors combat, son poids devient un handicap.", ["Pincer Pokémon", "Pokémon Pince"], null],
  "voltorb": ["An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.", "On dit qu’il se déguise en Poké Ball. Il s’autodétruit à la moindre stimulation.", ["Ball Pokémon", "Pokémon Balle"], null],
  "electrode": ["The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.", "Il stocke de l’énergie électrique dans son corps, ce qui le rend instable et explosif.", ["Ball Pokémon", "Pokémon Balle"], null],
  "exeggcute": ["These Pokémon get nervous when they’re not in a group of six. The minute even one member of the group goes missing, ??? become cowardly.", "Il a besoin d’être constitué de ses six membres pour rester calme. Sitôt qu’il en manque un, il lui prend soudainement l’envie de fuir.", ["Egg Pokémon", "Pokémon Œuf"], null],
  "exeggutor": ["When they work together, ???’s three heads can put out powerful psychic energy. Cloudy days make this Pokémon sluggish.", "Les attaques psychiques lancées par ses trois têtes à l’unisson sont très puissantes. Par temps nuageux, ses mouvements sont plus lents.", ["Coconut Pokémon", "Pokémon Fruitpalme"], null],
  "cubone": ["This Pokémon wears the skull of its deceased mother. Sometimes ???’s dreams make it cry, but each tear ??? sheds makes it stronger.", "Il porte sur sa tête le crâne de sa défunte mère. Il lui arrive de rêver d’elle et de pleurer, mais chaque larme qu’il verse le rend plus fort.", ["Lonely Pokémon", "Pokémon Solitaire"], null],
  "marowak": ["When this Pokémon evolved, the skull of its mother fused to it. ???’s temperament also turned vicious at the same time.", "En évoluant, il est devenu violent, et le crâne de sa mère qu’il portait a fusionné avec sa tête.", ["Bone Keeper Pokémon", "Pokémon Gard’Os"], null],
  "hitmonlee": ["The legs freely contract and stretch. The stretchy legs allow it to hit a distant foe with a rising kick.", "??? peut rétracter et étendre ses jambes à sa guise. La formidable allonge dont il dispose lui permet de frapper des adversaires éloignés.", ["Kicking Pokémon", "Pokémon Latteur"], null],
  "hitmonchan": ["Its punches slice the air. However, it seems to need a short break after fighting for three minutes.", "Ses poings fendent l’air, mais il se fatigue au bout de trois minutes à enchaîner les coups.", ["Punching Pokémon", "Pokémon Puncheur"], null],
  "lickitung": ["Wields its long tongue deftly, as though it were an arm. The Pokémon's viscous saliva, once it has been collected and boiled down, yields a strong and highly useful adhesive.", "??? se nourrit essentiellement de Pokémon Insecte. Il lèche ses ennemis avec sa longue langue pour les paralyser, puis les avale tout rond.", ["Licking Pokémon", "Pokémon Lécheur"], null],
  "koffing": ["It adores polluted air. Some claim that ??? used to be more plentiful in the Galar region than they are now.", "On raconte qu’il y a longtemps, ces Pokémon amateurs d’air pollué étaient beaucoup plus nombreux à Galar.", ["Poison Gas Pokémon", "Pokémon Gaz Mortel"], null],
  "weezing": ["It can’t suck in air quite as well as a Galarian ???, but the toxins it creates are more potent than those of its counterpart.", "Il ne peut pas aspirer autant d’air que le ??? de Galar, mais le poison qu’il produit est plus puissant.", ["Poison Gas Pokémon", "Pokémon Gaz Mortel"], null],
  "rhyhorn": ["Ludicrously strong—when it butts heads with a mountain, it is the mountain that shatters. But its short legs struggle with turns, and it is incapable of stopping unless it collides with something.", "Il ne peut se souvenir que d’une chose à la fois. S’il se met à courir, il en oublie tout de suite la raison.", ["Spikes Pokémon", "Pokémon Piquant"], null],
  "rhydon": ["Rapidly rotates its horn to bore through bedrock. It swaggers around volcanic regions, protected from the lava's heat by its tough, armorlike hide.", "Son épiderme est si épais qu’il lui permet même de survivre dans du magma d’une température de 2 000 °C.", ["Drill Pokémon", "Pokémon Perceur"], null],
  "chansey": ["This purehearted Pokémon shares its eggs with the injured.", "Ce Pokémon lent à l’origine a appris à fuir plus vite pour protéger ses œufs des voleurs.", ["Egg Pokémon", "Pokémon Œuf"], null],
  "tangela": ["It is cloaked entirely in blue vines, preventing any glimpse of its true identity. The vines impart a refreshing sensation when chewed—they're useful as a spice.", "Ses lianes ont une odeur particulière. Elles servent d’herbes aromatiques dans une certaine zone de Galar.", ["Vine Pokémon", "Pokémon Vigne"], null],
  "kangaskhan": ["There are records of a lost human child being raised by a childless ???.", "Certains documents certifient que les ??? sans progéniture élevaient des enfants humains en détresse.", ["Parent Pokémon", "Pokémon Maternel"], null],
  "horsea": ["They swim with dance-like motions and cause whirlpools to form. ??? compete to see which of them can generate the biggest whirlpool.", "??? crée des tourbillons en dansant sous l’eau. Il s’amuse à comparer la taille des remous qu’il fait avec ceux de ses congénères.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "seadra": ["???’s mouth is slender, but its suction power is strong. In an instant, ??? can suck in food that’s larger than the opening of its mouth.", "Sa puissance de succion est si forte qu’il peut aspirer en un instant ses proies pour les manger, même si elles sont plus grosses que sa bouche.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "goldeen": ["Its dorsal and pectoral fins are strongly developed like muscles. It can swim at a speed of five knots.", "Ses nageoires dorsales et pectorales sont très développées. Elles lui permettent de nager à une vitesse de cinq nœuds.", ["Goldfish Pokémon", "Pokémon Poisson"], null],
  "seaking": ["Using its horn, it bores holes in riverbed boulders, making nests to prevent its eggs from washing away.", "S’il fait des trous dans les rochers avec sa corne pour bâtir son nid, c’est pour éviter que ses Œufs ne soient emportés par les flots.", ["Goldfish Pokémon", "Pokémon Poisson"], null],
  "staryu": ["Fish Pokémon nibble at it, but ??? isn’t bothered. Its body regenerates quickly, even if part of it is completely torn off.", "Il ne se soucie guère des Pokémon poissons qui viennent le grignoter, car même si son corps est déchiqueté, il se régénère aussitôt.", ["Star Shape Pokémon", "Pokémon Étoile"], null],
  "starmie": ["??? swims by spinning its body at high speed. As this Pokémon cruises through the ocean, it absorbs tiny plankton.", "Il aspire du plancton quand il nage dans la mer en faisant tourner son corps à grande vitesse.", ["Mysterious Pokémon", "Pokémon Mystérieux"], null],
  "mr-mime": ["The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.", "Son talent pour le mime est indéniable. Il émet des ondes du bout des doigts pour créer un mur qui le protège de nombreuses attaques.", ["Barrier Pokémon", "Pokémon Bloqueur"], null],
  "scyther": ["The large, wickedly sharp scythes on its forearms are truly fearsome weapons. Prey's attempts to flee are unfailingly thwarted by this Pokémon's nimble motions.", "Si l’on voit un grand nombre d’arbres abattus au même endroit dans une forêt, cela signifie que l’on se trouve sur le territoire d’un ???.", ["Mantis Pokémon", "Pokémon Mante"], null],
  "jynx": ["The ??? of Galar often have beautiful and delicate voices. Some of these Pokémon have even gathered a fan base.", "Les ??? vivant à Galar sont souvent dotés d’une belle voix cristalline, ce qui leur vaut d’attirer des fans.", ["Human Shape Pokémon", "Pokémon Humanoïde"], null],
  "electabuzz": ["Feeds on electrical energy. During sudden showers beneath looming thunderclouds, one can observe ??? scaling tall trees, where the Pokémon will then wait for lightning to strike.", "Quand un orage approche, ils se réunissent tous autour d’un grand arbre et attendent patiemment que la foudre s’abatte.", ["Electric Pokémon", "Pokémon Électrique"], null],
  "magmar": ["Legend has it that this Pokémon was born from the crater of a volcano. When wounded, it bathes in lava to heal its body, much as one would soak in a hot spring.", "Tout son corps est en combustion permanente. Il est craint, car on dit qu’il cause des incendies.", ["Spitfire Pokémon", "Pokémon Crache-Feu"], null],
  "pinsir": ["This Pokémon clamps its pincers down on its prey and then either splits the prey in half or flings it away.", "Une fois sa proie enserrée entre ses cornes, deux choix s’offrent à lui : la couper en deux ou la projeter au loin de toutes ses forces.", ["Stag Beetle Pokémon", "Pokémon Scarabée"], null],
  "tauros": ["The ??? of the Galar region are volatile in nature, and they won’t allow people to ride on their backs.", "Les ??? vivant à Galar ont un tempérament violent et ne tolèrent pas que les êtres humains montent sur leur dos.", ["Wild Bull Pokémon", "Pokémon Buffle"], null],
  "magikarp": ["A feeble, pitiful imbecile of a Pokémon that is nonetheless very hardy. Unperturbed by turbid water, it can be found living in all sorts of places.", "Ce Pokémon est si faible que, dans les eaux à forts courants, il se contente de se laisser porter lamentablement.", ["Fish Pokémon", "Pokémon Poisson"], null],
  "gyarados": ["I suspect this Pokémon to be the true identity of a dragon written of in ancient texts, which claimed that it razed an entire village with white-hot beams from its maw.", "Quand il se laisse emporter par la rage, même la plus violente des tempêtes ne peut l’empêcher de détruire tout ce qui l’entoure.", ["Atrocious Pokémon", "Pokémon Terrifiant"], null],
  "lapras": ["Crossing icy seas is no issue for this cold-resistant Pokémon. Its smooth skin is a little cool to the touch.", "Il résiste bien aux très basses températures et peut nager dans des mers glaciales. Sa peau est lisse et légèrement froide au toucher.", ["Transport Pokémon", "Pokémon Transport"], null],
  "ditto": ["When it encounters another ???, it will move faster than normal to duplicate that opponent exactly.", "Quand il rencontre l’un de ses semblables, il s’agite avec plus de vivacité que d’habitude pour adopter exactement la même forme que lui.", ["Transform Pokémon", "Pokémon Morphing"], null],
  "eevee": ["Harbors the potential to evolve into manifold forms. Within ??? lies the key to the mysteries of Pokémon evolution—I'm certain of it.", "L’ADN de ce Pokémon très particulier recèle de nombreuses possibilités d’évolution.", ["Evolution Pokémon", "Pokémon Évolutif"], null],
  "vaporeon": ["Tests show that its cells closely resemble water molecules, which perhaps explains its ability to conceal its form while submerged. I believe the origins of mermaid folklore lie with this Pokémon.", "Sa structure cellulaire est similaire à la composition moléculaire de l’eau. Une fois dans cet élément, il devient indétectable à l’œil nu.", ["Bubble Jet Pokémon", "Pokémon Bulleur"], null],
  "jolteon": ["Bristles its fur into sharp, needlelike points when enraged. One can hear electricity crackle in its breath when it exhales.", "Il se charge d’ions négatifs contenus dans l’air pour envoyer des décharges d’environ 10 000 volts.", ["Lightning Pokémon", "Pokémon Orage"], null],
  "flareon": ["Flames burn within a saclike organ inside this Pokémon. When ??? inhales, these flames grow in intensity, reaching a mighty 3,000 degrees Fahrenheit.", "Il emmagasine de l’air dans sa poche de flammes et le chauffe à une température de 1 700 °C.", ["Flame Pokémon", "Pokémon Flamme"], null],
  "porygon": ["It has no discernible heartbeat and does not seem to draw breath, and yet it appears to function without issue. I cannot even begin to explain this utterly bizarre anomaly.", "Ces dernières années, il s’est rendu très utile dans le cyberespace, qu’il arpente pour s’assurer qu’il n’y a aucune donnée suspecte.", ["Virtual Pokémon", "Pokémon Virtuel"], null],
  "omanyte": ["This Pokémon is a member of an ancient, extinct species. ??? paddles through water with its 10 tentacles, looking like it’s just drifting along.", "Un Pokémon préhistorique aujourd’hui disparu. Il semble flotter lorsqu’il nage en brassant l’eau avec ses dix tentacules.", ["Spiral Pokémon", "Pokémon Spirale"], null],
  "omastar": ["???’s sharp fangs could crush rock, but the Pokémon can attack only the prey that come within reach of its tentacles.", "Ses crocs sont capables de broyer la roche, mais il ne peut s’attaquer qu’aux proies à portée de ses tentacules.", ["Spiral Pokémon", "Pokémon Spirale"], null],
  "kabuto": ["While some say this species has gone extinct, ??? sightings are apparently fairly common in some places.", "On raconte qu’ils se seraient éteints, mais apparemment, on peut souvent en croiser dans une zone particulière.", ["Shellfish Pokémon", "Pokémon Carapace"], null],
  "kabutops": ["The cause behind the extinction of this species is unknown. ??? were aggressive Pokémon that inhabited warm seas.", "Nul ne sait pourquoi il s’est éteint. Ce Pokémon préhistorique féroce vivait dans les mers chaudes.", ["Shellfish Pokémon", "Pokémon Carapace"], null],
  "aerodactyl": ["???’s sawlike fangs can shred skin to tatters—even the skin of Steel-type Pokémon.", "Sa dentition semblable à une scie peut même broyer la peau des Pokémon Acier.", ["Fossil Pokémon", "Pokémon Fossile"], null],
  "snorlax": ["This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.", "L’estomac de ce Pokémon est si résistant qu’il peut même digérer de la nourriture avariée.", ["Sleeping Pokémon", "Pokémon Pionceur"], null],
  "articuno": ["This Pokémon can control ice at will. ??? is said to live in snowy mountains riddled with permafrost.", "Il possède le pouvoir de contrôler la glace. Selon les dires, il vivrait sur les sommets recouverts de neiges éternelles.", ["Freeze Pokémon", "Pokémon Glaciaire"], null],
  "zapdos": ["??? is a legendary bird Pokémon. It’s said that when ??? rubs its feathers together, lightning will fall immediately after.", "On raconte que lorsque ce Pokémon oiseau légendaire fait vibrer ses plumes, le frottement fait tomber la foudre instantanément.", ["Electric Pokémon", "Pokémon Électrique"], null],
  "moltres": ["There are stories of this Pokémon using its radiant, flame-cloaked wings to light up paths for those lost in the mountains.", "On raconte qu’il a sauvé des personnes perdues en montagne en illuminant les sentiers à l’aide de ses splendides ailes flamboyantes.", ["Flame Pokémon", "Pokémon Flamme"], null],
  "dratini": ["This Pokémon was long considered to be no more than a myth. The small lump on a ???’s forehead is actually a horn that’s still coming in.", "On a longtemps douté de l’existence de ce Pokémon. La petite bosse sur son front est en fait sa corne en pleine croissance.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "dragonair": ["This Pokémon gathers power in the orbs on its tail and controls the weather. When enshrouded by an aura, ??? has a mystical appearance.", "Il contrôle la météo en accumulant de l’énergie dans les orbes au bout de sa queue. Sa silhouette nimbée d’une aura lui confère un air mystique.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "dragonite": ["This Pokémon is known as the Sea Incarnate. Figureheads that resemble ??? decorate the bows of many ships.", "On l’appelle « l’avatar de la mer ». Nombreux sont les navires arborant une figure de proue en forme de ???.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "mewtwo": ["Its DNA is almost the same as Mew’s. However, its size and disposition are vastly different.", "Son ADN est presque le même que celui de Mew, mais sa taille et son caractère sont très différents.", ["Genetic Pokémon", "Pokémon Génétique"], null],
  "mew": ["When viewed through a microscope, this Pokémon’s short, fine, delicate hair can be seen.", "À l’aide d’un microscope, on peut distinguer le pelage extrêmement court, fin et délicat de ce Pokémon.", ["New Species Pokémon", "Pokémon Nouveau"], null],
  "chikorita": ["In battle, ??? waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around.", "Lorsqu’il se bat, ??? secoue sa feuille pour tenir son ennemi à distance. Un doux parfum s’en dégage également, apaisant les Pokémon qui se battent et créant une atmosphère agréable et amicale.", ["Leaf Pokémon", "Pokémon Feuille"], null],
  "bayleef": ["???’s neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy.", "Le cou de ??? est entouré de nombreuses feuilles. Dans chacune d’elles se trouve une pousse d’arbre. Le parfum de cette pousse donne la pêche aux personnes qui le sentent.", ["Leaf Pokémon", "Pokémon Feuille"], null],
  "meganium": ["The fragrance of ???’s flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe’s fighting spirit.", "Le parfum de la fleur de ??? apaise et calme les esprits. Pendant les combats, ce Pokémon émet son parfum relaxant pour atténuer l’agressivité de l’ennemi.", ["Herb Pokémon", "Pokémon Herbe"], null],
  "cyndaquil": ["Hails from the Johto region. Though usually curled into a ball due to its timid disposition, it harbors tremendous firepower.", "??? se protège en faisant jaillir des flammes de son dos. Ces flammes peuvent être violentes si le Pokémon est en colère. Cependant, s’il est fatigué, seules quelques flammèches vacillent laborieusement.", ["Fire Mouse Pokémon", "Pokémon Souris Feu"], null],
  "quilava": ["This creature's fur is most mysterious—it is wholly impervious to the burning touch of flame. Should ??? turn its back to you, take heed! Such a posture indicates a forthcoming attack.", "??? garde ses ennemis à distance grâce à l’intensité de ses flammes et à des rafales d’air brûlant. Ce Pokémon utilise son incroyable agilité pour éviter les attaques, tout en enflammant ses ennemis.", ["Volcano Pokémon", "Pokémon Volcan"], null],
  "typhlosion": ["Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui's center.", "??? se cache derrière un chatoyant nuage de chaleur qu’il crée en attisant ses flammes intenses. Ce Pokémon peut générer des rafales explosives qui réduisent tout en cendres.", ["Volcano Pokémon", "Pokémon Volcan"], null],
  "totodile": ["Despite the smallness of its body, ???’s jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury.", "Malgré son tout petit corps, la mâchoire de ??? est très puissante. Parfois, ce Pokémon mordille les gens pour jouer, sans se rendre compte que sa morsure peut gravement blesser quelqu’un.", ["Big Jaw Pokémon", "Pokémon Mâchoire"], null],
  "croconaw": ["Once ??? has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in.", "Une fois que ??? a refermé sa mâchoire sur son ennemi, il est impossible de le faire lâcher prise. Ses crocs sont recourbés comme des hameçons et ne peuvent pas être retirés une fois enfoncés.", ["Big Jaw Pokémon", "Pokémon Mâchoire"], null],
  "feraligatr": ["??? intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.", "??? impressionne ses ennemis en ouvrant son énorme gueule. Pendant les combats, il piétine le sol de ses puissantes pattes arrière avant de charger ses adversaires à pleine vitesse.", ["Big Jaw Pokémon", "Pokémon Mâchoire"], null],
  "sentret": ["When ??? sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this Pokémon becomes separated from its pack, it becomes incapable of sleep due to fear.", "Lorsqu’un ??? dort, un autre monte la garde. La sentinelle réveille les autres au moindre signe de danger. Si un de ces Pokémon est séparé de sa meute, il est incapable de dormir, car il a peur.", ["Scout Pokémon", "Pokémon Espion"], null],
  "furret": ["??? has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this Pokémon is very nimble and fleet.", "??? est très mince. Lorsqu’il est attaqué, il peut s’enfuir en se faufilant habilement dans les recoins étroits. Malgré ses pattes courtes, ce Pokémon est très agile et rapide.", ["Long Body Pokémon", "Pokémon Allongé"], null],
  "hoothoot": ["It begins to hoot at the same time every day. Some Trainers use them in place of clocks.", "Il hulule chaque jour aux mêmes moments. Certains Dresseurs s’en servent comme d’une montre.", ["Owl Pokémon", "Pokémon Hibou"], null],
  "noctowl": ["When it needs to think, it rotates its head 180 degrees to sharpen its intellectual power.", "Quand il réfléchit, il tourne sa tête sur 180 degrés pour optimiser son mode de pensée.", ["Owl Pokémon", "Pokémon Hibou"], null],
  "ledyba": ["These very cowardly Pokémon join together and use Reflect to protect their nest.", "Extrêmement timide, ce Pokémon défend le nid qu’il partage avec ses congénères en utilisant Protection.", ["Five Star Pokémon", "Pokémon 5 Étoiles"], null],
  "ledian": ["It flies through the night sky, sprinkling sparkly dust. According to some, if that dust sticks to you, good things will happen to you.", "Il vole dans le ciel nocturne en répandant une poudre scintillante. Si elle vous touche, quelque chose de positif devrait bientôt vous arriver.", ["Five Star Pokémon", "Pokémon 5 Étoiles"], null],
  "spinarak": ["Although the poison from its fangs isn’t that strong, it’s potent enough to weaken prey that gets caught in its web.", "Le poison contenu dans les mandibules de ce Pokémon n’est pas très violent, mais il suffit à immobiliser les proies piégées dans sa toile.", ["String Spit Pokémon", "Pokémon Crache Fil"], null],
  "ariados": ["It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively.", "Il capture ses proies en projetant un fil qu’il sécrète. À la nuit tombée, il quitte sa toile et part chasser activement.", ["Long Leg Pokémon", "Pokémon Long-Patte"], null],
  "crobat": ["Its hind limbs have become another set of wings. ??? expertly maneuvers its four wings to dart in exquisite fashion through even the most confined caves without losing any speed.", "Il vole en contrôlant librement ses quatre ailes et peut se déplacer sans avoir besoin de ralentir, même dans les grottes étroites.", ["Bat Pokémon", "Pokémon Chovsouris"], null],
  "chinchou": ["On the dark ocean floor, its only means of communication is its constantly flashing lights.", "Au plus profond de l’océan, son seul moyen de communication est la lumière de ses antennes, qui clignotent constamment.", ["Angler Pokémon", "Pokémon Poisson"], null],
  "lanturn": ["This Pokémon flashes a bright light that blinds its prey. This creates an opening for it to deliver an electrical attack.", "Il dégage une vive lumière pour éblouir ses proies, puis leur inflige un choc électrique bien senti.", ["Light Pokémon", "Pokémon Lumière"], null],
  "pichu": ["??? stores electricity in the sacs on its cheeks but discharges it inadvertently when agitated or excited. Being yet immature, the Pokémon's handling of electricity is rather inept.", "Les poches électriques de ses joues sont très petites. Lorsqu’elles sont surchargées, il s’électrocute lui-même.", ["Tiny Mouse Pokémon", "Pokémon Minisouris"], null],
  "cleffa": ["In silhouette, they resemble twinkling starlight. When shooting stars rain from the night sky, ??? gather in numbers and dance as though they are indeed incarnations of the stars.", "Il ressemble un peu à une étoile. On suppose qu’il est venu sur terre accroché à une météorite.", ["Star Shape Pokémon", "Pokémon Étoile"], null],
  "igglybuff": ["Taking advantage of the softness of its body, ??? moves as if bouncing. Its body turns a deep pink when its temperature rises.", "Il se déplace en faisant rebondir son corps tout mou. Lorsque sa température corporelle augmente, il devient rose foncé.", ["Balloon Pokémon", "Pokémon Bouboule"], null],
  "togepi": ["This ovate creature is frequently mistaken for a moving egg when encountered out in the fields or in the mountains. Its guileless smile soothes the soul.", "C’est un symbole de chance. On dit que sa coquille est remplie de joie.", ["Spike Ball Pokémon", "Pokémon Balle Pic"], null],
  "togetic": ["No records exist of ??? being seen in the wilds. Rumors abound that it evolves under the loving care of a trusted human companion, upon whom the Pokémon then bestows great joy.", "Ce Pokémon est capable de léviter sans battre des ailes. Il est vite démoralisé s’il n’est pas en compagnie de gens sympathiques.", ["Happiness Pokémon", "Pokémon Bonheur"], null],
  "natu": ["Because its wings aren’t yet fully grown, it has to hop to get around. It is always staring at something.", "Ses ailes ne sont pas assez développées donc il ne peut se déplacer qu’en sautillant. Il fixe toujours quelque chose du regard.", ["Tiny Bird Pokémon", "Pokémon Minoiseau"], null],
  "xatu": ["This odd Pokémon can see both the past and the future. It eyes the sun’s movement all day.", "Capable de voir le passé et l’avenir, ce Pokémon mystérieux consacre toutes ses journées à observer la course du soleil.", ["Mystic Pokémon", "Pokémon Mystique"], null],
  "mareep": ["Rubbing its fleece generates electricity. You’ll want to pet it because it’s cute, but if you use your bare hand, you’ll get a painful shock.", "Il a beau être mignon, sa laine génère de l’électricité quand on la frotte. Tentez de le caresser, et il vous mettra vite au courant !", ["Wool Pokémon", "Pokémon Laine"], null],
  "flaaffy": ["It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches.", "Il accumule de l’électricité dans sa toison duveteuse. Il en a tellement stocké qu’il en a perdu sa laine par endroits.", ["Wool Pokémon", "Pokémon Laine"], null],
  "ampharos": ["Its tail shines bright and strong. It has been prized since long ago as a beacon for sailors.", "Sa queue brille d’une lumière éclatante. Depuis des temps très anciens, il est vénéré comme le guide des marins.", ["Light Pokémon", "Pokémon Lumière"], null],
  "bellossom": ["??? gather at times and appear to dance. They say that the dance is a ritual to summon the sun.", "Les ??? se réunissent parfois pour danser. On pense que c’est un rituel pour invoquer le soleil.", ["Flower Pokémon", "Pokémon Fleur"], null],
  "marill": ["Even after ??? swims in a cold sea, its water- repellent fur dries almost as soon as ??? leaves the water. That’s why this Pokémon is never cold.", "Sa fourrure est hydrophobe, si bien qu’elle sèche en un instant. Il n’a donc jamais froid, même lorsqu’il sort d’une mer glaciale.", ["Aqua Mouse Pokémon", "Pokémon Aquasouris"], null],
  "azumarill": ["These Pokémon create air-filled bubbles. When Azurill play in rivers, ??? will cover them with these bubbles.", "Il crée des bulles d’air dont il enveloppe gentiment les Azurill venus jouer dans la rivière.", ["Aqua Rabbit Pokémon", "Pokémon Aqualapin"], null],
  "sudowoodo": ["Though it pretends to be a tree, it fails to fool even children. To the touch, its body feels more like rock than tree bark. ???'s extreme aversion to water merits special note.", "Il se déguise en arbre pour éviter de se faire attaquer. Il déteste l’eau et se cache par temps de pluie.", ["Imitation Pokémon", "Pokémon Imitation"], null],
  "politoed": ["The cry of a male is louder than that of a female. Male ??? with deep, menacing voices find more popularity with the opposite gender.", "Le cri des mâles est plus puissant que celui des femelles, qui préfèrent les voix fortes et intimidantes.", ["Frog Pokémon", "Pokémon Grenouille"], null],
  "hoppip": ["This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, ??? links its leaves with other ??? to prepare against being blown away.", "Ce Pokémon flotte à la dérive, porté par le vent. S’il sent qu’un vent très fort approche, ??? attache ses feuilles aux autres ??? pour ne pas être emporté par la bourrasque.", ["Cottonweed Pokémon", "Pokémon Pissenlit"], null],
  "skiploom": ["???’s flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer.", "La fleur de ??? éclot lorsque la température atteint 18 °C. L’ouverture de la fleur change en fonction de la température. Certaines personnes se servent de ce Pokémon comme d’un thermomètre.", ["Cottonweed Pokémon", "Pokémon Pissenlit"], null],
  "jumpluff": ["??? rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating.", "??? traverse la mer, porté par les vents, pour découvrir de nouveaux territoires. Ce Pokémon se rapproche du sol quand le vent est trop froid.", ["Cottonweed Pokémon", "Pokémon Pissenlit"], null],
  "aipom": ["This treetop dweller possesses a tail as dexterous as a hand. Ancient writings describe this Pokémon as a one-armed oddity.", "Il guette ses proies depuis la cime des arbres. Quand il aperçoit un Croquine, son mets préféré, il se jette dessus.", ["Long Tail Pokémon", "Pokémon Longqueue"], null],
  "sunkern": ["??? tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew.", "??? essaie de bouger le moins possible. C’est parce qu’il veut conserver tous les nutriments qu’il stocke dans son corps pour son évolution. Il ne mange pas, ne subsistant que grâce à la rosée matinale.", ["Seed Pokémon", "Pokémon Graine"], null],
  "sunflora": ["??? converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night.", "??? convertit l’énergie solaire en nutriments. Il remue activement pendant la journée, quand il fait chaud. Il redevient immobile dès que le soleil se couche.", ["Sun Pokémon", "Pokémon Soleil"], null],
  "yanma": ["Its frail wings are so thin that one can see clear through them. However, during flight these wings exhibit the power to churn air with force enough to launch a house skyward.", "??? a un champ de vision de 360 degrés sans avoir besoin de bouger les yeux. Il vole incroyablement bien et peut faire des figures acrobatiques. Ce Pokémon descend en piqué sur ses proies.", ["Clear Wing Pokémon", "Pokémon Translaile"], null],
  "wooper": ["When walking on land, it covers its body with a poisonous film that keeps its skin from dehydrating.", "Lorsqu’il est sur la terre ferme, il couvre son corps d’un voile toxique qui le protège de la déshydratation.", ["Water Fish Pokémon", "Pokémon Poisson"], null],
  "quagsire": ["Its body is always slimy. It often bangs its head on the river bottom as it swims but seems not to care.", "Il est toujours gluant. Quand il nage, il se cogne souvent la tête au fond des rivières, mais semble s’en moquer.", ["Water Fish Pokémon", "Pokémon Poisson"], null],
  "espeon": ["Wields an arcane power with which it can predict the weather and even people's thoughts. When bathed in sunshine, the scarlet orb on its brow glows and builds energy.", "Le joyau sur le front de ??? projette des ondes psychiques en combat, et s’obscurcit quand il est à bout de force.", ["Sun Pokémon", "Pokémon Soleil"], null],
  "umbreon": ["It is most active in the wee hours of the night, when moonlight bathes the land. Its large eyes can pierce the darkness and perceive prey with absolute clarity.", "Les nuits de pleine lune, ou s’il est agité, les anneaux sur sa peau se mettent à briller.", ["Moonlight Pokémon", "Pokémon Lune"], null],
  "murkrow": ["Widely shunned as a bearer of ill fortune. Upon crossing paths with this creature, I've been told one must chant ”Workrum, Workrum—bad luck, don't come” as a protective incantation.", "Il cherche des objets brillants pour son chef. Sa réputation d’oiseau de mauvais augure lui vaut la haine de nombreuses personnes.", ["Darkness Pokémon", "Pokémon Obscurité"], null],
  "slowking": ["??? can solve any problem presented to it, but no one can understand a thing ??? says.", "Il est capable de résoudre tous les problèmes qu’on lui présente, mais personne ne parvient à comprendre ce qu’il dit.", ["Royal Pokémon", "Pokémon Royal"], null],
  "misdreavus": ["It conceals itself in darkness, sending chills up travelers' spines with its childlike weeping. As it observes the frightened travelers with glee, the red orbs upon its chest let off an eerie light.", "Il adore faire peur aux humains en imitant leurs pleurs, et n’apprécie guère ceux qui ne se laissent pas intimider.", ["Screech Pokémon", "Pokémon Strident"], null],
  "unown": ["It is hard to believe these strangely shaped Pokémon are truly living creatures. I've pointed out that the species' many forms resemble writing from other lands; no one will take me seriously.", "Ce Pokémon a la forme d’un caractère d’écriture antique. Personne ne sait si ces écritures antiques sont apparues avant les ??? ou le contraire. Des études sont en cours, mais aucun résultat n’a été annoncé.", ["Symbol Pokémon", "Pokémon Symbolique"], null],
  "wobbuffet": ["To keep its pitch-black tail hidden, it lives quietly in the darkness. It is never first to attack.", "Il vit discrètement dans l’obscurité pour cacher sa queue noire. Il n’attaque jamais en premier.", ["Patient Pokémon", "Pokémon Patient"], null],
  "girafarig": ["???’s rear head contains a tiny brain that is too small for thinking. However, the rear head doesn’t need to sleep, so it can keep watch over its surroundings 24 hours a day.", "La tête à l’arrière de ??? abrite un cerveau trop petit pour penser. En revanche, cette tête arrière n’a pas besoin de dormir, ce qui lui permet de monter la garde tout le temps.", ["Long Neck Pokémon", "Pokémon Long-Cou"], null],
  "pineco": ["It sticks tree bark to itself with its saliva, making itself thicker and larger. Elderly ??? are ridiculously huge.", "Il grandit en utilisant sa salive pour coller l’écorce des arbres sur son corps. Un ??? âgé peut prendre des proportions démesurées.", ["Bagworm Pokémon", "Pokémon Ver Caché"], null],
  "forretress": ["In the moment that it gulps down its prey, the inside of its shell is exposed, but to this day, no one has ever seen that sight.", "On ne peut voir l’intérieur de sa carapace que lorsqu’il engloutit sa nourriture, mais il est si rapide que personne n’a encore jamais réussi.", ["Bagworm Pokémon", "Pokémon Ver Caché"], null],
  "dunsparce": ["The nests ??? live in are mazes of tunnels. They never get lost in their own nests—they can tell where they are by the scent of the dirt.", "Bien que son nid ressemble à un labyrinthe, il ne s’y perd jamais, car il se repère grâce à l’odeur de la terre.", ["Land Snake Pokémon", "Pokémon Serpent"], null],
  "gligar": ["Its tail is tipped by a thick, horrible stinger. To bring down prey, it will first obscure their vision by covering their faces with its body, and then it will use the stinger to inject them with venom.", "??? plane dans les airs sans un bruit, comme s’il glissait. Ce Pokémon s’accroche au visage de son ennemi grâce aux serres de ses pattes arrière et aux pinces de ses pattes avant, et pique avec son dard empoisonné.", ["Fly Scorpion Pokémon", "Pokémon Scorpivol"], null],
  "steelix": ["This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.", "On pense que son corps s’est transformé à force d’avaler le fer contenu dans la terre en creusant.", ["Iron Snake Pokémon", "Pokémon Serpenfer"], null],
  "snubbull": ["In contrast to its appearance, it’s quite timid. When playing with other puppy Pokémon, it sometimes gets bullied.", "Malgré les apparences, c’est un grand timide qui fait souvent l’objet de railleries quand il se trouve au milieu d’un groupe de Pokémon Chiot.", ["Fairy Pokémon", "Pokémon Fée"], null],
  "granbull": ["Although it’s popular with young people, ??? is timid and sensitive, so it’s totally incompetent as a watchdog.", "Les jeunes gens en sont fous, mais sa timidité et sa grande délicatesse en font un piètre Pokémon de garde.", ["Fairy Pokémon", "Pokémon Fée"], null],
  "qwilfish": ["Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of ??? lives in other regions.", "Ses petites épines étaient autrefois des écailles. Elles sécrètent des toxines pouvant faire perdre connaissance.", ["Balloon Pokémon", "Pokémon Bouboule"], null],
  "scizor": ["Evolved by way of a curious item. The shell covering its body has been shown to be stronger than forged steel.", "Malgré son corps fin, sa puissance de frappe est prodigieuse, car même ses muscles sont composés de métal.", ["Pincer Pokémon", "Pokémon Pince"], null],
  "shuckle": ["The berries stored in its vaselike shell eventually become a thick, pulpy juice.", "Les Baies qu’il conserve dans sa carapace en forme d’urne se changent en jus onctueux après un certain temps.", ["Mold Pokémon", "Pokémon Pourri"], null],
  "heracross": ["This Pokémon has an unparalleled horn. ??? itself demonstrates tremendous power—it's capable of throwing several people trained in the traditional arts of war at once.", "Ce Pokémon est fier de sa force colossale qui lui permet de soulever cent fois son propre poids avec facilité.", ["Single Horn Pokémon", "Pokémon Unicorne"], null],
  "sneasel": ["Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in ???'s grasp.", "Un Pokémon aussi cruel que fourbe. Il se glisse dans le nid des autres Pokémon en leur absence pour dérober leurs Œufs.", ["Sharp Claw Pokémon", "Pokémon Grifacérée"], null],
  "teddiursa": ["It licks its paws because of the sweet honey that has soaked into them. It is cunning, stealing into the nests of Combee and taking for itself the honey that the Combee have amassed.", "Ce Pokémon aime se lécher les paumes quand elles sont encore pleines de miel. ??? concocte son propre miel en mélangeant les fruits et le pollen récolté par Dardargnan.", ["Little Bear Pokémon", "Pokémon Mini Ours"], null],
  "ursaring": ["When the cold season arrives in Hisui, this Pokémon will wander fields and mountains alike in search of its favorite berries. ???'s hunger during this time makes it a ferocious danger.", "On dit que les ??? trouvent leur nourriture dans les cours d’eau et les grands arbres des forêts où ils habitent. Ce Pokémon erre dans la forêt toute la journée pour chercher de la nourriture.", ["Hibernator Pokémon", "Pokémon Hibernant"], null],
  "slugma": ["??? does not have any blood in its body. Instead, intensely hot magma circulates throughout this Pokémon’s body, carrying essential nutrients and oxygen to its organs.", "Les veines de ??? ne contiennent pas de sang. Au lieu de ça, du magma en fusion circule dans le corps de ce Pokémon, apportant les nutriments et l’oxygène nécessaires à ses organes.", ["Lava Pokémon", "Pokémon Lave"], null],
  "magcargo": ["???’s body temperature is approximately 18,000 degrees Fahrenheit. Water is vaporized on contact. If this Pokémon is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog.", "La température de ??? est d’environ 10 000 °C. L’eau s’évapore à son contact. Si ce Pokémon se retrouve sous la pluie, les gouttes d’eau forment de la vapeur et couvrent la zone de brouillard.", ["Lava Pokémon", "Pokémon Lave"], null],
  "swinub": ["??? excels at sniffing out mushrooms buried beneath grass or snow. Since ancient times, the people of Hisui have often relied upon this skill.", "S’il sent une odeur attrayante, il fonce la tête la première pour trouver d’où elle vient.", ["Pig Pokémon", "Pokémon Cochon"], null],
  "piloswine": ["The long fur of this Pokémon covers its eyes, ears, and even limbs, allowing ??? to resist harshly frigid conditions. The Pokémon's white tusks can be used to defeat its enemies.", "Bien qu’il soit pourvu de pattes courtes, ses sabots larges et pointus l’empêchent de glisser sur la glace.", ["Swine Pokémon", "Pokémon Porc"], null],
  "corsola": ["These Pokémon live in warm seas. In prehistoric times, many lived in the oceans around the Galar region as well.", "Ces Pokémon habitués des mers chaudes se trouvaient autrefois en masse sur les côtes de Galar.", ["Coral Pokémon", "Pokémon Corail"], null],
  "remoraid": ["Spits water from its mouth with incredible accuracy. It captures Burmy by shooting them down off the branches from which they dangle.", "À l’aide de sa nageoire dorsale en forme de ventouse, il s’accroche sous un Démanta pour récupérer ses restes.", ["Jet Pokémon", "Pokémon Jet"], null],
  "octillery": ["While ??? still shoots water from its mouth, the drastic anatomical difference between it and Remoraid meant that for a long time, no one believed the former evolved from the latter.", "Il capture ses ennemis avec ses tentacules et les écrase ensuite avec sa tête dure comme la pierre.", ["Jet Pokémon", "Pokémon Jet"], null],
  "delibird": ["It has a generous habit of sharing its food with people and Pokémon, so it’s always scrounging around for more food.", "Ce Pokémon partage facilement son repas avec d’autres Pokémon et avec des humains, ce qui l’oblige à constamment courir après la nourriture.", ["Delivery Pokémon", "Pokémon Livraison"], null],
  "mantine": ["This calm and gentle Pokémon swims gracefully through the sea. After building speed, it can leap out of the water. It is often misidentified as a bird Pokémon due to this behavior.", "Il nage paisiblement, sans se soucier des Rémoraid qui s’agrippent à lui pour lui voler ses restes.", ["Kite Pokémon", "Pokémon Cervolant"], null],
  "skarmory": ["People fashion swords from ???’s shed feathers, so this Pokémon is a popular element in heraldic designs.", "Ce Pokémon orne souvent les blasons, car les plumes qu’il perd sont utilisées pour forger des épées.", ["Armor Bird Pokémon", "Pokémon Armoiseau"], null],
  "houndour": ["They make repeated eerie howls before dawn to call attention to their pack.", "Si ses congénères et lui poussent de sinistres hurlements avant l’aube, c’est pour signaler leur présence à tout le monde.", ["Dark Pokémon", "Pokémon Sombre"], null],
  "houndoom": ["Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it.", "Ceux qui le craignaient jadis lui ont donné le surnom de « messager de la Faucheuse » à cause de son hurlement sinistre si particulier.", ["Dark Pokémon", "Pokémon Sombre"], null],
  "kingdra": ["Scales shed by this Pokémon have such a splendorous gleam to them that they’ve been given to royalty as gifts.", "Les écailles qui se détachent de son corps brillent d’un éclat si élégant et si intense qu’on les offre aux familles royales.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "phanpy": ["??? uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These Pokémon can be seen drying their soaking-wet bodies at the edge of water.", "??? utilise sa petite trompe pour se doucher. Quand plusieurs d’entre eux se réunissent, ils s’arrosent joyeusement. On peut souvent voir ces Pokémon se sécher au bord de l’eau.", ["Long Nose Pokémon", "Pokémon Long-Nez"], null],
  "donphan": ["If ??? were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the Pokémon helps clear rock and mud slides that block mountain trails.", "Si ??? décidait de charger, il pourrait détruire une maison. Grâce à sa force étonnante, ce Pokémon peut aider à déplacer les rochers et les coulées de boue qui bloquent les chemins de montagne.", ["Armor Pokémon", "Pokémon Armure"], null],
  "porygon2": ["A bizarre item caused this Pokémon to evolve. While it now exhibits many new gestures and expressions, its biology remains inscrutable.", "Depuis qu’on l’a doté d’une intelligence artificielle, il parle un langage mystérieux que seuls ses congénères comprennent.", ["Virtual Pokémon", "Pokémon Virtuel"], null],
  "stantler": ["Its strangely shaped antlers have the power to bewitch those who see them. Medicine made by grinding up the black orbs from fallen antlers is an effective treatment for insomnia.", "Les superbes bois de ??? étaient vendus très cher comme œuvres d’art. Ce Pokémon fut chassé et l’espèce proche de l’extinction à cause des gens qui recherchaient leurs précieux bois.", ["Big Horn Pokémon", "Pokémon Maxi Corne"], null],
  "smeargle": ["It draws symbols with the fluid that oozes from the tip of its tail. Depending on the symbol, ??? fanatics will pay big money for them.", "Il se sert du liquide qui sort de sa queue pour dessiner sa marque. Ses fans s’arrachent ses plus beaux tracés à prix d’or.", ["Painter Pokémon", "Pokémon Peintre"], null],
  "tyrogue": ["Even though it is small, it can’t be ignored because it will slug any handy target without warning.", "Même s’il est petit, il vaut mieux ne pas l’ignorer : quand il trouve un adversaire à sa hauteur, il frappe fort et souvent sans prévenir.", ["Scuffle Pokémon", "Pokémon Bagarreur"], null],
  "hitmontop": ["After doing a handstand to throw off the opponent’s timing, it presents its fancy kick moves.", "Après avoir effectué un poirier visant à désorienter son adversaire, il lui assène des coups de pied furieux.", ["Handstand Pokémon", "Pokémon Poirier"], null],
  "smoochum": ["This is a very curious Pokémon. ??? decides what it likes and dislikes by touching things with its lips.", "Ce Pokémon très curieux touche tout et n’importe quoi avec ses lèvres pour déterminer ce qu’il aime et ce qu’il déteste.", ["Kiss Pokémon", "Pokémon Bisou"], null],
  "elekid": ["They generate electricity by spinning their arms. During a thunderstorm, if one hears the lively voices of children out in the wilderness, what one is actually hearing are the voices of ???.", "Il a encore du mal à emmagasiner l’électricité. Pour s’en nourrir, il se faufile dans les maisons à la recherche de prises électriques.", ["Electric Pokémon", "Pokémon Électrique"], null],
  "magby": ["This Pokémon lives in volcanic areas. With each breath, sparks spurt from its mouth and nose. When ??? is in good health, its flames gain a yellow tint.", "Il vit près des volcans. À la fin de la journée, il se détend dans un bon bain de magma.", ["Live Coal Pokémon", "Pokémon Charbon"], null],
  "miltank": ["This Pokémon needs to be milked every day, or else it will fall ill. The flavor of ??? milk changes with the seasons.", "Sa santé décline si on ne le trait pas tous les jours. Le goût de son lait varie selon la saison.", ["Milk Cow Pokémon", "Pokémon Vachalait"], null],
  "blissey": ["A kindhearted Pokémon that will care for any sick person or Pokémon until their health improves. The eggs it lays are delicious and bring good fortune to those who eat them.", "Il pond d’étranges œufs remplis de bonheur. On raconte que quiconque en mange un devient aimable envers tout le monde.", ["Happiness Pokémon", "Pokémon Bonheur"], null],
  "raikou": ["??? embodies the speed of lightning. The roars of this Pokémon send shock waves shuddering through the air and shake the ground as if lightning bolts had come crashing down.", "??? incarne la vitesse de l’éclair. Les rugissements de ce Pokémon libèrent des ondes de choc provenant du ciel et frappant le sol avec la puissance de la foudre.", ["Thunder Pokémon", "Pokémon Foudre"], null],
  "entei": ["??? embodies the passion of magma. This Pokémon is thought to have been born in the eruption of a volcano. It sends up massive bursts of fire that utterly consume all that they touch.", "??? incarne la colère du magma. On pense que ce Pokémon est né suite à l’éruption d’un volcan. Il peut envoyer d’énormes jets de flammes qui calcinent tout ce qu’ils touchent.", ["Volcano Pokémon", "Pokémon Volcan"], null],
  "suicune": ["??? embodies the compassion of a pure spring of water. It runs across the land with gracefulness. This Pokémon has the power to purify dirty water.", "??? incarne la tranquillité d’une source d’eau pure. Il parcourt les plaines avec grâce. Ce Pokémon a le pouvoir de purifier l’eau.", ["Aurora Pokémon", "Pokémon Aurore"], null],
  "larvitar": ["It feeds on soil. After it has eaten a large mountain, it will fall asleep so it can grow.", "Il vit en se nourrissant de terre. Après avoir dévoré une montagne, il s’endort et entame sa croissance.", ["Rock Skin Pokémon", "Pokémon Peaupierre"], null],
  "pupitar": ["It will not stay still, even while it’s a pupa. It already has arms and legs under its solid shell.", "Malgré son état de chrysalide, il ne reste pas immobile. Sous sa solide carapace, ses pattes sortent déjà.", ["Hard Shell Pokémon", "Pokémon Carapadure"], null],
  "tyranitar": ["The quakes caused when it walks make even great mountains crumble and change the surrounding terrain.", "Son pas est si lourd qu’il fait trembler le sol et s’écrouler même les plus grandes montagnes, ce qui altère la topographie de la zone.", ["Armor Pokémon", "Pokémon Armure"], null],
  "lugia": ["???’s wings pack devastating power—a light fluttering of its wings can blow apart regular houses. As a result, this Pokémon chooses to live out of sight deep under the sea.", "Les ailes de ??? renferment une puissance dévastatrice. Un simple battement de ses ailes peut détruire de petites maisons. Du coup, ce Pokémon a choisi de vivre loin de tout, dans les profondeurs océaniques.", ["Diving Pokémon", "Pokémon Plongeon"], null],
  "ho-oh": ["???’s feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This Pokémon is said to live at the foot of a rainbow.", "Les plumes de ??? brillent de sept couleurs selon l’orientation de son corps par rapport à la lumière. On raconte que ces plumes portent bonheur. On dit aussi que ce Pokémon vit au pied d’un arc-en-ciel.", ["Rainbow Pokémon", "Pokémon Arcenciel"], null],
  "celebi": ["This Pokémon traveled through time to come from the future. It bolsters grass and trees with its own strength, and it can heal wounds, too.", "Ce Pokémon venu du futur soigne les blessures et donne de la force aux plantes.", ["Time Travel Pokémon", "Pokémon Temporel"], null],
  "treecko": ["??? is cool, calm, and collected—it never panics under any situation. If a bigger foe were to glare at this Pokémon, it would glare right back without conceding an inch of ground.", "??? est cool, calme et serein. Il ne panique jamais, quelle que soit la situation. Quand un ennemi plus gros que lui lui lance un regard de défi, ce Pokémon reste stoïque et ne cède pas un centimètre de terrain.", ["Wood Gecko Pokémon", "Pokémon Bois Gecko"], null],
  "grovyle": ["This Pokémon adeptly flies from branch to branch in trees. In a forest, no Pokémon can ever hope to catch a fleeing ??? however fast they may be.", "Ce Pokémon vole de branche en branche avec brio. En forêt, aucun Pokémon, même le plus rapide, ne peut espérer attraper un ??? qui s’enfuit.", ["Wood Gecko Pokémon", "Pokémon Bois Gecko"], null],
  "sceptile": ["??? has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This Pokémon raises the trees in a forest with loving care.", "??? a des graines qui lui poussent sur le dos. On dit qu’elles regorgent de nutriments qui revitalisent les arbres. Ce Pokémon s’occupe des forêts avec amour.", ["Forest Pokémon", "Pokémon Forêt"], null],
  "torchic": ["??? has a place inside its body where it keeps its flame. Give it a hug—it will be glowing with warmth. This Pokémon is covered all over by a fluffy coat of down.", "??? dispose d’un endroit dans son corps pour stocker sa flamme. Si on lui fait un gros câlin, sa flamme s’illumine chaleureusement. Ce Pokémon est couvert d’un duvet très doux.", ["Chick Pokémon", "Pokémon Poussin"], null],
  "combusken": ["??? battles with the intensely hot flames it spews from its beak and with outstandingly destructive kicks. This Pokémon’s cry is very loud and distracting.", "??? combat grâce aux flammes ardentes qu’il crache de son bec et à ses coups de pied destructeurs. Le cri de ce Pokémon est très puissant et très gênant pour l’adversaire.", ["Young Fowl Pokémon", "Pokémon Poulet"], null],
  "blaziken": ["??? has incredibly strong legs—it can easily clear a 30-story building in one leap. This Pokémon’s blazing punches leave its foes scorched and blackened.", "??? a des jambes incroyablement puissantes. Il peut sauter par-dessus un immeuble de trente étages. Les coups de poing enflammés de ce Pokémon peuvent carboniser ses ennemis.", ["Blaze Pokémon", "Pokémon Ardent"], null],
  "mudkip": ["In water, ??? breathes using the gills on its cheeks. If it is faced with a tight situation in battle, this Pokémon will unleash its amazing power—it can crush rocks bigger than itself.", "Sous l’eau, ??? peut respirer grâce aux branchies sur ses joues. S’il se retrouve en difficulté pendant un combat, ce Pokémon déchaîne ses pouvoirs incroyables. Il peut détruire des rochers plus gros que lui.", ["Mud Fish Pokémon", "Pokémon Poissonboue"], null],
  "marshtomp": ["??? is much faster at traveling through mud than it is at swimming. This Pokémon’s hindquarters exhibit obvious development, giving it the ability to walk on just its hind legs.", "??? est bien plus rapide dans la boue que dans l’eau. L’arrière-train de ce Pokémon est particulièrement développé, ce qui lui donne la capacité de marcher sur ses pattes arrière.", ["Mud Fish Pokémon", "Pokémon Poissonboue"], null],
  "swampert": ["??? predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself.", "??? peut prédire l’arrivée des tempêtes en utilisant ses nageoires pour sentir les variations dans les vagues et les marées. Si une tempête s’approche, il empile des rochers pour protéger son habitat.", ["Mud Fish Pokémon", "Pokémon Poissonboue"], null],
  "poochyena": ["??? is an omnivore—it will eat anything. A distinguishing feature is how large its fangs are compared to its body. This Pokémon tries to intimidate its foes by making the hair on its tail bristle out.", "??? est omnivore. Il mange de tout. Ses crocs sont très gros, comparés à son corps. Ce Pokémon essaie d’intimider ses ennemis en hérissant les poils de sa queue.", ["Bite Pokémon", "Pokémon Morsure"], null],
  "mightyena": ["??? travel and act as a pack in the wild. The memory of its life in the wild compels the Pokémon to obey only those Trainers that it recognizes to possess superior skill.", "Les ??? vivent et se déplacent en meute. Leurs réminiscences de la vie sauvage les poussent à n’obéir qu’aux Dresseurs qu’ils considèrent comme réellement talentueux.", ["Bite Pokémon", "Pokémon Morsure"], null],
  "zigzagoon": ["??? that adapted to regions outside Galar acquired this appearance. If you’ve lost something, this Pokémon can likely find it.", "Le ??? de Galar a adopté cette forme dans les autres régions. Il est très doué pour dénicher des choses.", ["Tiny Raccoon Pokémon", "Pokémon Petit Raton"], null],
  "linoone": ["It uses its explosive speed and razor-sharp claws to bring down prey. Running along winding paths is not its strong suit.", "Il se sert de sa force de propulsion et de ses griffes aiguisées pour achever ses proies. Il a du mal à courir sur les routes sinueuses.", ["Rushing Pokémon", "Pokémon Fonceur"], null],
  "wurmple": ["Likes sap and is abundant in the wild. Why it evolves into various different forms is unknown. One cannot tell from a ???'s appearance which form it will take when it evolves.", "??? est la proie de Hélédelle. Ce Pokémon essaie de résister en dirigeant les pointes de son dos vers le prédateur. Il affaiblit son ennemi en lui injectant du poison.", ["Worm Pokémon", "Pokémon Ver"], null],
  "silcoon": ["Wraps itself in thin strings of silk while it stores energy for evolution. It can't extend its limbs and its movement is slow, but its eyes keep a sharp lookout—??? is always on guard.", "On pensait qu’??? pouvait résister à la faim et ne consommait rien avant son évolution. On sait maintenant que ce Pokémon étanche sa soif en récupérant l’eau de pluie déposée sur sa soie.", ["Cocoon Pokémon", "Pokémon Cocon"], null],
  "beautifly": ["A colorful and incredibly beautiful but also greedy Pokémon. In an effort to keep its favorite food all to itself, it will chase away Combee as they try to gather nectar.", "??? a une longue trompe en spirale, particulièrement pratique pour récupérer le pollen des fleurs. Ce Pokémon se laisse porter par les vents printaniers pendant qu’il butine.", ["Butterfly Pokémon", "Pokémon Papillon"], null],
  "cascoon": ["The silk coating its body is thin but sufficiently strong. ???'s silk has a luster and texture superior to that of Silcoon's, and clothes made using ??? silk are regarded as top-notch.", "Lorsqu’il est attaqué, ??? reste immobile, même s’il a très mal. En effet, s’il bougeait, son corps serait affaibli lors de son évolution. En revanche, ce Pokémon n’oubliera pas la douleur endurée.", ["Cocoon Pokémon", "Pokémon Cocon"], null],
  "dustox": ["Tends to be drawn to bonfires on dark nights. Difficult to chase away from settlements because of the way it scatters highly toxic scales.", "Lorsque ??? bat des ailes, une légère poussière se répand. Cette poussière est en fait un puissant poison capable de mettre au tapis un boxeur professionnel. Ce Pokémon cherche sa nourriture avec ses antennes, comme un radar.", ["Poison Moth Pokémon", "Pokémon Papipoison"], null],
  "lotad": ["Its leaf grew too large for it to live on land. That is how it began to live floating in the water.", "Sa feuille est devenue si grande et si lourde qu’il doit vivre en flottant sur l’eau.", ["Water Weed Pokémon", "Pokémon Aquaplante"], null],
  "lombre": ["It lives at the water’s edge where it is sunny. It sleeps on a bed of water grass by day and becomes active at night.", "Il vit au bord de l’eau dans les endroits ensoleillés. Il s’endort sur un tas d’algues dans la journée et ne se lève qu’à la nuit tombée.", ["Jolly Pokémon", "Pokémon Jovial"], null],
  "ludicolo": ["If it hears festive music, it begins moving in rhythm in order to amplify its power.", "Il bouge son corps sur un rythme entraînant pour décupler ses forces.", ["Carefree Pokémon", "Pokémon Insouciant"], null],
  "seedot": ["It attaches itself to a tree branch using the top of its head. Strong winds can sometimes make it fall.", "Il se suspend aux branches par l’extrémité de sa tête. Il arrive qu’une bourrasque le fasse tomber.", ["Acorn Pokémon", "Pokémon Gland"], null],
  "nuzleaf": ["They live in holes bored in large trees. The sound of ???’s grass flute fills listeners with dread.", "Il vit dans les trous des grands arbres. Le sifflement qu’il produit avec sa feuille suffit à remplir ses adversaires d’effroi.", ["Wily Pokémon", "Pokémon Malin"], null],
  "shiftry": ["It lives quietly in the deep forest. It is said to create chilly winter winds with the fans it holds.", "Il vit caché au fond des forêts. On raconte qu’il fait souffler la bise lorsqu’il agite ses grands éventails.", ["Wicked Pokémon", "Pokémon Malveillant"], null],
  "taillow": ["??? is young—it has only just left its nest. As a result, it sometimes becomes lonesome and cries at night. This Pokémon feeds on Wurmple that live in forests.", "??? est jeune. Il vient de quitter son nid. Du coup, il se sent parfois un peu seul et pleure la nuit. Ce Pokémon se nourrit des Chenipotte qu’il trouve dans les forêts.", ["Tiny Swallow Pokémon", "Pokémon Minirondel"], null],
  "swellow": ["??? is very conscientious about the upkeep of its glossy wings. Once two ??? are gathered, they diligently take care of cleaning each other’s wings.", "??? fait attention à bien entretenir ses ailes brillantes. Lorsque deux ??? se rencontrent, ils se nettoient mutuellement les ailes avec attention.", ["Swallow Pokémon", "Pokémon Hirondelle"], null],
  "wingull": ["It soars on updrafts without flapping its wings. It makes a nest on sheer cliffs at the sea’s edge.", "Il niche dans les falaises. En utilisant les courants d’air, il peut voler sans battre des ailes.", ["Seagull Pokémon", "Pokémon Mouette"], null],
  "pelipper": ["Skimming the water’s surface, it dips its large bill in the sea, scoops up food and water, and carries it.", "Avec son grand bec, il transporte de la nourriture qu’il a récoltée en volant la bouche ouverte au ras de la mer, gobant de l’eau au passage.", ["Water Bird Pokémon", "Pokémon Oiseaudo"], null],
  "ralts": ["Tends to prefer people with a chipper disposition to those who are gloomy, but it has shown no discrimination with regard to age or gender. Needs more research.", "Quand ses cornes rouges captent les ondes positives d’un Pokémon ou d’un humain, tout son corps se réchauffe.", ["Feeling Pokémon", "Pokémon Sentiment"], null],
  "kirlia": ["It resembles a maiden in appearance, but it wields strange powers to project visions of paradise. I suspect the crimson ornaments on its head are the key to its abilities.", "Il peut distordre l’espace-temps grâce à ses pouvoirs psychiques et ainsi voir l’avenir.", ["Emotion Pokémon", "Pokémon Émotion"], null],
  "gardevoir": ["It will dedicate itself to defending a master it has come to adore. Its pure white dress, reminiscent of those worn by ladies of nobility, is the dress of one who is willing to risk their life.", "Prêt à tout pour protéger son Dresseur, il peut aller jusqu’à épuiser sa force mentale pour créer un mini trou noir.", ["Embrace Pokémon", "Pokémon Étreinte"], null],
  "surskit": ["It lives in ponds and marshes that feature lots of plant life. It often fights with Dewpider, whose habitat and diet are similar.", "Il vit dans les lacs ou les marais où prospèrent les plantes hydrophiles. Il se dispute souvent proies et territoire avec son voisin, Araqua.", ["Pond Skater Pokémon", "Pokémon Maresurfeur"], null],
  "masquerain": ["Its thin, winglike antennae are highly absorbent. It waits out rainy days in tree hollows.", "Ses antennes en forme d’ailes absorbent facilement l’humidité. Par temps de pluie, il attend patiemment au creux d’un arbre.", ["Eyeball Pokémon", "Pokémon Boule Œil"], null],
  "shroomish": ["If ??? senses danger, it shakes its body and scatters spores from the top of its head. This Pokémon’s spores are so toxic, they make trees and weeds wilt.", "Lorsque ??? sent un danger, il secoue son corps et répand ses spores du haut de sa tête. Les spores de ce Pokémon sont si toxiques qu’elles font dépérir les arbres et les herbes.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "breloom": ["The seeds ringing ???’s tail are made of hardened toxic spores. It is horrible to eat the seeds. Just taking a bite of this Pokémon’s seed will cause your stomach to rumble.", "Les graines autour de la queue de ??? sont des spores toxiques. Elles sont totalement immangeables. Une simple bouchée d’une graine de ce Pokémon peut causer de grandes douleurs à l’estomac.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "slakoth": ["???’s heart beats just once a minute. Whatever happens, it is content to loaf around motionless. It is rare to see this Pokémon in motion.", "Le cœur de ??? ne bat qu’une fois par minute. Quoi qu’il arrive, il se contente de s’avachir, immobile. Il est très rare de voir ce Pokémon se déplacer.", ["Slacker Pokémon", "Pokémon Flâneur"], null],
  "vigoroth": ["??? is simply incapable of remaining still. Even when it tries to sleep, the blood in its veins grows agitated, compelling this Pokémon to run wild throughout the jungle before it can settle down.", "??? ne tient pas en place. Même quand il essaie de dormir, le sang dans ses veines s’agite, obligeant ce Pokémon à courir comme un fou dans la forêt pour s’épuiser afin de pouvoir se reposer.", ["Wild Monkey Pokémon", "Pokémon Turbusinge"], null],
  "slaking": ["Wherever ??? live, rings of over a yard in diameter appear in grassy fields. They are made by the Pokémon as it eats all the grass within reach while lying prone on the ground.", "On trouve parfois des cercles de plus de 1 m de rayon totalement désherbés dans les plaines. Ils sont faits par les ??? qui passent leurs journées allongés à manger toute l’herbe à portée de main.", ["Lazy Pokémon", "Pokémon Fainéant"], null],
  "nincada": ["It can sometimes live underground for more than 10 years. It absorbs nutrients from the roots of trees.", "Il peut passer plus de dix ans sous terre. Les racines des arbres constituent son régime alimentaire.", ["Trainee Pokémon", "Pokémon Apprenti"], null],
  "ninjask": ["This Pokémon is so quick, it is said to be able to avoid any attack. It loves to feed on tree sap.", "Ce Pokémon est tellement rapide qu’on le dit capable d’éviter toutes les attaques. Il adore se nourrir de la sève sucrée des arbres.", ["Ninja Pokémon", "Pokémon Ninja"], null],
  "shedinja": ["A strange Pokémon—it flies without moving its wings, has a hollow shell for a body, and does not breathe.", "Cet étrange Pokémon, dont le corps est comme une coquille vide, ne respire pas et peut voler sans battre des ailes.", ["Shed Pokémon", "Pokémon Exuvie"], null],
  "whismur": ["When ??? cries, the sound of its own voice startles it, making the Pokémon cry even louder. It cries until it’s exhausted, then it falls asleep.", "Quand il se met à crier, il se surprend lui-même et hurle de plus belle. Il continue ainsi jusqu’à ce qu’il se fatigue et tombe de sommeil.", ["Whisper Pokémon", "Pokémon Chuchoteur"], null],
  "loudred": ["The force of this Pokémon’s loud voice isn’t just the sound—it’s also the wave of air pressure that blows opponents away and damages them.", "Ses hurlements n’affectent pas seulement l’ouïe ; ils provoquent aussi une onde de choc qui balaie les ennemis et leur inflige des dégâts.", ["Big Voice Pokémon", "Pokémon Grosse Voix"], null],
  "exploud": ["This Pokémon can do more than just shout. To communicate with others of its kind, it’ll emit all sorts of sounds from the holes in its body.", "Pour communiquer avec ses semblables, il n’utilise pas que son cri puissant ; il émet aussi des sons par les trous de son corps.", ["Loud Noise Pokémon", "Pokémon Bruit Sourd"], null],
  "makuhita": ["There’s a rumor of a traditional recipe for stew that Trainers can use to raise strong ???.", "Il existerait un plat mijoté traditionnel que les Dresseurs cuisinent pour rendre leur ??? encore plus fort.", ["Guts Pokémon", "Pokémon Tenace"], null],
  "hariyama": ["??? that are big and fat aren’t necessarily strong. There are some small ones that move nimbly and use moves skillfully.", "Les ??? les plus forts ne sont pas forcément les plus grands. Les petits gabarits aussi ont plus d’un tour dans leur sac.", ["Arm Thrust Pokémon", "Pokémon Cogneur"], null],
  "azurill": ["Although ??? are normally docile, an angry one will swing around the big ball on its tail and try to smash its opponents.", "C’est un Pokémon docile, mais si on l’énerve, il n’hésite pas à frapper en faisant tournoyer la grosse boule au bout de sa queue.", ["Polka Dot Pokémon", "Pokémon Point Polka"], null],
  "nosepass": ["Once the people of Hisui discovered that its red nose always points north, they grew to rely on it greatly when traveling afar. The nose seems to work in a similar way to ancient compasses.", "Grâce à sa force magnétique, il peut chasser ses proies sans se déplacer, mais il attire parfois ses pires ennemis.", ["Compass Pokémon", "Pokémon Boussole"], null],
  "skitty": ["??? is known to chase around playfully after its own tail. In the wild, this Pokémon lives in holes in the trees of forests. It is very popular as a pet because of its adorable looks.", "On sait que ??? court souvent après sa queue. À l’état sauvage, ce Pokémon vit dans les cavités des arbres de la forêt. Il est tellement adorable qu’il a un grand succès comme animal de compagnie.", ["Kitten Pokémon", "Pokémon Chaton"], null],
  "delcatty": ["??? sleeps anywhere it wants without keeping a permanent nest. If other Pokémon approach it as it sleeps, this Pokémon will never fight—it will just move away somewhere else.", "??? peut dormir n’importe où. Il n’a pas de nid permanent. Lorsque d’autres Pokémon lui cherchent des noises pendant son sommeil, il ne répond pas et se contente de partir dormir ailleurs.", ["Prim Pokémon", "Pokémon Guindé"], null],
  "sableye": ["It feeds on gemstone crystals. In darkness, its eyes sparkle with the glitter of jewels.", "Ce Pokémon se nourrit de pierres précieuses. Dans les ténèbres, ses yeux brillent du reflet des joyaux.", ["Darkness Pokémon", "Pokémon Obscurité"], null],
  "mawile": ["It chomps with its gaping mouth. Its huge jaws are actually steel horns that have been transformed.", "Ses cornes d’acier forment une grande mâchoire avec laquelle il mord férocement ses adversaires.", ["Deceiver Pokémon", "Pokémon Trompeur"], null],
  "aron": ["When ??? evolves, its steel armor peels off. In ancient times, people would collect ???’s shed armor and make good use of it in their daily lives.", "Quand il évolue, il perd son armure d’acier. Autrefois, les gens la ramassaient pour en faire usage dans leur vie quotidienne.", ["Iron Armor Pokémon", "Pokémon Armurfer"], null],
  "lairon": ["During territorial disputes, ??? fight by slamming into each other. Close inspection of their steel armor reveals scratches and dents.", "Les ??? se disputent les territoires en luttant au corps à corps, comme le montrent les éraflures sur leur armure d’acier.", ["Iron Armor Pokémon", "Pokémon Armurfer"], null],
  "aggron": ["Long ago, there was a king who wore a helmet meant to resemble the head of an ???. He was trying to channel the Pokémon’s strength.", "Il y a fort longtemps, un roi portait un casque à l’effigie de ???, pensant qu’il pourrait ainsi s’approprier sa force.", ["Iron Armor Pokémon", "Pokémon Armurfer"], null],
  "meditite": ["??? heightens its inner energy through meditation. It survives on just one berry a day. Minimal eating is another aspect of this Pokémon’s training.", "??? intensifie son énergie intérieure grâce à la méditation. Il lui suffit d’une Baie par jour pour survivre. La diète fait partie de l’entraînement de ce Pokémon.", ["Meditate Pokémon", "Pokémon Méditation"], null],
  "medicham": ["Through the power of meditation, ??? developed its sixth sense. It gained the ability to use psychokinetic powers. This Pokémon is known to meditate for a whole month without eating.", "Grâce au pouvoir de la méditation, ??? a développé son sixième sens. Il peut utiliser des pouvoirs télékinétiques. On sait que ce Pokémon peut méditer pendant un mois sans manger.", ["Meditate Pokémon", "Pokémon Méditation"], null],
  "electrike": ["It stores electricity in its fur. It gives off sparks from all over its body in seasons when the air is dry.", "L’électricité statique s’accumule dans sa fourrure. Par temps sec, elle dégage des étincelles.", ["Lightning Pokémon", "Pokémon Orage"], null],
  "manectric": ["It rarely appears before people. It is said to nest where lightning has fallen.", "Ce Pokémon évite de se montrer aux humains. On raconte qu’il fait son nid aux endroits où la foudre s’est abattue.", ["Discharge Pokémon", "Pokémon Décharge"], null],
  "plusle": ["When ??? is cheering on its partner, it flashes with electric sparks from all over its body. If its partner loses, this Pokémon cries loudly.", "Quand ??? veut encourager son partenaire, des étincelles jaillissent un peu partout de son corps. Si son partenaire perd, ce Pokémon pleure à chaudes larmes.", ["Cheering Pokémon", "Pokémon Acclameur"], null],
  "minun": ["??? loves to cheer on its partner in battle. It gives off sparks from its body while it is doing so. If its partner is in trouble, this Pokémon gives off increasing amounts of sparks.", "??? adore encourager son partenaire pendant les combats. Des étincelles jaillissent alors de son corps. Lorsque son partenaire est en difficulté, le corps de ce Pokémon libère encore plus d’étincelles.", ["Cheering Pokémon", "Pokémon Acclameur"], null],
  "volbeat": ["???’s tail glows like a lightbulb. With other ???, it uses its tail to draw geometric shapes in the night sky. This Pokémon loves the sweet aroma given off by Illumise.", "La queue de ??? éclaire comme une ampoule. Ensemble, les ??? dessinent des figures géométriques dans la nuit étoilée. Ce Pokémon adore le parfum dégagé par Lumivole.", ["Firefly Pokémon", "Pokémon Luciole"], null],
  "illumise": ["??? leads a flight of illuminated Volbeat to draw signs in the night sky. This Pokémon is said to earn greater respect from its peers by composing more complex designs in the sky.", "??? dirige un vol de Muciole lumineux pour dessiner des figures dans la nuit étoilée. On raconte que ce Pokémon gagne le respect de ses pairs en composant des figures complexes dans le ciel.", ["Firefly Pokémon", "Pokémon Luciole"], null],
  "roselia": ["Though beautiful, it has highly poisonous thorns. There is an old tradition in my homeland wherein one would send these thorns to an opponent to challenge them to a duel.", "Ses mains sécrètent chacune un poison différent dont il se sert pour attaquer. Plus le parfum de ??? est intense, plus sa santé est bonne.", ["Thorn Pokémon", "Pokémon Épine"], null],
  "gulpin": ["Most of ???’s body is made up of its stomach—its heart and brain are very small in comparison. This Pokémon’s stomach contains special enzymes that dissolve anything.", "Le corps de ??? n’est pratiquement qu’un gros estomac. En comparaison, son cœur et son cerveau sont tout petits. L’estomac de ce Pokémon contient des enzymes spéciales capables de tout dissoudre.", ["Stomach Pokémon", "Pokémon Estomac"], null],
  "swalot": ["??? has no teeth, so what it eats, it swallows whole, no matter what. Its cavernous mouth yawns widely. An automobile tire could easily fit inside this Pokémon’s mouth.", "??? n’a pas de dents, ce qui le force à tout avaler en une bouchée. Quand il bâille, sa bouche prend une taille impressionnante, et on pourrait y placer une roue de voiture.", ["Poison Bag Pokémon", "Pokémon Sac Poison"], null],
  "carvanha": ["These Pokémon have sharp fangs and powerful jaws. Sailors avoid ??? dens at all costs.", "Il possède une mâchoire puissante garnie de dents acérées. Les marins ne s’approchent jamais des eaux habitées par les ???.", ["Savage Pokémon", "Pokémon Féroce"], null],
  "sharpedo": ["This Pokémon is known as the Bully of the Sea. Any ship entering the waters ??? calls home will be attacked—no exceptions.", "Surnommé le « tyran des mers », ce Pokémon attaque sans exception tous les navires qui osent s’aventurer sur son territoire.", ["Brutal Pokémon", "Pokémon Brutal"], null],
  "wailmer": ["When it sucks in a large volume of seawater, it becomes like a big, bouncy ball. It eats a ton of food daily.", "Il ressemble à un énorme ballon quand il avale de très grandes quantités d’eau de mer. Il dévore une tonne de nourriture par jour.", ["Ball Whale Pokémon", "Pokémon Baleinboule"], null],
  "wailord": ["Its immense size is the reason for its popularity. ??? watching is a favorite sightseeing activity in various parts of the world.", "Sa taille fait de lui un Pokémon fascinant. Les sites touristiques proposant d’observer les ??? ont toujours beaucoup de succès.", ["Float Whale Pokémon", "Pokémon Cachabouée"], null],
  "numel": ["??? stores magma of almost 2,200 degrees Fahrenheit within its body. If it gets wet, the magma cools and hardens. In that event, the Pokémon’s body grows heavy and its movements become sluggish.", "??? stocke du magma à 1 200 °C dans son corps. Lorsqu’il est mouillé, le magma se refroidit et durcit. Le corps du Pokémon devient alors très lourd et ses mouvements très lents.", ["Numb Pokémon", "Pokémon Engourdi"], null],
  "camerupt": ["The humps on ???’s back are formed by a transformation of its bones. They sometimes blast out molten magma. This Pokémon apparently erupts often when it is enraged.", "Les bosses sur le dos de ??? sont apparues après une déformation de ses os. Elles crachent parfois du magma en fusion. Ce Pokémon entre apparemment en éruption lorsqu’il est énervé.", ["Eruption Pokémon", "Pokémon Éruption"], null],
  "torkoal": ["You find abandoned coal mines full of them. They dig tirelessly in search of coal.", "Les ??? vivent en grand nombre dans les mines abandonnées, où ils extraient le charbon avec ardeur.", ["Coal Pokémon", "Pokémon Charbon"], null],
  "spoink": ["??? keeps a pearl on top of its head. The pearl functions to amplify this Pokémon’s psychokinetic powers. It is therefore on a constant search for a bigger pearl.", "??? garde une perle sur sa tête. Elle lui sert à amplifier ses pouvoirs télékinétiques. Il est constamment en quête d’une perle plus grosse.", ["Bounce Pokémon", "Pokémon Rebond"], null],
  "grumpig": ["??? uses the black pearls on its body to wield its fantastic powers. When it is doing so, it dances bizarrely. This Pokémon’s black pearls are valuable as works of art.", "??? utilise les perles noires sur son corps pour exercer ses formidables pouvoirs. Quand il est en action, il entame une étrange danse. Les perles noires de ce Pokémon ont une valeur inestimable.", ["Manipulate Pokémon", "Pokémon Magouilleur"], null],
  "spinda": ["Each ???’s spot pattern is different. With its stumbling movements, it evades opponents’ attacks brilliantly!", "Chaque ??? possède un pelage unique. Ce Pokémon esquive les attaques de son adversaire grâce à d’imprévisibles oscillations.", ["Spot Panda Pokémon", "Pokémon Panda Tache"], null],
  "trapinch": ["It makes an inescapable conical pit and lies in wait at the bottom for prey to come tumbling down.", "Il creuse, puis attend ses proies dans son antre en forme de cône, dont il est impossible de s’échapper.", ["Ant Pit Pokémon", "Pokémon Piégeur"], null],
  "vibrava": ["To help make its wings grow, it dissolves quantities of prey in its digestive juices and guzzles them down every day.", "Pour aider ses ailes à pousser, il se nourrit chaque jour d’un grand nombre de proies qu’il dissout en projetant de l’acide.", ["Vibration Pokémon", "Pokémon Vibration"], null],
  "flygon": ["It is nicknamed the Desert Spirit because the flapping of its wings sounds like a woman singing.", "On l’appelle « l’esprit du désert », car ses battements d’ailes résonnent comme une mélodie entonnée par une voix douce.", ["Mystic Pokémon", "Pokémon Mystique"], null],
  "cacnea": ["The more arid and harsh the environment, the more pretty and fragrant a flower ??? grows. This Pokémon battles by wildly swinging its thorny arms.", "Si son environnement est aride et difficile, la fleur de ??? devient plus jolie et dégage un parfum délicat. Ce Pokémon se bat en agitant ses bras épineux.", ["Cactus Pokémon", "Pokémon Cactus"], null],
  "cacturne": ["If a traveler is going through a desert in the thick of night, ??? will follow in a ragtag group. The Pokémon are biding their time, waiting for the traveler to tire and become incapable of moving.", "Lorsqu’un voyageur traverse le désert au milieu de la nuit, les ??? le suivent en groupe. Ces Pokémon attendent le bon moment, quand le voyageur est fatigué et qu’il n’est plus capable de bouger.", ["Scarecrow Pokémon", "Pokémon Épouvantail"], null],
  "swablu": ["Since ??? looks like a cumulus cloud, foes can have a hard time finding it. Apparently its wings turned white over many generations.", "Ses ailes en forme de nuage le dissimulent aux yeux des ennemis. On raconte qu’elles sont devenues blanches après plusieurs générations.", ["Cotton Bird Pokémon", "Pokémon Oiseaucoton"], null],
  "altaria": ["This Pokémon has a kind disposition, but if it’s provoked, it will threaten opponents with shrill cries before attacking them without mercy.", "Il est de nature aimable, mais si on le met en colère, il intimide son adversaire en poussant un cri strident et l’attaque sans pitié.", ["Humming Pokémon", "Pokémon Virevolteur"], null],
  "zangoose": ["??? usually stays on all fours, but when angered, it gets up on its hind legs and extends its claws. This Pokémon shares a bitter rivalry with Seviper that dates back over generations.", "??? est généralement à quatre pattes, mais lorsqu’il est en colère, il se lève sur ses pattes arrière et montre ses griffes. Ce Pokémon est l’ennemi juré de Séviper depuis plusieurs générations.", ["Cat Ferret Pokémon", "Pokémon Chat Furet"], null],
  "seviper": ["???’s swordlike tail serves two purposes—it slashes foes and douses them with secreted poison. This Pokémon will not give up its long-running blood feud with Zangoose.", "La queue tranchante comme un sabre de ??? a deux fonctions : elle peut frapper l’ennemi et lui injecter un poison qu’il sécrète. Ce Pokémon n’oublie jamais sa vieille rancune envers Mangriff.", ["Fang Snake Pokémon", "Pokémon Serpacroc"], null],
  "lunatone": ["It was discovered at the site of a meteor strike 40 years ago. Its stare can lull its foes to sleep.", "Il a été découvert dans le cratère d’une météorite il y a 40 ans. Un simple regard de sa part endort ses ennemis.", ["Meteorite Pokémon", "Pokémon Météorite"], null],
  "solrock": ["Solar energy is the source of its power, so it is strong during the daytime. When it spins, its body shines.", "Tirant sa force de l’énergie solaire, il est particulièrement puissant pendant la journée. Il s’illumine quand il tourne.", ["Meteorite Pokémon", "Pokémon Météorite"], null],
  "barboach": ["Makes its home in swamps with murky water. The poor visibility hides this Pokémon from predators, and the slime on its body makes grasping it difficult.", "Il sonde les bords boueux des rivières avec ses barbillons. Un film fin et visqueux protège tout son corps.", ["Whiskers Pokémon", "Pokémon Barbillon"], null],
  "whiscash": ["Strikes its caudal fin against the swamp bed to shake the ground and startle its prey. It will then swallow the fleeing prey whole. People mistook this behavior as the cause of earthquakes.", "Il a besoin d’un marais entier pour vivre. Si un ennemi s’approche, il s’énerve et déclenche un séisme.", ["Whiskers Pokémon", "Pokémon Barbillon"], null],
  "corphish": ["It was originally a Pokémon from afar that escaped to the wild. It can adapt to the dirtiest river.", "Un Pokémon importé, retourné à l’état sauvage. Il s’adapte même aux rivières les plus polluées.", ["Ruffian Pokémon", "Pokémon Brute"], null],
  "crawdaunt": ["A brutish Pokémon that loves to battle. It will crash itself into any foe that approaches its nest.", "Il adore se battre et frappe comme une brute tous ceux qui approchent de sa mare.", ["Rogue Pokémon", "Pokémon Crapule"], null],
  "baltoy": ["It was discovered in ancient ruins. While moving, it constantly spins. It stands on one foot even when asleep.", "Ce Pokémon découvert dans des ruines anciennes tourne sur lui-même pour se déplacer. Il se tient toujours sur un pied, même quand il dort.", ["Clay Doll Pokémon", "Pokémon Poupargile"], null],
  "claydol": ["It appears to have been born from clay dolls made by ancient people. It uses telekinesis to float and move.", "Ce Pokémon aurait été créé à partir d’une poupée d’argile confectionnée par une ancienne civilisation. Il se déplace en lévitant.", ["Clay Doll Pokémon", "Pokémon Poupargile"], null],
  "lileep": ["??? clings to rocks on the seabed. When prey comes close, this Pokémon entangles it with petallike tentacles.", "Accroché aux rochers des profondeurs, il attend qu’une proie s’approche de lui pour l’attraper avec ses tentacules en forme de pétales.", ["Sea Lily Pokémon", "Pokémon Lis d’Eau"], null],
  "cradily": ["Once ??? catches prey in its tentacles, it digests them whole and absorbs their nutrients.", "Il attrape ses proies à l’aide de ses tentacules, puis les dissout immédiatement avec ses sucs digestifs pour en absorber les nutriments.", ["Barnacle Pokémon", "Pokémon Bernacle"], null],
  "anorith": ["??? can swim swiftly by pulling its eight wings through the water like oars on a boat. This Pokémon is an ancestor of modern bug Pokémon.", "Ce Pokémon peut nager très vite en agitant ses huit ailes comme des rames de bateau. Il fait partie des ancêtres des Pokémon Insecte.", ["Old Shrimp Pokémon", "Pokémon Crustage"], null],
  "armaldo": ["Though it lives on land, it’s also a good swimmer. It dives into the ocean in search of prey, using its sharp claws to take down its quarry.", "Bien que vivant sur la terre ferme, il est très bon nageur. Il plonge dans la mer à la recherche de proies et les abat avec ses pinces acérées.", ["Plate Pokémon", "Pokémon Blindage"], null],
  "feebas": ["It is a shabby and ugly Pokémon. However, it is very hardy and can survive on little water.", "Ce Pokémon a peut-être un physique disgracieux, mais il est robuste et peut survivre dans très peu d’eau.", ["Fish Pokémon", "Pokémon Poisson"], null],
  "milotic": ["It’s said that a glimpse of a ??? and its beauty will calm any hostile emotions you’re feeling.", "On dit que la beauté de ce Pokémon est telle qu’elle apaise l’esprit de ceux qui le voient.", ["Tender Pokémon", "Pokémon Tendre"], null],
  "castform": ["Its form changes depending on the weather. The rougher conditions get, the rougher ???’s disposition!", "Il n’y a pas que son apparence qui change en fonction de la météo : son tempérament aussi ! Plus il y a de vent, plus il se montre agressif.", ["Weather Pokémon", "Pokémon Climat"], null],
  "kecleon": ["Its color changes for concealment and also when its mood or health changes. The darker the color, the healthier it is.", "Sa couleur change quand il se cache, mais varie aussi selon son humeur et son état de santé : plus il est en forme, plus sa couleur est vive.", ["Color Swap Pokémon", "Pokémon Multicolor"], null],
  "shuppet": ["There’s a proverb that says, “Shun the house where ??? gather in the growing dusk.”", "Il existe un proverbe ancien qui dit : « Fuis la demeure où les ??? se rassemblent en nombre à la pénombre. »", ["Puppet Pokémon", "Pokémon Poupée"], null],
  "banette": ["Resentment at being cast off made it spring into being. Some say that treating it well will satisfy it, and it will once more become a stuffed toy.", "Il est né de la rancune qu’il a ressentie quand il a été abandonné. Il redevient apparemment une poupée si l’on en prend grand soin.", ["Marionette Pokémon", "Pokémon Marionnette"], null],
  "duskull": ["I've heard that the children of Hisui all begin to behave once they've been told the story of how this Pokémon roams about before the witching hour to spirit away misbehaving children.", "Ce Pokémon devient invisible pour se rapprocher furtivement de ses proies. Il a le pouvoir de traverser les murs.", ["Requiem Pokémon", "Pokémon Requiem"], null],
  "dusclops": ["There are rumors that peeking inside its bandage-wrapped body will cause one to get pulled in through the gaps between the bandages, never to return. I've been too scared to verify.", "Il cherche des feux follets pour les avaler. Ce qu’il se passe alors à l’intérieur de son corps vide est un mystère.", ["Beckon Pokémon", "Pokémon Appel"], null],
  "tropius": ["Bunches of delicious fruit grow around its neck. In warm areas, many ranches raise ???.", "Dans les régions où il fait chaud, on trouve des fermes dédiées à l’élevage de ce Pokémon, très apprécié pour les fruits poussant sur son cou.", ["Fruit Pokémon", "Pokémon Fruit"], null],
  "chimecho": ["Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.", "Lorsqu’il y a beaucoup de vent, ??? pousse des cris, accroché à une branche ou à un auvent par une ventouse placée sur sa tête. Ce Pokémon attrape des Baies avec sa longue queue pour les manger.", ["Wind Chime Pokémon", "Pokémon Carillon"], null],
  "absol": ["Because of this Pokémon’s ability to detect danger, people mistook ??? as a bringer of doom.", "Sa capacité à pressentir le danger lui a autrefois valu la réputation de porter malheur.", ["Disaster Pokémon", "Pokémon Désastre"], null],
  "wynaut": ["It tends to move in a pack with others. They cluster in a tight group to sleep in a cave.", "Ces Pokémon adorent se déplacer en groupe. Ils se blottissent les uns contre les autres dans des cavernes pour dormir.", ["Bright Pokémon", "Pokémon Ravi"], null],
  "snorunt": ["Arrives alongside the first snow. It's thought that homes ??? visit will prosper for many generations. By tradition, one might offer a lump of ice made from pure water at one's front door.", "Il ne peut vivre que dans les plus froides contrées. Il s’accommode parfaitement de températures atteignant les - 100 °C.", ["Snow Hat Pokémon", "Pokémon Capuche"], null],
  "glalie": ["It covers its body with an armor of ice harder than steel. Uses its breath to freeze prey, which it then devours as if they were frozen desserts.", "Il a le pouvoir de geler l’humidité ambiante en un instant et peut ainsi immobiliser ses proies.", ["Face Pokémon", "Pokémon Face"], null],
  "spheal": ["During the season when drift ice approaches the shore, ??? prefers living on the ice—where fewer predators lurk—rather than the land. Its fur retains heat superbly and resists harsh cold.", "Il scrute la mer en se laissant porter par les vagues. Lorsqu’il repère des proies, il avertit les Kaimorse du groupe.", ["Clap Pokémon", "Pokémon Clap Clap"], null],
  "sealeo": ["Its white whiskers are very sensitive. ??? will balance Spheal on the tip of its nose, checking its scent and its feel to be sure the Spheal is healthy.", "Il ne peut pas s’empêcher de faire tourner sur son museau tout ce qui a une forme sphérique, comme les Obalie ou les Poké Balls.", ["Ball Roll Pokémon", "Pokémon Roule Boule"], null],
  "walrein": ["Its thick tusks are strong enough to shatter drift ice. They have been known to break, but they will grow back by the next year. The Hisui region is well known for these broken tusks.", "Ses défenses poussent tout au long de sa vie. Si l’une d’elles se brise au cours d’un combat, au bout d’un an, elle aura repoussé entièrement.", ["Ice Break Pokémon", "Pokémon Brise Glace"], null],
  "clamperl": ["???’s pearls are exceedingly precious. They can be more than 10 times as costly as Shellder’s pearls.", "La perle de ??? est tellement précieuse qu’elle peut valoir plus de dix fois la valeur de celle de Kokiyas.", ["Bivalve Pokémon", "Pokémon Bivalve"], null],
  "huntail": ["Deep seas are their habitat. According to tradition, when ??? wash up onshore, something unfortunate will happen.", "Il habite dans les profondeurs de l’océan. Un ??? trouvé sur la plage serait un mauvais présage.", ["Deep Sea Pokémon", "Pokémon Abysse"], null],
  "gorebyss": ["It sucks bodily fluids out of its prey. The leftover meat sinks to the seafloor, where it becomes food for other Pokémon.", "Il se nourrit en aspirant les fluides corporels de ses proies. Le reste tombe au fond de la mer, nourrissant ainsi d’autres Pokémon.", ["South Sea Pokémon", "Pokémon Mer du Sud"], null],
  "relicanth": ["This Pokémon was discovered during deep-sea exploration. Its appearance hasn’t changed in 100,000,000 years, so it’s called a living fossil.", "Découvert lors d’une expédition dans les abysses, son apparence inchangée depuis 100 millions d’années lui a valu le surnom de « fossile vivant ».", ["Longevity Pokémon", "Pokémon Longévité"], null],
  "luvdisc": ["??? makes its home in coral reefs in warm seas. It especially likes sleeping in the space between Corsola’s branches.", "Il vit dans les récifs coralliens des mers chaudes, et aime particulièrement dormir entre les cornes des Corayon.", ["Rendezvous Pokémon", "Pokémon Rendezvous"], null],
  "bagon": ["??? is a solitary Pokémon that doesn’t form groups with others of its kind. It also has a head hard enough to cleave a boulder in one strike.", "La tête de ce Pokémon solitaire est si solide qu’il est capable de fendre en deux un rocher d’un seul coup.", ["Rock Head Pokémon", "Pokémon Tête de Roc"], null],
  "shelgon": ["??? ignores its hunger entirely, never eating any food. Apparently, ??? will evolve once all its energy stores are used up.", "Il se prive de nourriture, résistant à la faim. On dit que son évolution commence lorsque ses réserves d’énergie sont épuisées.", ["Endurance Pokémon", "Pokémon Endurant"], null],
  "salamence": ["While basking in the joy of flight generally keeps this Pokémon in high spirits, ??? turns into an uncontrollable menace if something angers it.", "Heureux de pouvoir voler dans le ciel, il est souvent de bonne humeur, mais il devient incontrôlable lorsqu’on le met en colère.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "beldum": ["The cells in this Pokémon’s body are composed of magnetic material. Instead of blood, magnetic forces flow through ???’s body.", "Les cellules de son corps sont composées d’aimants. Une force magnétique coule dans ses veines à la place du sang.", ["Iron Ball Pokémon", "Pokémon Boulefer"], null],
  "metang": ["Using magnetic forces to stay aloft, this Pokémon flies at high speeds, weaving through harsh mountain terrain in pursuit of prey.", "Ce Pokémon vole par magnétisme. Il poursuit ses proies en slalomant à toute allure entre les pics escarpés.", ["Iron Claw Pokémon", "Pokémon Pincefer"], null],
  "metagross": ["??? is the result of the fusion of two Metang. This Pokémon defeats its opponents through use of its supercomputer-level brain.", "Né de la fusion de deux Métang, il vient à bout de ses ennemis grâce à son cerveau qui est aussi performant qu’un superordinateur.", ["Iron Leg Pokémon", "Pokémon Pattefer"], null],
  "regirock": ["Cutting-edge technology was used to study the internals of this Pokémon’s rock body, but nothing was found—not even a brain or a heart.", "Bien que son corps de pierre ait été examiné avec les technologies les plus modernes, nulle trace de cerveau ou de cœur n’a été trouvée.", ["Rock Peak Pokémon", "Pokémon Pic Rocheux"], null],
  "regice": ["This Pokémon’s body is made of solid ice. It’s said that ??? was born beneath thick ice in the ice age.", "Ce Pokémon de l’ère glaciaire dont le corps est entièrement composé d’eau gelée serait né sous une épaisse couche de glace.", ["Iceberg Pokémon", "Pokémon Iceberg"], null],
  "registeel": ["It’s rumored that this Pokémon was born deep underground in the planet’s mantle and that it emerged onto the surface 10,000 years ago.", "Il paraît qu’il est né dans le manteau terrestre et qu’il en a émergé il y a environ 10 000 ans.", ["Iron Pokémon", "Pokémon Fer"], null],
  "latias": ["??? is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The Pokémon enfolds its body with its down and refracts light to alter its appearance.", "??? est très intelligent et comprend le langage des hommes. Il est recouvert d’une espèce de duvet ressemblant à du verre. Ce Pokémon s’enveloppe dans ce duvet et reflète la lumière pour changer son apparence.", ["Eon Pokémon", "Pokémon Éon"], null],
  "latios": ["??? will only open its heart to a Trainer with a compassionate spirit. This Pokémon can fly faster than a jet plane by folding its forelegs to minimize air resistance.", "??? n’ouvrira son cœur qu’à un Dresseur doté d’un esprit compatissant. Ce Pokémon peut voler plus vite qu’un avion à réaction en repliant ses pattes avant pour améliorer son aérodynamisme.", ["Eon Pokémon", "Pokémon Éon"], null],
  "kyogre": ["??? is said to be the personification of the sea itself. Legends tell of its many clashes against Groudon, as each sought to gain the power of nature.", "Un Pokémon considéré comme l’avatar des océans. Selon les légendes, il a disputé de nombreux combats avec Groudon pour contrôler l’énergie de la nature.", ["Sea Basin Pokémon", "Pokémon Bassinmarin"], null],
  "groudon": ["Through Primal Reversion and with nature’s full power, it will take back its true form. It can cause magma to erupt and expand the landmass of the world.", "Grâce à l’énergie de la nature, il peut accomplir sa Primo-Résurgence pour retrouver son apparence originelle. Ce pouvoir lui permet de créer du magma pour étendre les continents.", ["Continent Pokémon", "Pokémon Continent"], null],
  "rayquaza": ["It flies forever through the ozone layer, consuming meteoroids for sustenance. The many meteoroids in its body provide the energy it needs to Mega Evolve.", "Un Pokémon qui vit dans la couche d’ozone et se nourrit des météorites qu’il intercepte. Leur énergie s’accumule dans son corps, ce qui lui permet de méga-évoluer.", ["Sky High Pokémon", "Pokémon Cieux"], null],
  "jirachi": ["It’s believed that when this Pokémon wakes from its 1,000-year slumber, it will grant any wishes written on the notes attached to its head.", "On raconte que lorsqu’il se réveille de son sommeil millénaire, il exauce les vœux écrits sur les rubans de papier de sa tête.", ["Wish Pokémon", "Pokémon Souhait"], null],
  "deoxys": ["??? emerged from a virus that came from space. It is highly intelligent and wields psychokinetic powers. This Pokémon shoots lasers from the crystalline organ on its chest.", "??? était à l’origine un virus provenant de l’espace. Il est extrêmement intelligent et dispose de pouvoirs télékinétiques. Ce Pokémon envoie des lasers avec l’organe cristallin situé sur sa poitrine.", ["DNA Pokémon", "Pokémon ADN"], null],
  "turtwig": ["This Pokémon becomes more energetic the more sunlight there is. The part resembling a shell is similar to silt and is slightly damp and warm to the touch.", "Son corps produit de l’oxygène par photosynthèse. La feuille sur sa tête flétrit quand il a soif.", ["Tiny Leaf Pokémon", "Pokémon Minifeuille"], null],
  "grotle": ["Appears where there is clean spring water. The fruit that grows on the shrubs on its shell is sweet, nutritious, and truly delicious.", "Il sait d’instinct où trouver une source d’eau pure. Il y transporte d’autres Pokémon sur son dos.", ["Grove Pokémon", "Pokémon Bosquet"], null],
  "torterra": ["This remarkable, large-bodied Pokémon would serve beautifully as borrowed scenery for a garden, and its strength is peerless. ??? roams the wilderness in search of clean water.", "Il arrive que de petits Pokémon se rassemblent sur son dos immobile pour y faire leur nid.", ["Continent Pokémon", "Pokémon Continent"], null],
  "chimchar": ["Full of vigor and always in high spirits. It was once known by the name ”Lantern-Tail” and feared as some kind of apparition.", "La flamme de son postérieur brûle grâce à un gaz de son estomac. Elle faiblit quand il ne va pas bien.", ["Chimp Pokémon", "Pokémon Chimpanzé"], null],
  "monferno": ["The deeper the blue on its face, the more powerful it will grow to become. It leaps about every which way and lands powerful blows against its opponents with the flame on its tail.", "Il attaque en prenant appui sur les murs et les plafonds. Sa queue ardente n’est pas son seul atout.", ["Playful Pokémon", "Pokémon Garnement"], null],
  "infernape": ["A tall, hardy Pokémon with a dazzling appearance. It shrouds itself in flame and battles as if engaged in dance—truly a sight to behold.", "Il fait voltiger ses ennemis grâce à sa vitesse et son style de combat spécial qui utilise ses quatre membres.", ["Flame Pokémon", "Pokémon Flamme"], null],
  "piplup": ["Prefers cold climes and appears along coasts. It's an adorable little thing—as cute as any child—but it's also prideful, unwilling to accept handouts from people.", "Il est fier et déteste accepter la nourriture qu’on lui offre. Son pelage épais le protège du froid.", ["Penguin Pokémon", "Pokémon Pingouin"], null],
  "prinplup": ["It swims gracefully through the frigid sea and sings with a voice like the roaring tide. It has powerful, sturdy wings and dignity to match.", "C’est un Pokémon solitaire. Un seul coup de ses puissantes ailes peut briser un arbre en deux.", ["Penguin Pokémon", "Pokémon Pingouin"], null],
  "empoleon": ["Since ancient times, it has been revered by the people of Hisui, who call it the Master of the Waves. Its wings are a match for even master-crafted blades.", "Les trois cornes de son bec sont le symbole de sa force. Celles du chef sont plus grosses que les autres.", ["Emperor Pokémon", "Pokémon Empereur"], null],
  "starly": ["They live in the fields and mountains, gathering in large flocks. Their cries are quite obnoxious. Though small, their wings are strong—a strike from them leaves pain that persists for a week.", "Ce Pokémon très bruyant parcourt champs et forêts en nuées pour chasser les Pokémon Insecte.", ["Starling Pokémon", "Pokémon Étourneau"], null],
  "staravia": ["They form remarkably large flocks and are constantly fighting amongst themselves. I suspect that those with magnificent plumes on their heads are the strong ones.", "Il peuple les champs et les forêts. Lorsque deux volées se croisent, elles luttent pour le territoire.", ["Starling Pokémon", "Pokémon Étourneau"], null],
  "staraptor": ["It has left the flock, having gained strength enough to survive on its own. The astounding force with which ??? flies through the air allows it to carry away large, burly targets.", "Lorsque Étourvol évolue en ???, il quitte son groupe pour vivre seul. Ses ailes sont très développées.", ["Predator Pokémon", "Pokémon Rapace"], null],
  "bidoof": ["??? has an unsophisticated face and is rarely flustered by anything. There have been incidents involving ??? sauntering into villages and gnawing on the houses without a single care.", "Il ronge constamment des troncs et des pierres pour se faire les incisives. Il niche le long de l’eau.", ["Plump Mouse Pokémon", "Pokémon Souridodue"], null],
  "bibarel": ["??? fur repels water and is also a fantastic material for heat retention. These Pokémon create dams on rivers to live in.", "Il construit des barrages de boue et d’écorce le long des fleuves. C’est un ouvrier de renom.", ["Beaver Pokémon", "Pokémon Castor"], null],
  "kricketot": ["When the trees take on new hues, more of these Pokémon appear. The tone they create by striking their antennae together resembles that of the marimba, an instrument of foreign lands.", "Quand ses antennes s’entrechoquent, elles laissent échapper un bruit de xylophone.", ["Cricket Pokémon", "Pokémon Criquet"], null],
  "kricketune": ["It uses its cutlass-like arms to produce sound, the melody of which varies from individual to individual. It is a worthwhile endeavor to seek out one's favorite tunes.", "Il exprime ses émotions par des mélodies. Les scientifiques étudient actuellement leur structure.", ["Cricket Pokémon", "Pokémon Criquet"], null],
  "shinx": ["Shakes its body to generate electricity. Its stature belies its aggression—one must be patient to tame this Pokémon.", "Sa fourrure s’illumine grâce à l’électricité. Il agite l’extrémité lumineuse de sa queue pour envoyer des signes à ses congénères.", ["Flash Pokémon", "Pokémon Flash"], null],
  "luxio": ["Proudly uses its electrified claws as weapons. It seems to be a gracious Pokémon, evenly sharing the spoils of the hunt with others of its kind.", "Quand il croise un ennemi, il se prépare au combat en sortant ses griffes dont les coups ont une puissance qui atteint un million de volts.", ["Spark Pokémon", "Pokémon Étincelle"], null],
  "luxray": ["They form packs, each having one male as leader. Legends say that when ???'s two eyes shimmer with gold, the Pokémon can see through anything.", "Il dort beaucoup pour récupérer la quantité d’énergie électrique énorme qu’il consomme afin de voir à travers la matière.", ["Gleam Eyes Pokémon", "Pokémon Brillœil"], null],
  "budew": ["When the sun's light strengthens, the bud atop this Pokémon's head opens. This is a sign to the people that the harsh winter is over, and the season of budding has begun.", "Il est sensible aux variations de température. Quand son bourgeon commence à s’ouvrir, l’arrivée du printemps est imminente.", ["Bud Pokémon", "Pokémon Bourgeon"], null],
  "roserade": ["Hidden within the bouquet on each hand are thorned whips loaded with virulent poison. ??? moves gracefully as it corners its prey and mercilessly lashes them with its whips.", "Sa main gauche administre un poison lent, et la droite, un poison foudroyant. Les deux peuvent être fatals.", ["Bouquet Pokémon", "Pokémon Bouquet"], null],
  "cranidos": ["An incredibly rare sight. They duel each other by ramming their heads together, and the resulting sound echoes throughout the area like the pealing of a bell.", "Son crâne extrêmement solide est sa principale caractéristique. Il s’en servait pour faire tomber des arbres les Baies dont il se nourrissait.", ["Head Butt Pokémon", "Pokémon Coud’Boule"], null],
  "rampardos": ["Very little is known about its biology. Can knock down massive trees by smashing its beautiful, pearl-like crown against them.", "Pokémon préhistorique célèbre pour ses coups de tête puissants et son petit cerveau, son extinction serait due à son extrême bêtise.", ["Head Butt Pokémon", "Pokémon Coud’Boule"], null],
  "shieldon": ["Much remains unknown about this Pokémon, as few have ever seen it. However, we know that it is calm and dislikes conflict, and it enjoys polishing its face against trees and rocks.", "On retrouve des fossiles de ??? dans les couches sédimentaires préhistoriques, mais seule sa tête a résisté à l’épreuve du temps.", ["Shield Pokémon", "Pokémon Bouclier"], null],
  "bastiodon": ["Its face is sturdy—as strong as diamond—and this hardness offers a very stable defense. Much about this species is still unknown, such as its natural habitat.", "Un Pokémon éteint depuis environ 100 millions d’années. Sa tête incroyablement solide était plus dure que l’acier.", ["Shield Pokémon", "Pokémon Bouclier"], null],
  "burmy": ["If its cloak is even slightly damaged, ??? will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.", "S’il perd sa cape au combat, il en tisse rapidement une nouvelle avec ce qui lui tombe sous la main.", ["Bagworm Pokémon", "Pokémon Ver Caché"], null],
  "wormadam": ["When Burmy evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed.", "Quand Cheniti a évolué, sa cape a fusionné avec son corps. ??? ne s’en sépare jamais.", ["Bagworm Pokémon", "Pokémon Ver Caché"], null],
  "mothim": ["Scatters steel-colored scales as it flaps its wings. Despite being observed feeding primarily on the nectar of flowers, ??? is not often seen around flower gardens.", "Ce Pokémon s’active à la nuit tombée pour voler le miel des Apitrini pendant leur sommeil.", ["Moth Pokémon", "Pokémon Phalène"], null],
  "combee": ["They swear fealty to a queen Pokémon and work diligently to gather nectar. Each swarm produces a different flavor of honey.", "Du lever du soleil à la tombée de la nuit, il récolte du nectar pour Apireine et sa colonie.", ["Tiny Bee Pokémon", "Pokémon Miniabeille"], null],
  "vespiquen": ["Commands its subjects to build its hive. It will dispatch any interlopers who dare sneak into its nest and use them as nourishment for itself.", "Plus la quantité de phéromones qu’il libère est élevée, plus le nombre d’Apitrini qu’il peut diriger est grand.", ["Beehive Pokémon", "Pokémon Ruche"], null],
  "pachirisu": ["A species related to the Pikachu line. Though ??? is a calm Pokémon, it still presents a danger should one touch its electrified tail or cheeks.", "Il arrive que deux ??? se frottent les joues pour partager l’électricité qu’ils ont accumulée.", ["EleSquirrel Pokémon", "Pokémon Écurélec"], null],
  "buizel": ["It moves freely in the water by spinning its forked tail for propulsion. The resemblance to the screw of a steamboat is coincidental.", "Il utilise la bouée autour de son cou pour passer sa tête hors de l’eau et observer les alentours.", ["Sea Weasel Pokémon", "Pokémon Aquabelette"], null],
  "floatzel": ["Has a long, rather splendid flotation sac, which prevents ??? from drowning even in stormy seas. One might glimpse this species around fishing hamlets from time to time.", "Il a développé une bouée pour poursuivre ses proies aquatiques. Elle fait office de canot gonflable.", ["Sea Weasel Pokémon", "Pokémon Aquabelette"], null],
  "cherubi": ["Once the fruit growing alongside the main body is large and plump, ??? will use the nutrients within to evolve. The fruit then detaches, becoming nourishment for other creatures.", "Plus son corps est rouge, plus la saveur de sa petite boule gorgée de nutriments est sucrée et délicieuse.", ["Cherry Pokémon", "Pokémon Cerise"], null],
  "cherrim": ["Motionless, save for the occasional quiver. A rich array of Pokémon can be found gathered around it, drawn by the scent exuded from ???'s folded petals.", "Lorsqu’il se ferme, ses pétales sont si durs qu’il ne craint plus les attaques des Pokémon oiseaux.", ["Blossom Pokémon", "Pokémon Floraison"], null],
  "shellos": ["Found in abundance on seashores bordering warm waters. ??? are unexpectedly friendly and will crawl toward any person they see. Take care not to get coated in mucus!", "Si on le caresse trop fort, il sécrète un étrange liquide mauve qui est inoffensif, mais dont la texture est très gluante.", ["Sea Slug Pokémon", "Pokémon Aqualimace"], null],
  "gastrodon": ["Eats beach sand for nourishment. Should one ??? encounter another of a different color, a fierce battle will inevitably ensue.", "Son corps est caoutchouteux, mais très résistant, car la puissance des chocs qu’il subit se répand sur toute sa surface.", ["Sea Slug Pokémon", "Pokémon Aqualimace"], null],
  "ambipom": ["To affirm their kinship, members of this species will form a ring by linking their newly doubled tails together. On rare occasions, humans have been accepted into such rings.", "Il utilise toujours ses deux queues pour faire la moindre tâche. Il s’en sert aussi pour enlacer les gens qu’il affectionne tout particulièrement.", ["Long Tail Pokémon", "Pokémon Longqueue"], null],
  "drifloon": ["Said to lure away young children and carry them off to the afterlife. Some whisper that ??? are formed of reincarnated human souls, but these rumors are as yet unconfirmed.", "Nés d’une concentration d’âmes, ces Pokémon peuvent apparaître en grand nombre les jours où le taux d’humidité est élevé.", ["Balloon Pokémon", "Pokémon Bouboule"], null],
  "drifblim": ["It drifts along at dusk, perfectly silent. Its transient, melancholy aspect touches some people deeply—every so often, one will come upon a song or poem devoted to ???.", "Il attrape des personnes et des Pokémon pour les transporter vers une destination inconnue.", ["Blimp Pokémon", "Pokémon Ballon"], null],
  "buneary": ["My hypothesis as to why ??? rolls up its ears is that its hearing is far too keen. I surmise that the Pokémon protects its hearing by limiting the sound that may enter its ears.", "Plus il s’entraîne, plus les coups qu’il assène en déroulant vigoureusement ses oreilles gagnent en puissance.", ["Rabbit Pokémon", "Pokémon Lapin"], null],
  "lopunny": ["Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.", "À la fin de la saison chaude, il mue et se recouvre d’une fourrure épaisse et légère pour se préparer à affronter le froid hivernal.", ["Rabbit Pokémon", "Pokémon Lapin"], null],
  "mismagius": ["The incantations ??? chants can ward against misfortune, so a custom exists of inviting it into one's home. Incur the Pokémon's displeasure, however, and disaster will surely ensue.", "Il susurre des malédictions pour tourmenter ses ennemis et leur infliger de terribles migraines ou des hallucinations terrifiantes.", ["Magical Pokémon", "Pokémon Magique"], null],
  "honchkrow": ["One cry from this Pokémon, and a murder of Murkrow come flying. At such times, one would think the curtain of night had fallen, plunging the world into jet-black darkness.", "Ses sous-fifres font le sale boulot pour lui. Il n’intervient en combat que pour donner le coup de grâce à son ennemi.", ["Big Boss Pokémon", "Pokémon Big Boss"], null],
  "glameow": ["Bewitches humans with its helical tail and piercing gaze. Its hidden claws are quite sharp as well, making this Pokémon an exceedingly tricky opponent if antagonized.", "Lorsqu’il est heureux, sa queue décrit des arabesques comme un ruban de gymnastique rythmique.", ["Catty Pokémon", "Pokémon Chafouin"], null],
  "purugly": ["Though impudent and difficult to tame, ??? enjoys great popularity due to its fur, the beauty of which surpasses even velveteen.", "Il ceinture sa taille de sa queue bifide pour paraître plus imposant.", ["Tiger Cat Pokémon", "Pokémon Chatigre"], null],
  "chingling": ["This Pokémon gave me an excruciating headache when it seemingly cried out without making a sound. Perhaps there are some sounds that the human ear is simply incapable of hearing.", "Quand il sautille, l’orbe qu’il a dans la bouche s’agite et tinte comme une cloche.", ["Bell Pokémon", "Pokémon Clochette"], null],
  "stunky": ["The poison that gushes from its aft end is accompanied by an utterly evil-smelling odor with such potency that one whiff can induce memory loss.", "S’il lève la queue, c’est qu’il s’apprête à projeter un liquide tellement nauséabond qu’il peut faire perdre connaissance.", ["Skunk Pokémon", "Pokémon Moufette"], null],
  "skuntank": ["Sprays a poisonous fluid to take down prey. Sometimes, unable to stomach the stench of its own fluid, it leaves the bested prey uneaten.", "Ce Pokémon, qui creuse son terrier dans le sol, peut projeter un liquide à l’odeur infecte avec le bout de sa queue.", ["Skunk Pokémon", "Pokémon Moufette"], null],
  "bronzor": ["Floats using a mysterious energy. The pattern engraved upon its back is held as sacred and can sometimes be found in imagery from ancient cemeteries and other such timeworn places.", "On raconte qu’il se met à briller et à refléter la vérité quand on le polit, mais il a horreur de cela.", ["Bronze Pokémon", "Pokémon Bronze"], null],
  "bronzong": ["Some believe that its bell-like cry opens holes to another world. It has been revered as a deity since ancient times.", "De nombreux savants pensent que ce Pokémon n’est pas originaire de Galar à cause des motifs qui ornent son corps.", ["Bronze Bell Pokémon", "Pokémon Clochebronze"], null],
  "bonsly": ["Its tears elicit sympathy from those who see them, but do not be deceived! This expulsion of body water is merely a physiological mechanism for keeping itself in good health.", "Il vit dans les zones rocheuses arides. Quand ses boules vertes sont sèches, elles se mettent à briller légèrement.", ["Bonsai Pokémon", "Pokémon Bonsaï"], null],
  "mime-jr": ["Known to turn up in bustling marketplaces now and again. It mimics people much as a child would, then watches how they react, eyes sparkling.", "Il considère les meilleurs danseurs parmi les M. Glaquette comme ses maîtres et s’évertue à mimer leurs mouvements.", ["Mime Pokémon", "Pokémon Mime"], null],
  "happiny": ["In imitation of Chansey, it keeps a round stone tucked into its belly pouch and cherishes it dearly. It gets along well with children and will sometimes play house with them for fun.", "Il prête volontiers son caillou rond à ceux qu’il apprécie, mais éclate en sanglots et se met en colère si on ne le lui rend pas.", ["Playhouse Pokémon", "Pokémon Maisonjouet"], null],
  "chatot": ["A versatile performer skilled in the imitation of human speech. It is said that older, more experienced ??? can even understand the meaning of the words they mimic.", "On peut lui enseigner quelques mots. S’il s’agit d’un groupe, ils retiendront les mêmes phrases.", ["Music Note Pokémon", "Pokémon Note Musique"], null],
  "spiritomb": ["It lays curses by thinking wicked thoughts. Writings tell that this Pokémon was born out of the assembly of five score and eight malevolent spirits.", "Pour punir son comportement déplorable, un voyageur a utilisé un mystérieux sortilège pour l’enchaîner à une Clé de Voûte.", ["Forbidden Pokémon", "Pokémon Interdit"], null],
  "gible": ["It nests in caves untouched by sunlight. Its sharp teeth may fall out when worn away or after an impact, but they regrow within a few days.", "Il attaque et entraîne dans son antre tout ce qui bouge, sans distinction. Sa gueule est immense, mais son estomac est relativement petit.", ["Land Shark Pokémon", "Pokémon Terrequin"], null],
  "gabite": ["Though ??? are usually of a violent disposition, when I gave one a glass bead it had been eyeing covetously, it suddenly became quite docile.", "Il cache des pierres précieuses dans le sol de sa grotte, et accueille à coups de griffes et de crocs quiconque ose y pénétrer.", ["Cave Pokémon", "Pokémon Caverne"], null],
  "garchomp": ["Soars across the heavens at blinding speed—a magnificent sight! It has a feral disposition. Utmost caution is required if one meets a ??? out in the wilds.", "Ce Pokémon très rapide même au sol capture ses proies sur les monts enneigés et rentre vite dans son antre avant que son corps ne gèle.", ["Mach Pokémon", "Pokémon Supersonic"], null],
  "munchlax": ["Its robust stomach allows it to nonchalantly devour even rotted matter. It pays frequent visits to villages, seeking out food scraps intended for compost.", "Il conserve sa nourriture sous son épaisse fourrure. Il lui arrive d’en offrir un peu à ceux en qui il a confiance.", ["Big Eater Pokémon", "Pokémon Goinfre"], null],
  "riolu": ["Though infantile in appearance, it has the mysterious ability to read the minds of humans. The pure of heart are met with ???'s approval, while those of ill nature earn only its loathing.", "Il perçoit sous forme d’aura non seulement les sentiments des autres, mais aussi l’état de la nature.", ["Emanation Pokémon", "Pokémon Émanation"], null],
  "lucario": ["A most gallant-looking creature. It emits energy waves and controls them with precision, using them to sense even faraway beings. I have given the name ”aura” to this power.", "Étant capable de lire ce que pensent les humains, ce Pokémon ne s’attache qu’aux Dresseurs dotés d’un cœur pur.", ["Aura Pokémon", "Pokémon Aura"], null],
  "hippopotas": ["Though large and languid, ??? is difficult to detect due to its tendency to burrow into and lurk beneath the soil. When agitated or excited, it expels sand from its nostrils.", "Il est principalement actif pendant la journée. Il s’enfouit profondément dans le sable pour dormir, car les nuits désertiques sont très froides.", ["Hippo Pokémon", "Pokémon Hippo"], null],
  "hippowdon": ["Short-tempered and easily moved to violence. It whips up whirlwinds of sand to crush its foes' spirits, then goes in for the attack.", "Il entre dans une violente colère quand on l’énerve : il expulse le sable qu’il a accumulé pour provoquer de véritables tempêtes.", ["Heavyweight Pokémon", "Pokémon Poids Lourd"], null],
  "skorupi": ["Its claws are not only razor-sharp but poisonous, making ??? a highly dangerous Pokémon. It seems to be weakened by cold temperatures, however.", "Il attaque avec les pinces empoisonnées de sa queue. Le venin se répand alors dans le corps de la victime et la paralyse.", ["Scorpion Pokémon", "Pokémon Scorpion"], null],
  "drapion": ["Has a brutish, ferocious temperament. With immense strength and a sturdy shell off which swords will bounce, it rampages about and wreaks havoc.", "Sa férocité lui a valu le surnom de « démon du désert », mais face à un Hippodocus, il est parfaitement docile et évite de le provoquer.", ["Ogre Scorpion Pokémon", "Pokémon Scorpogre"], null],
  "croagunk": ["A poison wielder with a dastardly personality. Despite such qualities, this species is afforded a measure of popularity due to its peculiar cry and comical features.", "Dilué, son poison sert de remède. Cela lui a valu de devenir la mascotte populaire d’une entreprise de produits pharmaceutiques.", ["Toxic Mouth Pokémon", "Pokémon Toxique"], null],
  "toxicroak": ["Its crimson claws contain a virulent toxin. This toxin can be made into a tonic by diluting it, mixing it with several types of wild grass, and boiling it down over two days.", "Il lance un coassement viril de victoire quand il parvient à terrasser sa proie. Il s’apparente aux Crapustule.", ["Toxic Mouth Pokémon", "Pokémon Toxique"], null],
  "carnivine": ["Though this is a plant Pokémon, it has a gluttonous and unruly temperament. ??? attacks its prey with its cavernous maw wide open.", "Il s’accroche aux arbres des marais et attire ses proies avec sa salive à l’odeur enivrante.", ["Bug Catcher Pokémon", "Pokémon Chopinsecte"], null],
  "finneon": ["What a gorgeous sight this Pokémon is as it swims with its long, pink-painted caudal fins fluttering behind it. ???'s beautiful appearance has led to its nickname: ”finery fish.”", "Il attire ses proies avec ses nageoires caudales lumineuses. Il passe la journée à la surface et se retire dans les abysses la nuit venue.", ["Wing Fish Pokémon", "Pokémon Poisson Ailé"], null],
  "lumineon": ["Uses its gleaming fins to hunt its prey. The view of ??? schooling near the surface of the sea at night is breathtaking— it's as though there were shining stars right there.", "Il se déplace en rampant dans les profondeurs de l’océan. Ses nageoires brillent telles des étoiles dans le ciel nocturne.", ["Neon Pokémon", "Pokémon Néon"], null],
  "mantyke": ["Though ball-like in shape, this Pokémon is a proficient swimmer. I have discovered that if a ??? spends much time with schools of Remoraid, it will eventually achieve evolution.", "Il nage au sein des bancs de Rémoraid. Lorsqu’un prédateur les attaque, il se bat à leurs côtés.", ["Kite Pokémon", "Pokémon Cervolant"], null],
  "snover": ["One is likely to encounter this Pokémon while out in the snow. There are stories of ??? appearing in human settlements but doing no harm—rather, they bond with the children.", "Les Baies en forme de crèmes glacées qui poussent sur son ventre sont le mets favori des Darumarond vivant à Galar.", ["Frost Tree Pokémon", "Pokémon Arbregelé"], null],
  "abomasnow": ["A powerful Pokémon that can split huge boulders with ease. Dislikes associating with others and chooses to live quietly deep within the mountains, playing with the snow.", "Ce grand Pokémon déclenche des blizzards. Lorsqu’il agite son corps, tout ce qui l’entoure se retrouve couvert de neige.", ["Frost Tree Pokémon", "Pokémon Arbregelé"], null],
  "weavile": ["This species corners prey as a pack, under the guidance of a leader. ??? displays increased cunning, leading me to speculate that its evolution caused further brain development.", "Il communique avec ses semblables en gravant des motifs avec ses griffes. Il existerait près de 500 signes différents.", ["Sharp Claw Pokémon", "Pokémon Grifacérée"], null],
  "magnezone": ["I theorize that a special magnetic field influenced this Pokémon, changing its molecular structure and causing it to evolve. It emits strange radio waves toward space from its antenna.", "On pense qu’il a évolué après avoir été exposé à un champ magnétique particulier qui a modifié la structure moléculaire de son corps.", ["Magnet Area Pokémon", "Pokémon Aimant"], null],
  "lickilicky": ["Its tongue can extend and contract freely, and it is capable of reaching lengths over 10 times ???'s height. Beware of the saliva, as it contains corrosive elements.", "Il est aussi habile avec sa langue que les êtres humains le sont avec leurs mains. En revanche, il est maladroit quand il utilise ses doigts.", ["Licking Pokémon", "Pokémon Lécheur"], null],
  "rhyperior": ["This Pokémon evolved through use of a curious item. Its rocklike hide is composed of a mysterious substance and can withstand a blow from a masterwork sword with nary a scratch.", "Il repousse les attaques avec ses Protecteurs et profite du moment où l’adversaire est déstabilisé pour le transpercer avec sa vrille, dont il est fier.", ["Drill Pokémon", "Pokémon Perceur"], null],
  "tangrowth": ["Draped with long vines, it resembles a shrub in appearance. It swings bundles of vines as though they were arms, wrapping them around prey to ensnare them.", "Ses lianes poussent plus rapidement s’il vit sous un climat chaud. Quand elles deviennent trop longues, il se les coupe.", ["Vine Pokémon", "Pokémon Vigne"], null],
  "electivire": ["Its evolution was induced by an unusual item, and its electrical output rises along with its heart rate. From its tails, it can unleash an electric current measuring 20,000 volts.", "La quantité d’électricité qu’il génère est énorme, même pour un Pokémon Électrik. Il inflige de fortes décharges du bout de ses queues.", ["Thunderbolt Pokémon", "Pokémon Foudrélec"], null],
  "magmortar": ["Use of a strange item caused this Pokémon to evolve. Fireballs launched from the ends of its tubelike arms are hot enough to melt an iron pot in an instant.", "Au fil du temps, son corps est devenu similaire à un volcan, et un de ses organes ressemble désormais à une chambre magmatique.", ["Blast Pokémon", "Pokémon Explosion"], null],
  "togekiss": ["Scant few have ever sighted this Pokémon. After studying what literature remains, I am certain ??? will reveal itself when peace reigns in the land.", "On dit que ce Pokémon dispense ses bienfaits, ce qui explique pourquoi il est représenté sur les porte-bonheurs depuis fort longtemps.", ["Jubilee Pokémon", "Pokémon Célébration"], null],
  "yanmega": ["Extremely violent. When hunting, it wastes none of its energy, aiming only for prey's most vulnerable spots. Any who manage to tame this Pokémon must be of incredible bravery.", "Il peut voler avec aise tout en portant un adulte dans ses six pattes. Les ailes de sa queue lui servent de balancier.", ["Ogre Darner Pokémon", "Pokémon Libellogre"], null],
  "leafeon": ["Cells similar to those of plants have been found in its fur. Its hard tail can fell a large tree with one stroke, and the tail's sharpness exceeds even that of a sword crafted by a master.", "Grâce à sa queue aussi effilée qu’une lame, il est capable de fendre en deux des arbres immenses.", ["Verdant Pokémon", "Pokémon Verdoyant"], null],
  "glaceon": ["??? is able to lower its body temperature very quickly. It freezes the atmosphere, creating diamond dust that glitters like gems while it flutters and dances around.", "Ce Pokémon exhale un vent glacial qui crée une neige poudreuse. Sa présence est très appréciée dans les stations de ski.", ["Fresh Snow Pokémon", "Pokémon Poudreuse"], null],
  "gliscor": ["It glides soundlessly on pitch-black wings and sinks sharp fangs into the throat of its prey. It takes on a look of satisfaction once it has entirely drained its prey of blood.", "Il vole sans un bruit, et capture ses proies avec sa queue pour leur infliger une morsure critique.", ["Fang Scorpion Pokémon", "Pokémon Scorpicroc"], null],
  "mamoswine": ["This species reached its zenith during the period known as the ice age. I suspect that Hisui's frigid climate is in harmony with ???'s constitution, thus awakening hidden potential.", "Comme son physique le laisse deviner, il est très fort. La taille de ses défenses de glace augmente à mesure que la température baisse.", ["Twin Tusk Pokémon", "Pokémon Deudéfenses"], null],
  "porygon-z": ["A curious item induced this evolution. The Pokémon's offensive capabilities have greatly increased, but the strangeness of its behavior has magnified in equal measure. This worries me.", "On dit qu’un nouveau programme l’a fait évoluer, mais les avis des scientifiques divergent quant à savoir s’il s’agit réellement d’une évolution.", ["Virtual Pokémon", "Pokémon Virtuel"], null],
  "gallade": ["The blades extending from its elbows are sharper than the finest swords. Its swordsmanship, albeit self-taught, is astonishingly impressive.", "Ses sens aiguisés lui indiquent lorsque quelqu’un est en danger. Il accourt alors à la rescousse.", ["Blade Pokémon", "Pokémon Lame"], null],
  "probopass": ["It is able to emit powerful magnetism, allowing it control over the iron sand that forms its luscious mustache. Using this iron sand, ??? forms hard stones with which it smites its prey.", "Il utilise ses trois petites unités pour combattre ses ennemis et capturer ses proies. Le reste de son corps se contente de donner des ordres.", ["Compass Pokémon", "Pokémon Boussole"], null],
  "dusknoir": ["Comes to those whose lives have come to an end and escorts their souls to the afterlife. Known to mistakenly take the souls of those who yet have life left in them, albeit rarely.", "Il dévore l’âme de ses ennemis en les engloutissant dans sa bouche ventrale. Il recrache ensuite leur enveloppe corporelle.", ["Gripper Pokémon", "Pokémon Mainpince"], null],
  "froslass": ["A Pokémon inhabited by the soul of a woman who died bearing a grudge in the snowy mountains. Legends of ??? placing deathly curses on misbehaving men send shivers down my spine.", "Il gèle ses proies avec son souffle à - 50 °C, les amène dans son antre, puis les y aligne avec soin.", ["Snow Land Pokémon", "Pokémon Enneigement"], null],
  "rotom": ["This bizarre Pokémon appears to be a will-o'-the-wisp powered by electricity. Be wary, as ??? is both smart and mischievous.", "Son corps composé de plasma lui permet d’infiltrer diverses machines. Il adore surprendre les gens.", ["Plasma Pokémon", "Pokémon Plasma"], null],
  "uxie": ["A Pokémon feared but also respected for stealing away the memories of evildoers. I have found records that suggest ??? holds dominion over knowledge.", "On dit que sa venue a fourni aux humains le bon sens nécessaire pour améliorer leur existence.", ["Knowledge Pokémon", "Pokémon Savoir"], null],
  "mesprit": ["Known as the Being of Emotion. In legend, this Pokémon was feared, as any who showed disrespect would have their emotions thrown into disarray.", "Il dort au fond d’un lac. On dit que son esprit abandonne son corps pour voler à sa surface.", ["Emotion Pokémon", "Pokémon Émotion"], null],
  "azelf": ["The dreaded Being of Willpower. Legends tell of this Pokémon manipulating the will of its adversaries and turning them into puppets of its own.", "On raconte que Créhelf, Créfollet et ??? proviennent du même Œuf.", ["Willpower Pokémon", "Pokémon Volonté"], null],
  "dialga": ["This Pokémon is revered as a deity in Hisuian legend. The birth of ??? was what caused the vast river of time to begin flowing in our world.", "Il peut contrôler le temps. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.", ["Temporal Pokémon", "Pokémon Temps"], null],
  "palkia": ["This Pokémon is feared as a deity in Hisuian legend. The birth of ??? was what caused the walls of our world to disappear, creating a sky that spans for infinity.", "Il peut modeler l’espace. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.", ["Spatial Pokémon", "Pokémon Espace"], null],
  "heatran": ["Stories tell of this Pokémon being birthed from the boiling magma within Mount Coronet. Its molten-steel body holds many mysteries.", "Le sang de ce Pokémon des cratères bouillonne dans son corps comme du magma.", ["Lava Dome Pokémon", "Pokémon Caldeira"], null],
  "regigigas": ["According to legend, ??? pulled landmasses together and bound them with rope to create the continent of Hisui. Though I have my doubts, the story could well contain a shred of truth.", "On raconte qu’après avoir créé des Pokémon avec différentes matières, il aurait placé les continents à leur position actuelle.", ["Colossal Pokémon", "Pokémon Prodigieux"], null],
  "giratina": ["There is one Hisuian verse that tells of a powerful light creating a deep shadow. I imagine that this deep shadow is ???.", "Sa grande violence lui a valu d’être banni. Il observe les hommes en silence depuis le Monde Distorsion.", ["Renegade Pokémon", "Pokémon Renégat"], null],
  "cresselia": ["??? is reminiscent of the crescent moon. It leaves a brilliant line of light in its wake as it flies across the night sky. I daresay it resembles the heavenly maiden who created the Milky Way.", "Dormir avec une de ses plumes à la main permet de faire de beaux rêves. On le surnomme « avatar du croissant de lune ».", ["Lunar Pokémon", "Pokémon Lunaire"], null],
  "phione": ["Can be seen floating offshore during seasons when the seas are warm. Its azure body blends in with the ocean waters—logic suggests this is a defense mechanism against natural predators.", "Ce Pokémon des mers chaudes revient toujours à son lieu de naissance, peu importe la distance.", ["Sea Drifter Pokémon", "Pokémon Dérivenmer"], null],
  "manaphy": ["Rumored to migrate across the oceans and visit Hisui's coastal waters only rarely. Although ??? resembles Phione, it is also quite different. The relation between the two is unclear.", "Il possède l’étrange pouvoir de s’entendre avec n’importe quel Pokémon.", ["Seafaring Pokémon", "Pokémon Voyagenmer"], null],
  "darkrai": ["On a moonless night, a strange incident occurred in which every one of a village's inhabitants suffered nightmares. The villagers attested that ??? appeared before them in these nightmares.", "Il a la capacité de bercer les gens pour les faire rêver. Il se montre durant les nuits de nouvelle lune.", ["Pitch-Black Pokémon", "Pokémon Noirtotal"], null],
  "shaymin": ["When the turning of seasons brings the cruel winter to its end and the joyous people give thanks to the heavens, ??? appears and covers the withered land with flowers.", "Il prend son essor pour répandre la gratitude lorsque les Gracidées fleurissent.", ["Gratitude Pokémon", "Pokémon Gratitude"], null],
  "arceus": ["It is the heavenly fount from which pours the light that shines across Hisui. Its luminance guides and protects all Pokémon. Hisuian mythology states that ??? is the creator of all things.", "Dans la mythologie, ce Pokémon existait déjà avant la formation de l’univers.", ["Alpha Pokémon", "Pokémon Alpha"], null],
  "victini": ["When it shares the infinite energy it creates, that being’s entire body will be overflowing with power.", "L’énergie sans limites qu’il produit donne une force incroyable à ceux qui entrent en contact avec elle.", ["Victory Pokémon", "Pokémon Victoire"], null],
  "snivy": ["They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.", "Il laisse sa queue prendre le soleil pour sa photosynthèse. Quand il est malade, sa queue pend tristement.", ["Grass Snake Pokémon", "Pokémon Serpenterbe"], null],
  "servine": ["When it gets dirty, its leaves can’t be used in photosynthesis, so it always keeps itself clean.", "La saleté l’empêchant d’utiliser la photosynthèse, il prend grand soin d’être toujours propre.", ["Grass Snake Pokémon", "Pokémon Serpenterbe"], null],
  "serperior": ["It can stop its opponents’ movements with just a glare. It takes in solar energy and boosts it internally.", "Il peut paralyser l’ennemi d’un regard. Il amplifie l’énergie du soleil dans son corps.", ["Regal Pokémon", "Pokémon Majestueux"], null],
  "tepig": ["It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.", "Il adore se goinfrer de Baies grillées, mais il lui arrive de les réduire en cendres dans son excitation.", ["Fire Pig Pokémon", "Pokémon Cochon Feu"], null],
  "pignite": ["When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.", "Quand le feu dans son corps s’embrase, sa vitesse et son agilité augmentent. En cas d’urgence, il crache de la fumée.", ["Fire Pig Pokémon", "Pokémon Cochon Feu"], null],
  "emboar": ["It has mastered fast and powerful fighting moves. It grows a beard of fire.", "Il a une barbe enflammée. Il maîtrise des techniques de combat au corps à corps rapides et puissantes.", ["Mega Fire Pig Pokémon", "Pokémon Grochon Feu"], null],
  "oshawott": ["This Pokémon from the Unova region uses the shell on its belly as a weapon to cut down its foes. Thus, I've conferred upon this shell the name ”scalchop”.", "Il combat avec le coupillage de son ventre. Il peut parer un assaut et immédiatement contre-attaquer.", ["Sea Otter Pokémon", "Pokémon Loutre"], null],
  "dewott": ["Its exquisite double-scalchop technique is likely the result of daily training, and it can send even masters of the blade fleeing in defeat.", "Chaque ??? a sa propre technique d’escrime au coupillage, acquise grâce à un entraînement drastique.", ["Discipline Pokémon", "Pokémon Entraînement"], null],
  "samurott": ["Hard of heart and deft of blade, this rare form of ??? is a product of the Pokémon's evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.", "Il peut terrasser ses ennemis d’un coup de la lame enchâssée dans son armure, et les faire taire d’un seul regard.", ["Formidable Pokémon", "Pokémon Dignitaire"], null],
  "patrat": ["Extremely cautious, one of them will always be on the lookout, but it won’t notice a foe coming from behind.", "Très prudent, il surveille attentivement son territoire, mais oublie souvent de regarder derrière lui.", ["Scout Pokémon", "Pokémon Espion"], null],
  "watchog": ["When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.", "Il attaque en crachant les graines des Baies qu’il accumule dans ses bajoues. S’il voit un ennemi, il dresse la queue.", ["Lookout Pokémon", "Pokémon Vigilant"], null],
  "lillipup": ["This Pokémon is far brighter than the average child, and ??? won’t forget the love it receives or any abuse it suffers.", "Ce Pokémon est plus intelligent que la plupart des enfants. Il n’oublie ni l’affection qu’il a reçue ni les mauvais traitements qu’il a pu subir.", ["Puppy Pokémon", "Pokémon Chiot"], null],
  "herdier": ["The black fur that covers this Pokémon’s body is dense and springy. Even sharp fangs bounce right off.", "Les poils sombres qui recouvrent son dos sont si épais et si souples qu’ils peuvent même repousser des crocs acérés.", ["Loyal Dog Pokémon", "Pokémon Chien Fidèle"], null],
  "stoutland": ["??? is immensely proud of its impressive moustache. It’s said that moustache length is what determines social standing among this species.", "Sa moustache remarquable fait sa fierté, car sa longueur permettrait de déterminer la hiérarchie au sein de l’espèce.", ["Big-Hearted Pokémon", "Pokémon Magnanime"], null],
  "purrloin": ["Opponents that get drawn in by its adorable behavior come away with stinging scratches from its claws and stinging pride from its laughter.", "Malheur à qui se laisse berner par ses gestes adorables : une fois les gens à sa portée, il les griffe sans crier gare, en ricanant.", ["Devious Pokémon", "Pokémon Scélérat"], null],
  "liepard": ["This stealthy Pokémon sneaks up behind prey without making any sound at all. It competes with Thievul for territory.", "Sans un bruit, il approche ses victimes par-derrière pour les frapper. Il dispute son territoire avec les Roublenard.", ["Cruel Pokémon", "Pokémon Implacable"], null],
  "pansage": ["It’s good at finding berries and gathers them from all over. It’s kind enough to share them with friends.", "Il est très doué pour trouver des Baies et aime les partager avec ses amis sans rien demander en échange.", ["Grass Monkey Pokémon", "Pokémon Singe Herbe"], null],
  "simisage": ["Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.", "Il a un tempérament violent et se bat avec sa queue pleine d’épines. La feuille sur sa tête est très amère.", ["Thorn Monkey Pokémon", "Pokémon Singépine"], null],
  "pansear": ["This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.", "Il vit dans les cratères des volcans. L’intérieur de la mèche qu’il a sur la tête peut atteindre 300 °C.", ["High Temp Pokémon", "Pokémon Brûlant"], null],
  "simisear": ["When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.", "Quand il est excité, des flammèches brûlantes dansent sur sa tête et sa queue. Il raffole des choses sucrées.", ["Ember Pokémon", "Pokémon Braise"], null],
  "panpour": ["The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.", "L’eau contenue dans la mèche sur sa tête est pleine de nutriments. Elle fait pousser les plantes avec vigueur.", ["Spray Pokémon", "Pokémon Jet d’Eau"], null],
  "simipour": ["It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.", "Il aime les endroits où l’eau est pure. Il se ravitaille en eau en l’aspirant avec sa queue.", ["Geyser Pokémon", "Pokémon Drainage"], null],
  "munna": ["It eats dreams and releases mist. The mist is pink when it’s eating a good dream, and black when it’s eating a nightmare.", "Il se nourrit de songes et expire de la fumée qui prend la couleur rose si le rêve est joyeux, ou noire s’il s’agit d’un cauchemar.", ["Dream Eater Pokémon", "Pokémon Mangerêve"], null],
  "musharna": ["It drowses and dreams all the time. It’s best to leave it be if it’s just woken up, as it’s a terrible grump when freshly roused from sleep.", "Il est sans cesse assoupi, plongé dans ses rêves. Il vaut mieux éviter de le déranger, car il est toujours mal luné au réveil.", ["Drowsing Pokémon", "Pokémon Rêveur"], null],
  "pidove": ["It’s forgetful and not very bright, but many Trainers love it anyway for its friendliness and sincerity.", "Il n’est pas très malin et un peu distrait, mais beaucoup de Dresseurs l’apprécient pour son caractère affectueux et sa bonne volonté.", ["Tiny Pigeon Pokémon", "Pokémon Tipigeon"], null],
  "tranquill": ["These bright Pokémon have acute memories. Apparently delivery workers often choose them as their partners.", "Il est intelligent et possède une bonne mémoire. On raconte que les livreurs le choisissent souvent comme partenaire.", ["Wild Pigeon Pokémon", "Pokémon Sauvapigeon"], null],
  "unfezant": ["This Pokémon is intelligent and intensely proud. People will sit up and take notice if you become the Trainer of one.", "Ce Pokémon est aussi intelligent qu’il est arrogant. Les Dresseurs de ??? sont tenus en haute estime.", ["Proud Pokémon", "Pokémon Fier"], null],
  "blitzle": ["Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.", "Sa crinière luit quand il lâche des décharges. Il module leur rythme et leur nombre pour communiquer avec ses pairs.", ["Electrified Pokémon", "Pokémon Étincélec"], null],
  "zebstrika": ["They have lightning-like movements. When ??? run at full speed, the sound of thunder reverberates.", "Il réagit à la vitesse de l’éclair. Lorsqu’il est en plein galop, on peut entendre le grondement du tonnerre.", ["Thunderbolt Pokémon", "Pokémon Foudrélec"], null],
  "roggenrola": ["When it detects a noise, it starts to move. The energy core inside it makes this Pokémon slightly warm to the touch.", "Il se déplace en réagissant aux sons environnants. Son noyau d’énergie rend son corps légèrement chaud au toucher.", ["Mantle Pokémon", "Pokémon Manteau"], null],
  "boldore": ["It relies on sound in order to monitor what’s in its vicinity. When angered, it will attack without ever changing the direction it’s facing.", "Il sonde les environs grâce au son. Lorsqu’un importun le met en colère, il se lance à sa poursuite sans changer l’orientation de son corps.", ["Ore Pokémon", "Pokémon Minerai"], null],
  "gigalith": ["Although its energy blasts can blow away a dump truck, they have a limitation— they can only be fired when the sun is out.", "Il est capable d’envoyer des boules d’énergie assez puissantes pour balayer un camion-benne, mais il ne peut tirer que les jours ensoleillés.", ["Compressed Pokémon", "Pokémon Surpression"], null],
  "woobat": ["It emits ultrasonic waves as it flutters about, searching for its prey—bug Pokémon.", "Il virevolte gaiement et émet des ultrasons pour trouver des Pokémon Insecte à grignoter.", ["Bat Pokémon", "Pokémon Chovsouris"], null],
  "swoobat": ["The auspicious shape of this Pokémon’s nose apparently led some regions to consider ??? a symbol of good luck.", "Certaines contrées le vénèrent et pensent que la forme de son nez est un symbole de chance et de bonheur.", ["Courting Pokémon", "Pokémon Cupidon"], null],
  "drilbur": ["It’s a digger, using its claws to burrow through the ground. It causes damage to vegetable crops, so many farmers have little love for it.", "Les cultivateurs le détestent, car il abîme leurs légumes en creusant la terre avec ses griffes.", ["Mole Pokémon", "Pokémon Taupe"], null],
  "excadrill": ["Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.", "On l’appelle le « roi de la vrille ». Il creuse la terre à une vitesse pouvant atteindre 150 km/h.", ["Subterrene Pokémon", "Pokémon Souterrain"], null],
  "audino": ["This Pokémon has a kind heart. By touching with its feelers, ??? can gauge other creatures’ feelings and physical conditions.", "Ce Pokémon gentil est capable de deviner les émotions et l’état de santé des autres rien qu’en les touchant avec ses antennes.", ["Hearing Pokémon", "Pokémon Audition"], null],
  "timburr": ["??? that have started carrying logs that are about three times their size are nearly ready to evolve.", "Lorsque ??? est capable de soulever une poutre faisant trois fois son poids, le jour de son évolution est proche.", ["Muscular Pokémon", "Pokémon Costaud"], null],
  "gurdurr": ["??? excels at demolition—construction is not its forte. In any case, there’s skill in the way this Pokémon wields its metal beam.", "Il manie la poutre métallique avec habileté. Il est doué pour démanteler une bâtisse, mais peu adroit lorsqu’il s’agit d’en construire une.", ["Muscular Pokémon", "Pokémon Costaud"], null],
  "conkeldurr": ["When going all out, this Pokémon throws aside its concrete pillars and leaps at opponents to pummel them with its fists.", "Quand il décide de passer aux choses sérieuses, il jette ses piliers de béton et saute sur son adversaire pour le frapper du poing.", ["Muscular Pokémon", "Pokémon Costaud"], null],
  "tympole": ["It uses sound waves to communicate with others of its kind. People and other Pokémon species can’t hear its cries of warning.", "Il communique avec ses compagnons en émettant des ondes. Son cri d’alerte est inaudible pour les humains et les autres Pokémon.", ["Tadpole Pokémon", "Pokémon Têtard"], null],
  "palpitoad": ["On occasion, their cries are sublimely pleasing to the ear. ??? with larger lumps on their bodies can sing with a wider range of sounds.", "Il lui arrive de pousser des cris ravissants. Plus ses protubérances sont grosses, plus le son porte loin.", ["Vibration Pokémon", "Pokémon Vibration"], null],
  "seismitoad": ["This Pokémon is popular among the elderly, who say the vibrations of its lumps are great for massages.", "Ce Pokémon est un excellent masseur grâce aux vibrations de ses pustules. Les personnes âgées l’apprécient particulièrement.", ["Vibration Pokémon", "Pokémon Vibration"], null],
  "throh": ["They train in groups of five. Any member that can’t keep up will discard its belt and leave the group.", "Ils s’entraînent intensément par groupes de cinq. Ceux qui ne peuvent pas suivre le rythme abandonnent leur ceinture et se retirent.", ["Judo Pokémon", "Pokémon Judo"], null],
  "sawk": ["The karate chops of a ??? that’s trained itself to the limit can cleave the ocean itself.", "Après avoir suivi un entraînement intensif, la puissance du tranchant de sa main est telle qu’il peut fendre la mer en deux.", ["Karate Pokémon", "Pokémon Karaté"], null],
  "sewaddle": ["Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.", "La mascotte des créateurs de mode. Il découpe ses vêtements dans les feuilles qu’il trouve.", ["Sewing Pokémon", "Pokémon Couture"], null],
  "swadloon": ["It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.", "Il se protège du froid en s’emmitouflant dans une feuille. Il se déplace en forêt et mange les feuilles tombées par terre.", ["Leaf-Wrapped Pokémon", "Pokémon Capefeuille"], null],
  "leavanny": ["It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.", "Il réchauffe les Œufs avec la chaleur de l’humus. Il fabrique des langes pour les Larveyette avec des feuilles.", ["Nurturing Pokémon", "Pokémon Précepteur"], null],
  "venipede": ["Its fangs are highly venomous. If this Pokémon finds prey it thinks it can eat, it leaps for them without any thought of how things might turn out.", "Ses crocs sont extrêmement venimeux. Dès qu’il voit une proie à son goût, il bondit sur elle sans penser aux conséquences.", ["Centipede Pokémon", "Pokémon Chilopode"], null],
  "whirlipede": ["??? protects itself with a sturdy shell and poisonous spikes while it stores up the energy it’ll need for evolution.", "Il se protège avec sa solide carapace et ses épines empoisonnées tandis qu’il rassemble l’énergie nécessaire à son évolution.", ["Curlipede Pokémon", "Pokémon Coconplopode"], null],
  "scolipede": ["??? engage in fierce territorial battles with Centiskorch. At the end of one of these battles, the victor makes a meal of the loser.", "Il défend son territoire avec acharnement contre son ennemi Scolocendre. Le perdant sert de dîner au vainqueur.", ["Megapede Pokémon", "Pokémon Mégaplopode"], null],
  "cottonee": ["Weaving together the cotton of both ??? and Eldegoss produces exquisite cloth that’s highly prized by many luxury brands.", "Les marques de luxe utilisent les étoffes splendides issues du mélange des cotons de ??? et de Blancoton.", ["Cotton Puff Pokémon", "Pokémon Boule Coton"], null],
  "whimsicott": ["As long as this Pokémon bathes in sunlight, its cotton keeps growing. If too much cotton fluff builds up, ??? tears it off and scatters it.", "Son coton se met à gonfler sous les rayons du soleil. Quand il est trop volumineux, il s’effiloche et se répand aux alentours.", ["Windveiled Pokémon", "Pokémon Vole Vent"], null],
  "petilil": ["The leaves on its head are highly valued for medicinal purposes. Dry the leaves in the sun, boil them, and then drink the bitter decoction for remarkably effective relief from fatigue.", "Plus ses feuilles sont foncées, plus il est en bonne santé. Il s’installe parfois dans les champs ou les parterres de fleurs bien entretenus.", ["Bulb Pokémon", "Pokémon Racine"], null],
  "lilligant": ["I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.", "L’huile essentielle extraite de sa fleur dégage un parfum exceptionnel, mais elle coûte extrêmement cher.", ["Flowering Pokémon", "Pokémon Chef-Fleur"], null],
  "basculin": ["Though it differs from other ??? in several respects, including demeanor—this one is gentle—I have categorized it as a regional form given the vast array of shared qualities.", "On l’utilisait autrefois en cuisine. La chair grasse des ??? à motif rouge était plutôt destinée aux jeunes.", ["Hostile Pokémon", "Pokémon Violent"], null],
  "sandile": ["??? is small, but its legs and lower body are powerful. Pushing sand aside as it goes, ??? moves through the desert as if it’s swimming.", "Malgré son petit gabarit, il a beaucoup de force dans les pattes arrière. Il parcourt le désert comme s’il nageait dans le sable.", ["Desert Croc Pokémon", "Pokémon Croco Sable"], null],
  "krokorok": ["Although this Pokémon has specialized eyes that allow it to see in the dark, ??? won’t move much at night—the desert gets cold after sunset.", "Bien que ses yeux particuliers lui permettent de voir dans l’obscurité, les nuits sont si froides dans le désert qu’il ne se déplace presque pas.", ["Desert Croc Pokémon", "Pokémon Croco Sable"], null],
  "krookodile": ["While terribly aggressive, ??? also has the patience to stay hidden under sand for days, lying in wait for prey.", "Il aime la violence, mais sait aussi se montrer patient lorsqu’il doit passer plusieurs jours dans le sable à attendre une proie.", ["Intimidation Pokémon", "Pokémon Intimidation"], null],
  "darumaka": ["This popular symbol of good fortune will never fall over in its sleep, no matter how it’s pushed or pulled.", "On a beau le pousser ou le tirer, quand il dort, rien ne le fait vaciller. Cette qualité lui a valu de devenir un emblème pour les porte-bonheurs.", ["Zen Charm Pokémon", "Pokémon Daruma"], null],
  "darmanitan": ["This Pokémon’s power level rises along with the temperature of its fire, which can reach 2,500 degrees Fahrenheit.", "Sa puissance augmente à mesure que la flamme de son corps s’intensifie. La température de celle-ci peut parfois dépasser les 1 400 °C.", ["Blazing Pokémon", "Pokémon Enflammé"], null],
  "maractus": ["Once each year, this Pokémon scatters its seeds. They’re jam-packed with nutrients, making them a precious food source out in the desert.", "Il sème les graines de ses fleurs une fois par an. Celles-ci abondent en nutriments et représentent une denrée précieuse dans le désert.", ["Cactus Pokémon", "Pokémon Cactus"], null],
  "dwebble": ["It first tries to find a rock to live in, but if there are no suitable rocks to be found, ??? may move in to the ports of a Hippowdon.", "S’il ne trouve pas de bon caillou à creuser pour s’y loger, il élit domicile dans un des trous du corps d’Hippodocus.", ["Rock Inn Pokémon", "Pokémon Lithicole"], null],
  "crustle": ["Its thick claws are its greatest weapons. They’re mighty enough to crack Rhyperior’s carapace.", "Ses meilleures armes sont ses pinces. Elles sont si dures qu’elles peuvent ébrécher les Protecteurs de Rhinastoc.", ["Stone Home Pokémon", "Pokémon Lapidicole"], null],
  "scraggy": ["It protects itself with its durable skin. It’s thought that this Pokémon will evolve once its skin has completely stretched out.", "Il se protège grâce à sa peau robuste. On dit que quand celle-ci ne peut plus s’étirer davantage, c’est qu’il est sur le point d’évoluer.", ["Shedding Pokémon", "Pokémon Mue"], null],
  "scrafty": ["While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.", "Il est de nature violente, mais au fond de lui, il tient à sa famille, à ses amis et à son territoire.", ["Hoodlum Pokémon", "Pokémon Gang"], null],
  "sigilyph": ["A discovery was made in the desert where ??? fly. The ruins of what may have been an ancient city were found beneath the sands.", "En fouillant sous le sable du désert survolé par ???, on a retrouvé les vestiges de ce que l’on croit être une ville antique.", ["Avianoid Pokémon", "Pokémon Similoiseau"], null],
  "yamask": ["The spirit of a person from a bygone age became this Pokémon. It rambles through ruins, searching for someone who knows its face.", "Il est né de l’âme d’un être humain d’un peuple antique. Il erre dans les ruines à la recherche de quiconque reconnaîtra son visage.", ["Spirit Pokémon", "Pokémon Âme"], null],
  "cofagrigus": ["There are many depictions of ??? decorating ancient tombs. They’re symbols of the wealth that kings of bygone eras had.", "On le voit souvent représenté sur les murs des vieilles sépultures des rois en tant que symbole de leur richesse.", ["Coffin Pokémon", "Pokémon Cercueil"], null],
  "tirtouga": ["??? is considered to be the ancestor of many turtle Pokémon. It was restored to life from a fossil.", "Ancêtre présumé de nombreuses espèces de Pokémon tortues, il a été restauré à partir d’un fossile.", ["Prototurtle Pokémon", "Pokémon Tortantique"], null],
  "carracosta": ["This Pokémon emerges from the water in search of prey despite the fact that it moves more slowly on land.", "Bien qu’il soit moins à l’aise sur terre que dans l’eau, il s’aventure sur le rivage pour se nourrir.", ["Prototurtle Pokémon", "Pokémon Tortantique"], null],
  "archen": ["??? is said to be the ancestor of bird Pokémon. It lived in treetops, eating berries and bug Pokémon.", "On dit que c’est l’ancêtre des Pokémon oiseaux. Il vivait à la cime des arbres et se nourrissait de Baies et de Pokémon Insecte.", ["First Bird Pokémon", "Pokémon Oisancien"], null],
  "archeops": ["Though capable of flight, ??? was apparently better at hunting on the ground.", "Il savait voler, mais il semble qu’il était beaucoup plus doué pour chasser ses proies sur la terre ferme.", ["First Bird Pokémon", "Pokémon Oisancien"], null],
  "trubbish": ["This Pokémon was born from a bag stuffed with trash. Galarian Weezing relish the fumes belched by ???.", "Il est né d’un sac poubelle rempli d’ordures. Le gaz empoisonné qu’il exhale est très apprécié des Smogogo de Galar.", ["Trash Bag Pokémon", "Pokémon Sac Poubelle"], null],
  "garbodor": ["The toxic liquid it launches from its right arm is so virulent that it can kill a weakened creature instantly.", "Le liquide qu’il projette de son bras droit est si toxique que si une créature fragile en est aspergée, elle succombe sur-le-champ.", ["Trash Heap Pokémon", "Pokémon Dépotoir"], null],
  "zorua": ["A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, ??? vents lingering malice.", "Il lui arrive de se changer en être humain, surtout en enfant, pour venir chercher de la nourriture en ville.", ["Tricky Fox Pokémon", "Pokémon Sombrenard"], null],
  "zoroark": ["With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, ??? attacks its nemeses with a bitter energy so intense, it lacerates ???'s own body.", "Les Dresseurs en manque de compagnie ordonnent à ??? de leur montrer une illusion pour tromper leur solitude.", ["Illusion Fox Pokémon", "Pokémon Polymorfox"], null],
  "minccino": ["They pet each other with their tails as a form of greeting. Of the two, the one whose tail is fluffier is a bit more boastful.", "Les ??? se saluent en se frottant la queue. Celui qui a la plus volumineuse en tire une certaine fierté.", ["Chinchilla Pokémon", "Pokémon Chinchilla"], null],
  "cinccino": ["A special oil that seeps through their fur helps them avoid attacks. The oil fetches a high price at market.", "La sécrétion huileuse de ses poils lui permet de dévier les attaques. Elle s’arrache à prix d’or sur les marchés.", ["Scarf Pokémon", "Pokémon Écharpe"], null],
  "gothita": ["Even when nobody seems to be around, ??? can still be heard making a muted cry. Many believe it’s speaking to something only it can see.", "Parfois, ce Pokémon chuchote alors qu’il n’y a personne aux alentours. On raconte qu’il parle à une entité que personne ne peut voir.", ["Fixation Pokémon", "Pokémon Dévisageur"], null],
  "gothorita": ["On nights when the stars shine, this Pokémon’s psychic power is at its strongest. It’s unknown just what link ??? has to the greater universe.", "Ses pouvoirs psychiques semblent atteindre leur paroxysme pendant les nuits étoilées, mais nul ne sait s’il a un rapport avec l’espace.", ["Manipulate Pokémon", "Pokémon Magouilleur"], null],
  "gothitelle": ["A criminal who was shown his fate by a ??? went missing that same day and was never seen again.", "Les criminels à qui ??? a révélé les derniers instants de leur vie ont tous été portés disparus le jour même.", ["Astral Body Pokémon", "Pokémon Cosmique"], null],
  "solosis": ["Many say that the special liquid covering this Pokémon’s body would allow it to survive in the vacuum of space.", "On raconte que le curieux fluide qui entoure le corps de ce Pokémon lui permet de survivre dans l’espace.", ["Cell Pokémon", "Pokémon Cellule"], null],
  "duosion": ["Its brain has split into two, and the two halves rarely think alike. Its actions are utterly unpredictable.", "Étant donné que ses deux cerveaux sont rarement sur la même longueur d’onde, il est impossible de prédire son comportement.", ["Mitosis Pokémon", "Pokémon Divisé"], null],
  "reuniclus": ["It’s said that drinking the liquid surrounding ??? grants wisdom. Problem is, the liquid is highly toxic to anything besides ??? itself.", "S’il ne s’agissait pas d’un poison violent que seul ??? peut boire, son curieux fluide pourrait, selon les dires, rendre plus intelligent.", ["Multiplying Pokémon", "Pokémon Multiplié"], null],
  "ducklett": ["They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.", "Un Pokémon doué pour la plongée qui passe son temps sous l’eau à chercher des sphaignes, son plat préféré.", ["Water Bird Pokémon", "Pokémon Oiseaudo"], null],
  "swanna": ["??? start to dance at dusk. The one dancing in the middle is the leader of the flock.", "Ils se mettent à danser à la tombée de la nuit. Le ??? qui danse au centre est le chef de la troupe.", ["White Bird Pokémon", "Pokémon Cygne"], null],
  "vanillite": ["Supposedly, this Pokémon was born from an icicle. It spews out freezing air at −58 degrees Fahrenheit to make itself more comfortable.", "On raconte qu’il est né de stalactites. Il gèle les alentours en soufflant de l’air à - 50 °C pour améliorer son confort.", ["Fresh Snow Pokémon", "Pokémon Poudreuse"], null],
  "vanillish": ["It blasts enemies with cold air reaching −148 degrees Fahrenheit, freezing them solid. But it spares their lives afterward—it’s a kind Pokémon.", "Bien qu’il gèle ses ennemis en soufflant de l’air à - 100 °C, sa gentillesse l’empêche de leur ôter la vie.", ["Icy Snow Pokémon", "Pokémon Grêle"], null],
  "vanilluxe": ["People believe this Pokémon formed when two Vanillish stuck together. Its body temperature is roughly 21 degrees Fahrenheit.", "La température de son corps est d’environ - 6 °C. On raconte que ce Pokémon naît lorsque deux Sorboul se collent l’un à l’autre.", ["Snowstorm Pokémon", "Pokémon Congère"], null],
  "deerling": ["The turning of the seasons changes the color and scent of this Pokémon’s fur. People use it to mark the seasons.", "Quand la saison change, il change de pelage et d’odeur. Un Pokémon qui annonce le passage des saisons.", ["Season Pokémon", "Pokémon Saison"], null],
  "sawsbuck": ["They migrate according to the seasons, so some people call ??? the harbingers of spring.", "Il change d’habitat selon les saisons. Certains disent même qu’il est celui qui apporte le printemps.", ["Season Pokémon", "Pokémon Saison"], null],
  "emolga": ["This Pokémon absolutely loves sweet berries. Sometimes it stuffs its cheeks full of so much food that it can’t fly properly.", "Les Baies sucrées sont son péché mignon. Il lui arrive d’en conserver beaucoup trop dans ses bajoues, ce qui l’empêche de bien planer.", ["Sky Squirrel Pokémon", "Pokémon Pteromys"], null],
  "karrablast": ["It spits a liquid from its mouth to melt through Shelmet’s shell. ??? doesn’t eat the shell— it eats only the contents.", "Il crache un liquide qui dissout les coquilles des Escargaume pour se régaler de leur contenu.", ["Clamping Pokémon", "Pokémon Carabe"], null],
  "escavalier": ["It charges its enemies, lances at the ready. An image of one of its duels is captured in a famous painting of ??? clashing with Sirfetch’d.", "Il charge ses ennemis en brandissant ses lances. Il existe un célèbre tableau représentant la joute entre un ??? et un Palarticho.", ["Cavalry Pokémon", "Pokémon Chevalier"], null],
  "foongus": ["The spores released from this Pokémon’s hands are highly poisonous, but when thoroughly dried, the spores can be used as stomach medicine.", "Les spores qu’il libère de ses mains sont très toxiques, mais si on les sèche bien, elles peuvent soulager les maux de ventre.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "amoonguss": ["??? generally doesn’t move much. It tends to stand still near Poké Balls that have been dropped on the ground.", "Ce Pokémon a tendance à très peu se déplacer. Quand il voit une Poké Ball abandonnée au sol, il reste immobile à côté.", ["Mushroom Pokémon", "Pokémon Champignon"], null],
  "frillish": ["Legend has it that the residents of a sunken ancient city changed into these Pokémon.", "Certaines légendes racontent que les ??? sont les habitants d’une ancienne cité engloutie qui ont été changés en Pokémon.", ["Floating Pokémon", "Pokémon Flottaison"], null],
  "jellicent": ["Whenever a full moon hangs in the night sky, schools of ??? gather near the surface of the sea, waiting for their prey to appear.", "Les nuits de pleine lune, ils se réunissent à la surface de la mer pour attendre leurs proies.", ["Floating Pokémon", "Pokémon Flottaison"], null],
  "alomomola": ["The reason it helps Pokémon in a weakened condition is that any Pokémon coming after them may also attack ???.", "On pense qu’il protège les Pokémon affaiblis parce qu’il partage avec eux les mêmes prédateurs.", ["Caring Pokémon", "Pokémon Soigneur"], null],
  "joltik": ["??? latch on to other Pokémon and suck out static electricity. They’re often found sticking to Yamper’s hindquarters.", "Il s’accroche aux autres Pokémon pour aspirer leur électricité statique. On en trouve souvent collés au postérieur de Voltoutou.", ["Attaching Pokémon", "Pokémon Crampon"], null],
  "galvantula": ["It lays traps of electrified threads near the nests of bird Pokémon, aiming to snare chicks that are not yet good at flying.", "Il piège les oisillons qui ne savent pas encore voler en tissant une toile électrique près des nids des Pokémon oiseaux.", ["EleSpider Pokémon", "Pokémon Araclectrik"], null],
  "ferroseed": ["Mossy caves are their preferred dwellings. Enzymes contained in mosses help ???’s spikes grow big and strong.", "Il aime les grottes pleines de mousse. Les enzymes contenues dans ces plantes l’aident à obtenir des épines grandes et solides.", ["Thorn Seed Pokémon", "Pokémon Graine Épine"], null],
  "ferrothorn": ["Its spikes are harder than steel. This Pokémon crawls across rock walls by stabbing the spikes on its feelers into the stone.", "Ses épines sont plus solides que l’acier. Il plante celles de ses tentacules dans les parois rocheuses pour se déplacer.", ["Thorn Pod Pokémon", "Pokémon Boule Épine"], null],
  "klink": ["It’s suspected that ??? were the inspiration behind ancient people’s invention of the first gears.", "Les humains auraient inventé les mécanismes à engrenages il y a fort longtemps, en observant ce Pokémon.", ["Gear Pokémon", "Pokémon Engrenage"], null],
  "klang": ["Many companies in the Galar region choose ??? as their logo. This Pokémon is considered the symbol of industrial technology.", "Ce Pokémon symbolisant la technologie industrielle est souvent utilisé dans le logo des entreprises de Galar.", ["Gear Pokémon", "Pokémon Engrenage"], null],
  "klinklang": ["The three gears that compose this Pokémon spin at high speed. Its new spiked gear isn’t a living creature.", "Bien que son nouveau rouage à pointes ne soit pas doué de vie, il parvient à le faire tourner à grande vitesse avec les deux autres.", ["Gear Pokémon", "Pokémon Engrenage"], null],
  "tynamo": ["One alone can emit only a trickle of electricity, so a group of them gathers to unleash a powerful electric shock.", "Tout seul, il ne dégage pas beaucoup d’électricité. Mais un banc d’??? produit des décharges surpuissantes.", ["EleFish Pokémon", "Pokémon Électrophore"], null],
  "eelektrik": ["These Pokémon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.", "Un Pokémon doté d’un gros appétit. Il paralyse ses proies avec des décharges électriques avant de les manger.", ["EleFish Pokémon", "Pokémon Électrophore"], null],
  "eelektross": ["They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.", "Il peut sortir de l’eau à la force de ses bras pour attraper des proies sur la rive. Il retourne à l’eau en un instant.", ["EleFish Pokémon", "Pokémon Électrophore"], null],
  "elgyem": ["This Pokémon was discovered about 50 years ago. Its highly developed brain enables it to exert its psychic powers.", "Ce Pokémon a été découvert il y a environ 50 ans. Son cerveau surdéveloppé lui permet d’utiliser ses pouvoirs psychiques avec aisance.", ["Cerebral Pokémon", "Pokémon Cerveau"], null],
  "beheeyem": ["Sometimes found drifting above wheat fields, this Pokémon can control the memories of its opponents.", "Il peut manipuler les souvenirs de son adversaire à loisir. Parfois, on l’aperçoit en train de vagabonder au-dessus des champs de blé.", ["Cerebral Pokémon", "Pokémon Cerveau"], null],
  "litwick": ["The younger the life this Pokémon absorbs, the brighter and eerier the flame on its head burns.", "Plus les victimes dont il aspire l’énergie vitale sont jeunes, plus sa flamme grandit et luit lugubrement.", ["Candle Pokémon", "Pokémon Chandelle"], null],
  "lampent": ["It lurks in cities, pretending to be a lamp. Once it finds someone whose death is near, it will trail quietly after them.", "Il se cache en ville en se faisant passer pour un lampadaire. Lorsqu’il repère une personne dont l’heure est proche, il la suit en catimini.", ["Lamp Pokémon", "Pokémon Lampe"], null],
  "chandelure": ["In homes illuminated by ??? instead of lights, funerals were a constant occurrence— or so it’s said.", "On raconte que dans les manoirs éclairés par des ???, les funérailles s’enchaînent sans discontinuer.", ["Luring Pokémon", "Pokémon Invitation"], null],
  "axew": ["They play with each other by knocking their large tusks together. Their tusks break sometimes, but they grow back so quickly that it isn’t a concern.", "Il joue avec ses congénères à se donner de grands coups de crocs. Peu importe s’ils se cassent : ils repousseront aussitôt.", ["Tusk Pokémon", "Pokémon Crocs"], null],
  "fraxure": ["Its skin is as hard as a suit of armor. ???’s favorite strategy is to tackle its opponents, stabbing them with its tusks at the same time.", "Son épiderme est dur comme une armure. Il est passé maître dans l’art de charger l’ennemi tout en le transperçant de ses crocs.", ["Axe Jaw Pokémon", "Pokémon Hachomenton"], null],
  "haxorus": ["While usually kindhearted, it can be terrifying if angered. Tusks that can slice through steel beams are how ??? deals with its adversaries.", "D’un naturel doux, il est cependant redoutable lorsqu’il se fâche. Il est très fier de ses crocs qui peuvent même découper des poutres d’acier.", ["Axe Jaw Pokémon", "Pokémon Hachomenton"], null],
  "cubchoo": ["It sniffles before performing a move, using its frosty snot to provide an icy element to any move that needs it.", "Il renifle avant d’utiliser une capacité. Le froid intense contenu dans sa morve lui permet de lancer les capacités de type Glace.", ["Chill Pokémon", "Pokémon Gelé"], null],
  "beartic": ["It swims energetically through frigid seas. When it gets tired, it freezes the seawater with its breath so it can rest on the ice.", "Il sillonne les mers glaciales avec aisance. Quand il est fatigué, il gèle l’eau de mer d’un souffle et se repose sur l’iceberg improvisé.", ["Freezing Pokémon", "Pokémon Congelé"], null],
  "cryogonal": ["When the weather gets hot, these Pokémon turn into water vapor. ??? are almost never seen during summer.", "Lorsqu’il fait trop chaud, il s’évapore, ce qui explique pourquoi on ne le voit presque pas en été.", ["Crystallizing Pokémon", "Pokémon Cristal"], null],
  "shelmet": ["It has a strange physiology that responds to electricity. When together with Karrablast, ??? evolves for some reason.", "Il a l’étrange faculté de réagir à l’énergie électrique. On ne sait trop pourquoi, mais quand il se trouve aux côtés de Carabing, il évolue.", ["Snail Pokémon", "Pokémon Escargot"], null],
  "accelgor": ["Discarding its shell made it nimble. To keep itself from dehydrating, it wraps its body in bands of membrane.", "Il est bien plus agile sans sa coquille. La membrane en forme de bandelettes qui l’entoure l’empêche de se dessécher.", ["Shell Out Pokémon", "Pokémon Exuviateur"], null],
  "stunfisk": ["For some reason, this Pokémon smiles slightly when it emits a strong electric current from the yellow markings on its body.", "Lorsque les parties jaunes de son corps envoient une puissante décharge électrique, il ébauche un sourire. Personne ne sait pourquoi.", ["Trap Pokémon", "Pokémon Piège"], null],
  "mienfoo": ["Though small, ???’s temperament is fierce. Any creature that approaches ??? carelessly will be greeted with a flurry of graceful attacks.", "De nature brutale malgré sa petite taille, il inflige une série de coups majestueux aux inconscients qui s’approchent trop près de lui.", ["Martial Arts Pokémon", "Pokémon Art Martial"], null],
  "mienshao": ["Delivered at blinding speeds, kicks from this Pokémon can shatter massive boulders into tiny pieces.", "Ses coups de pied ultrarapides et invisibles à l’œil nu peuvent réduire un énorme rocher en poussière.", ["Martial Arts Pokémon", "Pokémon Art Martial"], null],
  "druddigon": ["??? are vicious and cunning. They take up residence in nests dug out by other Pokémon, treating the stolen nests as their own lairs.", "Féroce et perfide, ??? s’approprie les terriers creusés par d’autres Pokémon pour en faire son antre.", ["Cave Pokémon", "Pokémon Caverne"], null],
  "golett": ["This Pokémon was created from clay. It received orders from its master many thousands of years ago, and it still follows those orders to this day.", "Ce Pokémon fait d’argile continue de respecter les ordres que son maître lui a donnés il y a quelques millénaires.", ["Automaton Pokémon", "Pokémon Golem Ancien"], null],
  "golurk": ["There’s a theory that inside ??? is a perpetual motion machine that produces limitless energy, but this belief hasn’t been proven.", "Son énergie viendrait d’un mécanisme à mouvement perpétuel interne, mais jusqu’à présent, personne n’en a la preuve.", ["Automaton Pokémon", "Pokémon Golem Ancien"], null],
  "pawniard": ["A pack of these Pokémon forms to serve a Bisharp boss. Each ??? trains diligently, dreaming of one day taking the lead.", "Il vit en meute, sous les ordres d’un Scalproie. Il s’entraîne sans relâche en rêvant du jour où il sera chef de meute à son tour.", ["Sharp Blade Pokémon", "Pokémon Coupant"], null],
  "bisharp": ["Violent conflicts erupt between ??? and Fraxure over places where sharpening stones can be found.", "Sa recherche des meilleurs endroits où trouver des pierres pour affûter ses lames le conduit souvent à affronter des Incisache.", ["Sword Blade Pokémon", "Pokémon Tranchant"], null],
  "bouffalant": ["These Pokémon live in herds of about 20 individuals. ??? that betray the herd will lose the hair on their heads for some reason.", "Les ??? vivent en troupeau d’une vingtaine d’individus. Pour une raison inconnue, si l’un d’eux trahit le groupe, il perd sa crinière.", ["Bash Buffalo Pokémon", "Pokémon Coup d’Bœuf"], null],
  "rufflet": ["Its chick-like looks belie its hotheadedness. It challenges its parents at every opportunity, desperate to prove its strength.", "Sa poigne est telle qu’il peut réduire en miettes les plus dures des Baies. Belliqueux de nature, il n’hésite pas à défier tout le monde.", ["Eaglet Pokémon", "Pokémon Aiglon"], null],
  "braviary": ["Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water's surface.", "Son caractère agressif et violent lui a valu de perdre son rôle de transporteur à Galar au profit de Corvaillus.", ["Valiant Pokémon", "Pokémon Vaillant"], null],
  "vullaby": ["??? grow quickly. Bones that have gotten too small for older ??? to wear often get passed down to younger ones in the nest.", "Il grandit vite. Au sein du nid, les petits ??? héritent des couches en crâne de leurs aînés.", ["Diapered Pokémon", "Pokémon Couche"], null],
  "mandibuzz": ["They adorn themselves with bones. There seem to be fashion trends among them, as different bones come into and fall out of popularity.", "Il se pare d’ossements qu’il a ramassés. Il semblerait qu’il choisisse la forme des os qu’il porte selon les dernières tendances.", ["Bone Vulture Pokémon", "Pokémon Vostour"], null],
  "heatmor": ["A flame serves as its tongue, melting through the hard shell of Durant so that ??? can devour their insides.", "Il se sert de sa flamme comme d’une langue. Il fait fondre peu à peu l’exosquelette des Fermite pour se délecter de leur chair.", ["Anteater Pokémon", "Pokémon Tamanoir"], null],
  "durant": ["With their large mandibles, these Pokémon can crunch their way through rock. They work together to protect their eggs from Sandaconda.", "Sa grande mâchoire réduit même les rochers en miettes. Il se bat avec sa colonie pour protéger ses Œufs des attaques des Dunaconda.", ["Iron Ant Pokémon", "Pokémon Fourmi Dure"], null],
  "deino": ["Because it can’t see, this Pokémon is constantly biting at everything it touches, trying to keep track of its surroundings.", "Comme il ne voit rien, il se repère en mâchouillant tout ce qui se trouve autour de lui.", ["Irate Pokémon", "Pokémon Rude"], null],
  "zweilous": ["Their two heads will fight each other over a single piece of food. ??? are covered in scars even without battling others.", "Ses deux têtes se disputent la même proie. Il est toujours couvert de blessures, même s’il n’a affronté personne.", ["Hostile Pokémon", "Pokémon Violent"], null],
  "hydreigon": ["The three heads take turns sinking their teeth into the opponent. Their attacks won’t slow until their target goes down.", "Chacune de ses trois têtes mord à tour de rôle. Il attaque ses adversaires sans relâche, jusqu’à ce qu’ils s’écroulent.", ["Brutal Pokémon", "Pokémon Brutal"], null],
  "larvesta": ["???’s body is warm all over. It spouts fire from the tips of its horns to intimidate predators and scare prey.", "La température de son corps est très élevée. Il projette des flammes du bout de ses cornes pour intimider ses ennemis et ses proies.", ["Torch Pokémon", "Pokémon Torche"], null],
  "volcarona": ["This Pokémon emerges from a cocoon formed of raging flames. Ancient murals depict ??? as a deity of fire.", "Né d’un cocon enflammé, ce Pokémon apparaît sur d’anciennes fresques représenté comme une divinité du feu.", ["Sun Pokémon", "Pokémon Soleil"], null],
  "cobalion": ["From the moment it’s born, this Pokémon radiates the air of a leader. Its presence will calm even vicious foes.", "Dès la naissance, il a un air de chef. Même le plus terrible des adversaires file doux face à lui.", ["Iron Will Pokémon", "Pokémon Cœur de Fer"], null],
  "terrakion": ["In Unovan legend, ??? battled against humans in an effort to protect other Pokémon.", "Selon une légende d’Unys, ??? se serait jadis dressé contre les humains pour protéger les Pokémon.", ["Cavern Pokémon", "Pokémon Grotte"], null],
  "virizion": ["It darts around opponents with a flurry of quick movements, slicing them up with its horns.", "Rapide comme le vent, il s’abat tel un tourbillon sur ses ennemis avant de les transpercer sans pitié de ses cornes acérées.", ["Grassland Pokémon", "Pokémon Plaine Verte"], null],
  "tornadus": ["This storm-stirring Pokémon is said to cause the seasons to turn by whipping up the air. I suspect its humanlike form to be a false one.", "L’énergie dégagée par sa queue provoque d’énormes tempêtes dont la force peut renverser des maisons.", ["Cyclone Pokémon", "Pokémon Tornade"], null],
  "thundurus": ["They say this wielder of electricity has waged war with its nemesis, Tornadus, since time immemorial. The lightning bolts it hurls pierce the very earth and enrich the soil.", "Il vole dans le ciel d’Unys et fait tomber des éclairs, provoquant des incendies qui font sa mauvaise réputation.", ["Bolt Strike Pokémon", "Pokémon Foudroyeur"], null],
  "reshiram": ["According to myth, if people ignore truth and let themselves become consumed by greed, ??? will arrive to burn their kingdoms down.", "Selon un mythe, lorsque les gens ne font aucun cas de la Réalité et s’abandonnent à la cupidité, ??? rase le pays entier avec ses flammes.", ["Vast White Pokémon", "Pokémon Blanc Réel"], null],
  "zekrom": ["Mythology tells us that if people lose the righteousness in their hearts, their kingdoms will be razed by ???’s lightning.", "Selon la légende, lorsque les gens perdent tout sens de ce qui est juste, ??? réduit le pays entier en cendres avec de terribles éclairs.", ["Deep Black Pokémon", "Pokémon Noir Idéal"], null],
  "landorus": ["When the incarnations of wind and of lightning clash, ??? arrives to quell the conflict. After the tempests and thunderbolts abate, the land is sure to be blessed with bountiful harvests.", "Il utilise l’énergie qu’il tire du vent et de la foudre pour enrichir les sols en nutriments pour les cultures.", ["Abundance Pokémon", "Pokémon Fertilité"], null],
  "kyurem": ["It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.", "Il se serait congelé lui-même avec son souffle glacé pour stabiliser sa structure cellulaire.", ["Boundary Pokémon", "Pokémon Frontière"], null],
  "keldeo": ["They say that ??? must survive harsh battles and fully develop the horn on its forehead before this Pokémon’s true power will awaken.", "Lorsqu’il livre un combat difficile, la corne sur son front se renforce et se développe, ce qui éveillerait sa véritable puissance.", ["Colt Pokémon", "Pokémon Poulain"], null],
  "meloetta": ["Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.", "Sa voix si particulière lui permet de chanter des mélodies qui ensorcellent les gens et modifient leurs émotions.", ["Melody Pokémon", "Pokémon Mélodie"], null],
  "genesect": ["This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.", "Un Pokémon existant depuis 300 millions d’années, et modifié par la Team Plasma. Il a maintenant un canon dans le dos.", ["Paleozoic Pokémon", "Pokémon Paléozoïque"], null],
  "chespin": ["Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn’t faze it.", "Sa tête et son dos sont recouverts d’une carapace tellement dure que même une collision avec un camion ne lui ferait rien.", ["Spiny Nut Pokémon", "Pokémon Bogue"], null],
  "quilladin": ["They strengthen their lower bodies by running into one another. They are very kind and won’t start fights.", "Il renforce ses membres inférieurs en se ruant violemment sur ses congénères. Naturellement paisible, il ne provoque jamais un combat.", ["Spiny Armor Pokémon", "Pokémon Épinarmure"], null],
  "chesnaught": ["When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.", "Il se défend en joignant ses poings devant son visage. Dans cette posture, il peut même résister à l’onde de choc d’une explosion.", ["Spiny Armor Pokémon", "Pokémon Épinarmure"], null],
  "fennekin": ["As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.", "Il a toujours une brindille avec lui en cas de petit creux. Il projette de l’air chaud par ses oreilles pour intimider ses ennemis.", ["Fox Pokémon", "Pokémon Renard"], null],
  "braixen": ["When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.", "Quand il saisit la branche plantée dans sa queue, elle prend feu par friction. Il peut communiquer avec ses congénères en agitant ce bâton enflammé.", ["Fox Pokémon", "Pokémon Renard"], null],
  "delphox": ["Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.", "Ses pouvoirs psychiques lui permettent de créer des tourbillons de flammes à 3 000 °C qui enveloppent et consument ses ennemis.", ["Fox Pokémon", "Pokémon Renard"], null],
  "froakie": ["It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.", "Il protège son corps en l’entourant d’une mousse délicate. Malgré son apparence insouciante, ce Pokémon est en fait constamment à l’affût.", ["Bubble Frog Pokémon", "Pokémon Crapobulle"], null],
  "frogadier": ["Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute’s time.", "Son agilité est incomparable. Il peut gravir une tour de 600 m de haut en moins d’une minute.", ["Bubble Frog Pokémon", "Pokémon Crapobulle"], null],
  "greninja": ["It appears and vanishes with a ninja’s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.", "Aussi insaisissable qu’un ninja, il se joue de ses ennemis grâce à sa célérité, et les tranche de ses Sheauriken.", ["Ninja Pokémon", "Pokémon Ninja"], null],
  "bunnelby": ["It’s very sensitive to danger. The sound of Corviknight’s flapping will have ??? digging a hole to hide underground in moments.", "Il est sensible au danger. Lorsqu’il entend le battement d’ailes de Corvaillus, il creuse prestement un terrier et s’y cache.", ["Digging Pokémon", "Pokémon Fouisseur"], null],
  "diggersby": ["The fur on its belly retains heat exceptionally well. People used to make heavy winter clothing from fur shed by this Pokémon.", "La fourrure de son ventre est un excellent isolant thermique. Jadis, on fabriquait des vêtements chauds en se servant de sa mue.", ["Digging Pokémon", "Pokémon Fouisseur"], null],
  "fletchling": ["When this Pokémon gets excited, its body temperature increases sharply. If you touch a ??? with bare hands, you might get burned.", "Quand il est surexcité, sa température corporelle augmente d’un coup, à tel point qu’il est possible de se brûler en le touchant à mains nues.", ["Tiny Robin Pokémon", "Pokémon Rougegorge"], null],
  "fletchinder": ["??? are exceedingly territorial and aggressive. These Pokémon fight among themselves over feeding grounds.", "De nature belliqueuse, il dispose d’un fort instinct territorial. Quand il chasse, il se dispute régulièrement les proies avec ses congénères.", ["Ember Pokémon", "Pokémon Braise"], null],
  "talonflame": ["??? dives toward prey at speeds of up to 310 mph and assaults them with powerful kicks, giving the prey no chance to escape.", "??? attaque à une vitesse de 500 km/h. Il achève ses proies d’un puissant coup de patte sans leur laisser la moindre chance de fuir.", ["Scorching Pokémon", "Pokémon Fournaise"], null],
  "scatterbug": ["The powder that covers its body regulates its temperature, so it can live in any region or climate.", "La poudre qui recouvre son corps l’aide à réguler sa température. Il peut s’adapter à tous les climats.", ["Scatterdust Pokémon", "Pokémon Exhalécaille"], null],
  "spewpa": ["The beaks of bird Pokémon can’t begin to scratch its stalwart body. To defend itself, it spews powder.", "Même les becs acérés des Pokémon Oiseaux ne parviennent pas à meurtrir son corps très dur. Il se défend en crachant de la poudre.", ["Scatterdust Pokémon", "Pokémon Exhalécaille"], null],
  "vivillon": ["The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.", "Selon le climat de sa région d’origine, les motifs de ses ailes sont différents. Il sème des écailles aux couleurs vives.", ["Scale Pokémon", "Pokémon Lépidécaille"], null],
  "litleo": ["This hot-blooded Pokémon is filled with curiosity. When it gets angry or starts fighting, its short mane gets hot.", "Il déborde d’énergie et de curiosité. Quand il se fâche ou qu’il s’apprête à se battre, sa courte crinière s’échauffe.", ["Lion Cub Pokémon", "Pokémon Lionceau"], null],
  "pyroar": ["The temperature of its breath is over 10,000 degrees Fahrenheit, but ??? doesn’t use it on its prey. This Pokémon prefers to eat raw meat.", "Son souffle enflammé atteint les 6 000 °C, mais il ne l’utilise jamais contre ses proies. Il préfère en effet la viande crue.", ["Royal Pokémon", "Pokémon Royal"], null],
  "flabebe": ["??? wears a crown made from pollen it’s collected from its flower. The crown has hidden healing properties.", "Il confectionne la couronne qui orne sa tête en récoltant du pollen. Elle recèle de nombreuses propriétés curatives.", ["Single Bloom Pokémon", "Pokémon Uniflore"], null],
  "floette": ["It gives its own power to flowers, pouring its heart into caring for them. ??? never forgives anyone who messes up a flower bed.", "Il fait profiter ses fleurs de ses pouvoirs et met tout son cœur à leur entretien. Gare à ceux qui ravagent ses plates-bandes !", ["Single Bloom Pokémon", "Pokémon Uniflore"], null],
  "florges": ["Its life can span several hundred years. It’s said to devote its entire life to protecting gardens.", "Il peut vivre des centaines d’années, et consacre sa longue existence à l’entretien des jardins.", ["Garden Pokémon", "Pokémon Jardin"], null],
  "skiddo": ["If it has sunshine and water, it doesn’t need to eat, because it can generate energy from the leaves on its back.", "Tant qu’il a de l’eau et du soleil en abondance, ce Pokémon n’a pas besoin de nourriture. Les feuilles sur son dos produisent son énergie par photosynthèse.", ["Mount Pokémon", "Pokémon Monture"], null],
  "gogoat": ["They inhabit mountainous regions. The leader of the herd is decided by a battle of clashing horns.", "Ce Pokémon vit dans les régions montagneuses. Le chef du troupeau s’impose à l’issue d’un combat de cornes.", ["Mount Pokémon", "Pokémon Monture"], null],
  "pancham": ["Wanting to make sure it’s taken seriously, ???’s always giving others a glare. But if it’s not focusing, it ends up smiling.", "Il dévisage toujours ses adversaires d’un air renfrogné pour être pris au sérieux, mais dès que la tension retombe, son sourire reprend le dessus.", ["Playful Pokémon", "Pokémon Garnement"], null],
  "pangoro": ["Using its leaf, ??? can predict the moves of its opponents. It strikes with punches that can turn a dump truck into scrap with just one hit.", "Il anticipe les mouvements de son adversaire grâce à sa feuille. Ses coups de poing peuvent réduire un camion-benne en un tas de ferraille.", ["Daunting Pokémon", "Pokémon Patibulaire"], null],
  "furfrou": ["Left alone, its fur will grow longer and longer, but it will only allow someone it trusts to cut it.", "Sa fourrure pousse indéfiniment, mais il refuse de se faire couper la toison par une personne en qui il n’a pas confiance.", ["Poodle Pokémon", "Pokémon Caniche"], null],
  "espurr": ["There’s enough psychic power in ??? to send a wrestler flying, but because this power can’t be controlled, ??? finds it troublesome.", "Il possède des pouvoirs psychiques si puissants qu’il peut faire valser un catcheur. Malheureusement, il a du mal à les contrôler.", ["Restraint Pokémon", "Pokémon Retenue"], null],
  "meowstic": ["The defensive instinct of the males is strong. It’s when they’re protecting themselves or their partners that they unleash their full power.", "Le mâle a un instinct de défense très développé. Il n’hésite pas à lancer une attaque à pleine puissance pour protéger ses partenaires et lui.", ["Constraint Pokémon", "Pokémon SelfContrôle"], null],
  "honedge": ["The blue eye on the sword’s handguard is the true body of ???. With its old cloth, it drains people’s lives away.", "L’œil bleu sur la garde de la lame est le véritable corps de ???. Il aspire l’énergie vitale des gens avec son étoffe usée par le temps.", ["Sword Pokémon", "Pokémon Glaive"], null],
  "doublade": ["The two swords employ a strategy of rapidly alternating between offense and defense to bring down their prey.", "Ses deux lames abattent leurs proies en enchaînant les attaques et les parades à un rythme effréné.", ["Sword Pokémon", "Pokémon Glaive"], null],
  "aegislash": ["Its potent spectral powers allow it to manipulate others. It once used its powers to force people and Pokémon to build a kingdom to its liking.", "Grâce à ses puissants pouvoirs spirituels, il a contrôlé des humains et des Pokémon pour créer un pays conforme à ses idéaux.", ["Royal Sword Pokémon", "Pokémon Noble Lame"], null],
  "spritzee": ["The scent its body gives off enraptures those who smell it. Noble ladies had no shortage of love for ???.", "Une douce odeur qui charme les gens émane de son corps. Les dames nobles raffolaient de lui.", ["Perfume Pokémon", "Pokémon Fragrance"], null],
  "aromatisse": ["The scents ??? can produce range from sweet smells that bolster allies to foul smells that sap an opponent’s will to fight.", "Il peut émettre une puanteur si infâme qu’elle prive ses ennemis de leur combativité, ou un parfum si réconfortant qu’il encourage ses alliés.", ["Fragrance Pokémon", "Pokémon Parfum"], null],
  "swirlix": ["The sweet smell of cotton candy perfumes ???’s fluffy fur. This Pokémon spits out sticky string to tangle up its enemies.", "Sa douce fourrure possède une odeur sucrée comme la barbe à papa. Il produit des filaments gluants pour empêtrer ses adversaires.", ["Cotton Candy Pokémon", "Pokémon Confiserie"], null],
  "slurpuff": ["???’s fur contains a lot of air, making it soft to the touch and lighter than it looks.", "Sa fourrure est si aérée qu’elle le rend très doux et très agréable au toucher, et bien plus léger qu’il en a l’air.", ["Meringue Pokémon", "Pokémon Mousseline"], null],
  "inkay": ["By exposing foes to the blinking of its luminescent spots, ??? demoralizes them, and then it seizes the chance to flee.", "Il sape la combativité de son adversaire en faisant clignoter son corps lumineux, puis profite de cet instant de répit pour s’enfuir.", ["Revolving Pokémon", "Pokémon Rotation"], null],
  "malamar": ["It’s said that ???’s hypnotic powers played a role in certain history-changing events.", "On raconte que ses pouvoirs hypnotiques seraient à l’origine d’évènements qui ont bouleversé le cours de l’Histoire.", ["Overturning Pokémon", "Pokémon Révolution"], null],
  "binacle": ["If the two don’t work well together, both their offense and defense fall apart. Without good teamwork, they won’t survive.", "Il faut que les deux bras travaillent bien ensemble s’ils souhaitent survivre, sinon leur défense et leur attaque en souffrent grandement.", ["Two-Handed Pokémon", "Pokémon Bimane"], null],
  "barbaracle": ["Having an eye on each palm allows it to keep watch in all directions. In a pinch, its limbs start to act on their own to ensure the enemy’s defeat.", "Il scrute les environs avec les yeux de ses paumes. En cas d’urgence, ses membres peuvent prendre des initiatives pour triompher de l’ennemi.", ["Collective Pokémon", "Pokémon Assemblage"], null],
  "skrelp": ["??? looks like a piece of rotten seaweed, so it can blend in with seaweed drifting on the ocean and avoid being detected by enemies.", "Ressembler à une algue en décomposition lui permet d’échapper à ses ennemis en se cachant au milieu des résidus de plantes aquatiques.", ["Mock Kelp Pokémon", "Pokémon Simulalgue"], null],
  "dragalge": ["??? generates dragon energy by sticking the plume on its head out above the ocean’s surface and bathing it in sunlight.", "Il sort la crête sur sa tête à la surface de l’eau et l’expose à la lumière du soleil pour produire de l’énergie draconique.", ["Mock Kelp Pokémon", "Pokémon Simulalgue"], null],
  "clauncher": ["By detonating gas that accumulates in its right claw, this Pokémon launches water like a bullet. This is how ??? defeats its enemies.", "Il concentre du gaz dans sa pince droite et le fait exploser pour tirer une rafale d’eau sur ses ennemis, comme une balle de pistolet.", ["Water Gun Pokémon", "Pokémon Lance à Eau"], null],
  "clawitzer": ["???’s right arm is a cannon that launches projectiles made of seawater. Shots from a ???’s cannon arm can sink a tanker.", "Sa pince droite est un canon pouvant projeter des obus d’eau assez puissants pour couler un navire-citerne.", ["Howitzer Pokémon", "Pokémon Blaster"], null],
  "helioptile": ["The sun powers this Pokémon’s electricity generation. Interruption of that process stresses ??? to the point of weakness.", "Il peut générer de l’électricité grâce au soleil. Si on le dérange en pleine production d’énergie, cela le stresse et l’affaiblit.", ["Generator Pokémon", "Pokémon Générateur"], null],
  "heliolisk": ["One ??? basking in the sun with its frill outspread is all it would take to produce enough electricity to power a city.", "Lorsqu’il déploie sa collerette pour emmagasiner la lumière du soleil, il génère à lui seul assez d’électricité pour alimenter une grande ville.", ["Generator Pokémon", "Pokémon Générateur"], null],
  "tyrunt": ["This Pokémon is selfish and likes to be pampered. It can also inflict grievous wounds on its Trainer just by playing around.", "Capricieux, il veut toujours être le centre de l’attention. Il peut gravement blesser son Dresseur en essayant de jouer avec lui.", ["Royal Heir Pokémon", "Pokémon Prince"], null],
  "tyrantrum": ["A single bite of ???’s massive jaws will demolish a car. This Pokémon was the king of the ancient world.", "Ce Pokémon peut réduire une voiture en miettes d’un seul coup de mâchoire. Il était considéré comme le roi du monde préhistorique.", ["Despot Pokémon", "Pokémon Tyran"], null],
  "amaura": ["??? is an ancient Pokémon that has gone extinct. Specimens of this species can sometimes be found frozen in ice.", "Un Pokémon ancien qui s’est éteint. On trouve parfois des spécimens conservés dans la glace.", ["Tundra Pokémon", "Pokémon Toundra"], null],
  "aurorus": ["When gripped by rage, ??? will emanate freezing air, covering everything around it in ice.", "Lorsqu’il se laisse emporter par sa rage, il relâche des bourrasques glacées qui gèlent tout ce qui l’entoure.", ["Tundra Pokémon", "Pokémon Toundra"], null],
  "sylveon": ["It emits a soothing aura from its ribbon-shaped organs. It wraps these appendages around quarrelers to instantly restore calm to the situation.", "Un conte de Galar relate la victoire d’un beau ??? sur un terrible Pokémon Dragon.", ["Intertwining Pokémon", "Pokémon Attachant"], null],
  "hawlucha": ["It always strikes a pose before going for its finishing move. Sometimes opponents take advantage of that time to counterattack.", "Il prend toujours la pose avant de donner le coup de grâce à son adversaire. Certains en profitent pour contre-attaquer.", ["Wrestling Pokémon", "Pokémon Catcheur"], null],
  "dedenne": ["Since ??? can’t generate much electricity on its own, it steals electricity from outlets or other electric Pokémon.", "Puisqu’il a du mal à générer sa propre électricité, il en vole aux autres Pokémon Électrik ou via les prises de courant.", ["Antenna Pokémon", "Pokémon Antenne"], null],
  "carbink": ["It’s said that somewhere in the world, there’s a mineral vein housing a large pack of slumbering ???. It’s also said that this pack has a queen.", "On raconte qu’il existerait quelque part dans le monde un filon regorgeant de ???, qui abriterait également leur reine.", ["Jewel Pokémon", "Pokémon Joyau"], null],
  "goomy": ["??? hides away in the shade of trees, where it's nice and humid. If the slime coating its body dries out, the Pokémon instantly becomes lethargic.", "Ses cornes sont des organes sensoriels qui lui permettent de se cacher quand il détecte des ennemis. C’est grâce à cela qu’il vit toujours.", ["Soft Tissue Pokémon", "Pokémon Mollusque"], null],
  "sliggoo": ["A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui's water.", "Son petit cerveau est caché dans la bosse qui est sur son dos. Il ne pense pas à grand-chose, si ce n’est à se nourrir et à fuir devant ses ennemis.", ["Soft Tissue Pokémon", "Pokémon Mollusque"], null],
  "goodra": ["Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.", "Il attaque à l’aide de ses longues cornes. Ses coups sont cent fois plus puissants que ceux d’un champion poids lourds de boxe.", ["Dragon Pokémon", "Pokémon Dragon"], null],
  "klefki": ["??? sucks in metal ions with the horn topping its head. It seems this Pokémon loves keys so much that its head needed to look like one, too.", "Il absorbe les ions métalliques avec l’appendice sur sa tête. Il paraît qu’il ressemble à une clé car il tient à imiter cet objet qu’il aime tant.", ["Key Ring Pokémon", "Pokémon Trousseau"], null],
  "phantump": ["With a voice like a human child’s, it cries out to lure adults deep into the forest, getting them lost among the trees.", "Il imite des cris d’enfants pour pousser les adultes à venir se perdre au plus profond de la forêt.", ["Stump Pokémon", "Pokémon Souche"], null],
  "trevenant": ["Small roots that extend from the tips of this Pokémon’s feet can tie into the trees of the forest and give ??? control over them.", "Il étire les fines racines de ses pieds pour établir une connexion avec les autres arbres de la forêt et ainsi les contrôler.", ["Elder Tree Pokémon", "Pokémon Vieillarbre"], null],
  "pumpkaboo": ["The light that streams out from the holes in the pumpkin can hypnotize and control the people and Pokémon that see it.", "Il peut manipuler les humains et les Pokémon en les hypnotisant grâce à la lumière qui filtre par les trous de son ventre en forme de citrouille.", ["Pumpkin Pokémon", "Pokémon Citrouille"], null],
  "gourgeist": ["In the darkness of a new-moon night, ??? will come knocking. Whoever answers the door will be swept off to the afterlife.", "Les soirs de nouvelle lune, il frappe aux portes des maisons. Si quelqu’un a le malheur de lui ouvrir, il l’emporte aussitôt dans l’au-delà.", ["Pumpkin Pokémon", "Pokémon Citrouille"], null],
  "bergmite": ["Lives on mountains blanketed in perennial snow. It freezes water vapor in the air to make the ice helmet that it dons for defense.", "Il vit dans les régions les plus froides, agrippé aux Séracrawl. Il gèle ses pattes sur leur dos pour se maintenir en place.", ["Ice Chunk Pokémon", "Pokémon Glaçon"], null],
  "avalugg": ["The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.", "Les crevasses sur son dos s’approfondissent au cours de la journée, mais se comblent de nouveau pendant la nuit.", ["Iceberg Pokémon", "Pokémon Iceberg"], null],
  "noibat": ["No wavelength of sound is beyond ???’s ability to produce. The ultrasonic waves it generates can overcome much larger Pokémon.", "Il peut contrôler des ondes à n’importe quelle fréquence du spectre. Même les plus grands Pokémon ne peuvent supporter ses ultrasons.", ["Sound Wave Pokémon", "Pokémon Ondes"], null],
  "noivern": ["Flying through the darkness, it weakens enemies with ultrasonic waves that could crush stone. Its fangs finish the fight.", "Il plane dans les ténèbres, blessant ses ennemis à coups d’ultrasons pouvant briser des rochers avant de les achever de ses crocs acérés.", ["Sound Wave Pokémon", "Pokémon Ondes"], null],
  "xerneas": ["When the horns on its head shine in seven colors, it is said to be sharing everlasting life.", "D’après la légende, quand ses bois brillent de sept couleurs, cela signifie qu’il prodigue la vie éternelle.", ["Life Pokémon", "Pokémon Existence"], null],
  "yveltal": ["When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.", "Quand il sent que la fin de sa vie est proche, il aspire la force vitale des êtres vivants et retourne à l’état de cocon.", ["Destruction Pokémon", "Pokémon Annihilation"], null],
  "zygarde": ["Some say it can change to an even more powerful form when battling those who threaten the ecosystem.", "Ce Pokémon serait capable de prendre une forme encore plus puissante quand il se bat contre un ennemi qui menace l’écosystème.", ["Order Pokémon", "Pokémon Équilibre"], null],
  "diancie": ["It can instantly create many diamonds by compressing the carbon in the air between its hands.", "Il peut créer une multitude de diamants en un instant en serrant ses mains, simplement en compressant les molécules de carbone contenues dans l’air.", ["Jewel Pokémon", "Pokémon Joyau"], null],
  "hoopa": ["It is said to be able to seize anything it desires with its six rings and six huge arms. With its power sealed, it is transformed into a much smaller form.", "On raconte que grâce à ses six anneaux et ses six énormes bras, il est capable de dérober tout ce qui lui plaît. Mais son pouvoir a été scellé, et il a été réduit à l’état d’un être minuscule.", ["Mischief Pokémon", "Pokémon Chenapan"], null],
  "volcanion": ["It expels its internal steam from the arms on its back. It has enough power to blow away a mountain.", "Il évacue la vapeur qui s’accumule à l’intérieur de son corps par les bras situés sur son dos. Ce jet est assez puissant pour raser des montagnes.", ["Steam Pokémon", "Pokémon Vapeur"], null],
  "rowlet": ["Flies noiselessly on delicate wings. It has mastered the art of deftly launching dagger-sharp feathers from those same wings.", "Pendant la journée, il emmagasine de l’énergie par photosynthèse. La nuit, il plane silencieusement à la recherche de proies.", ["Grass Quill Pokémon", "Pokémon Plumefeuille"], null],
  "dartrix": ["Regularly basks in sunlight to gather power—presumably due to the frigid climate. Nonetheless, the edges of the blade quills set into its wings are keen as ever.", "Il prend grand soin de son plumage, s’assurant ainsi d’avoir une apparence impeccable et des plumes aiguisées à souhait.", ["Blade Quill Pokémon", "Pokémon Plum’acérée"], null],
  "decidueye": ["The air stored inside the rachises of ???'s feathers insulates the Pokémon against Hisui's extreme cold. This is firm proof that evolution can be influenced by environment.", "Il décoche ses plumes acérées en un dixième de seconde. Sa victime n’a pas le temps de le voir agir qu’elle est déjà grièvement touchée.", ["Arrow Quill Pokémon", "Pokémon Plumeflèche"], null],
  "litten": ["Trying to pet ??? before it trusts you will result in a nasty scratch from its sharp claws. Be careful.", "Quiconque essaie de le caresser avant d’avoir gagné sa confiance s’expose à de sérieuses griffures.", ["Fire Cat Pokémon", "Pokémon Chat Feu"], null],
  "torracat": ["When facing a powerful enemy, ???’s fighting spirit gets pumped up, and its fire bell blazes hotter.", "Quand il fait face à un adversaire redoutable, il redouble de combativité et la puissance calorifère de sa clochette augmente.", ["Fire Cat Pokémon", "Pokémon Chat Feu"], null],
  "incineroar": ["???’s rough and aggressive behavior is its most notable trait, but the way it helps out small Pokémon shows that it has a kind side as well.", "Bien qu’il soit parfois brutal, il sait aussi se montrer attentionné en venant en aide aux petits Pokémon.", ["Heel Pokémon", "Pokémon Vil Catcheur"], null],
  "popplio": ["If ??? want to create big, powerful balloons, they must be persistent. It takes daily practice for these Pokémon to develop their skills.", "Il s’entraîne sans relâche tous les jours pour réussir à créer de gros ballons de bonne qualité.", ["Sea Lion Pokémon", "Pokémon Otarie"], null],
  "brionne": ["On nights when the sea is calm, ??? dance with one another to the singing of the Primarina that’s leading them.", "Les soirs où la mer est calme, il danse avec ses congénères au son des chants d’Oratoria, le chef du groupe.", ["Pop Star Pokémon", "Pokémon Starlette"], null],
  "primarina": ["For ???, every battle’s a stage. Its singing and the dancing of its balloons will mesmerize the audience.", "Les combats sont une véritable performance artistique, pour lui. Les spectateurs sont charmés par son chant et la danse de ses ballons.", ["Soloist Pokémon", "Pokémon Soliste"], null],
  "pikipek": ["It may look spindly, but its neck muscles are heavy-duty. It can peck at a tree 16 times per second!", "Son cou fin renferme des muscles étonnamment puissants. Il tape contre les arbres à raison de seize coups de bec par seconde.", ["Woodpecker Pokémon", "Pokémon Pivert"], null],
  "trumbeak": ["From its mouth, it fires the seeds of berries it has eaten. The scattered seeds give rise to new plants.", "Il crache violemment les noyaux des Baies qu’il a mangées. Ils s’éparpillent au sol et donnent naissance à de nouvelles plantes.", ["Bugle Beak Pokémon", "Pokémon Bec Clairon"], null],
  "toucannon": ["Known for forming harmonious couples, this Pokémon is brought to wedding ceremonies as a good luck charm.", "Les couples de ??? sont réputés pour leur harmonie. On en amène souvent aux mariages pour porter bonheur aux jeunes époux.", ["Cannon Pokémon", "Pokémon Canon"], null],
  "yungoos": ["Although it will eat anything, it prefers fresh living things, so it marches down streets in search of prey.", "Il mange de tout, mais aime particulièrement les proies fraîches, voire encore vives. Il erre sur les routes à leur recherche.", ["Loitering Pokémon", "Pokémon Patrouille"], null],
  "gumshoos": ["Patient by nature, this Pokémon loses control of itself and pounces when it spots its favorite meal—Rattata!", "D’un naturel très patient, il ne peut toutefois s’empêcher de bondir sur son plat favori, Rattata, s’il en voit un.", ["Stakeout Pokémon", "Pokémon Filature"], null],
  "grubbin": ["It uses its big jaws to dig nests into the forest floor, and it loves to feed on sweet tree sap.", "Il creuse son terrier dans le sol de la forêt avec ses grandes mandibules. Il raffole de la sève sucrée.", ["Larva Pokémon", "Pokémon Larve"], null],
  "charjabug": ["Its digestive processes convert the leaves it eats into electricity. An electric sac in its belly stores the electricity for later use.", "Il possède une poche dans laquelle il emmagasine l’électricité qu’il produit en digérant des feuilles mortes.", ["Battery Pokémon", "Pokémon Batterie"], null],
  "vikavolt": ["If it carries a Charjabug to use as a spare battery, a flying ??? can rapidly fire high-powered beams of electricity.", "S’il emporte un Chrysapile en tant que batterie de secours, il peut tirer une salve de rayons électriques extrêmement puissants en plein vol.", ["Stag Beetle Pokémon", "Pokémon Scarabée"], null],
  "crabrawler": ["??? has been known to mistake Exeggutor for a coconut tree and climb it. The enraged Exeggutor shakes it off and stomps it.", "Il grimpe parfois sur un Noadkoko qu’il a pris pour un cocotier. Il se fait alors éjecter puis piétiner par le Noadkoko courroucé.", ["Boxing Pokémon", "Pokémon Boxeur"], null],
  "crabominable": ["Before it stops to think, it just starts pummeling. There are records of its turning back avalanches with a flurry of punches.", "Agir ou réfléchir ? ??? choisit de frapper ! On raconte qu’il serait déjà parvenu à repousser une avalanche à coups de pince.", ["Woolly Crab Pokémon", "Pokémon Crabe Velu"], null],
  "oricorio": ["This ??? has drunk red nectar. If its Trainer gives the wrong order, this passionate Pokémon becomes fiercely angry.", "Un ??? ayant bu du Nectar Rouge. D’un naturel passionné, il brûle de rage quand son Dresseur se trompe d’ordre.", ["Dancing Pokémon", "Pokémon Danse"], null],
  "cutiefly": ["An opponent’s aura can tell ??? what that opponent’s next move will be. Then ??? can glide around the attack and strike back.", "Il perçoit l’aura de son ennemi et anticipe ses mouvements. Il parvient ainsi à éviter les attaques et à riposter dans la foulée.", ["Bee Fly Pokémon", "Pokémon Bombyle"], null],
  "ribombee": ["??? absolutely hate getting wet or rained on. In the cloudy Galar region, they are very seldom seen.", "Il a horreur d’être trempé par la pluie. On ne le voit que très rarement à Galar, région connue pour son temps couvert.", ["Bee Fly Pokémon", "Pokémon Bombyle"], null],
  "rockruff": ["This Pokémon intimidates opponents by striking the ground with the rocks on its neck. The moment an opponent flinches, ??? attacks.", "Il intimide ses ennemis en cognant les rochers autour de son cou contre le sol. Au premier signe de faiblesse, il passe à l’assaut.", ["Puppy Pokémon", "Pokémon Chiot"], null],
  "lycanroc": ["With swift movements, this Pokémon gradually backs its prey into a corner. ???’s fangs are always aimed toward opponents’ weak spots.", "Il poursuit ses proies avec rapidité et patience. Une fois la cible acculée, il attaque toujours son point faible avec ses crocs.", ["Wolf Pokémon", "Pokémon Loup"], null],
  "wishiwashi": ["When it senses danger, its eyes tear up. The sparkle of its tears signals other ??? to gather.", "Ses yeux se mouillent quand il sent le danger approcher. Le scintillement de ses larmes sert de signal pour que ses congénères se rassemblent.", ["Small Fry Pokémon", "Pokémon Minipoisson"], null],
  "mareanie": ["Unlike their Alolan counterparts, the ??? of the Galar region have not yet figured out that the branches of Corsola are delicious.", "Contrairement aux ??? d’Alola, ceux de Galar ne font pas grand cas des cornes de Corayon.", ["Brutal Star Pokémon", "Pokémon Cruel"], null],
  "toxapex": ["Within the poison sac in its body is a poison so toxic that Pokémon as large as Wailord will still be suffering three days after it first takes effect.", "Sa poche à venin interne regorge d’un poison si violent que même un Wailord en souffrirait pendant trois jours entiers.", ["Brutal Star Pokémon", "Pokémon Cruel"], null],
  "mudbray": ["It eats dirt to create mud and smears this mud all over its feet, giving them the grip needed to walk on rough terrain without slipping.", "Il mâche de la terre pour créer une boue dont il s’enduit les jambes. Celle-ci lui permet alors d’arpenter même les routes accidentées.", ["Donkey Pokémon", "Pokémon Âne"], null],
  "mudsdale": ["??? has so much stamina that it could carry over 10 tons across the Galar region without rest or sleep.", "Il a assez d’endurance pour arpenter tout Galar sans relâche en tirant des charges dépassant les dix tonnes.", ["Draft Horse Pokémon", "Pokémon Cheval Trait"], null],
  "dewpider": ["??? normally lives underwater. When it comes onto land in search of food, it takes water with it in the form of a bubble on its head.", "Il vit principalement dans l’eau, mais s’il a besoin de s’aventurer sur la terre ferme pour chasser ses proies, il protège sa tête avec une bulle d’eau.", ["Water Bubble Pokémon", "Pokémon Aquabulle"], null],
  "araquanid": ["It acts as a caretaker for Dewpider, putting them inside its bubble and letting them eat any leftover food.", "Il prend soin de petits Araqua en les abritant dans sa bulle et en les laissant grignoter les restes de ses repas.", ["Water Bubble Pokémon", "Pokémon Aquabulle"], null],
  "fomantis": ["During the day, ??? basks in sunlight and sleeps peacefully. It wakes and moves around at night.", "La journée, il dort tranquillement au soleil pour en absorber les rayons. La nuit, il se réveille et vaque à ses occupations.", ["Sickle Grass Pokémon", "Pokémon Fauch’Herbe"], null],
  "lurantis": ["The petals on this Pokémon’s arms are thin and super sharp, and they can fire laser beams if ??? gathers light first.", "Les pétales sur ses deux bras sont fins, mais très tranchants. Ils peuvent également absorber la lumière pour la renvoyer sous forme de laser.", ["Bloom Sickle Pokémon", "Pokémon Fauch’Fleur"], null],
  "morelull": ["??? live in forests that stay dark even during the day. They scatter flickering spores that put enemies to sleep.", "Il vit dans les forêts sombres même en plein jour. Il dissémine des spores clignotantes pour endormir ses ennemis.", ["Illuminating Pokémon", "Pokémon Luminescent"], null],
  "shiinotic": ["If you see a light deep in a forest at night, don’t go near. ??? will make you fall fast asleep.", "Il ne faut pas s’approcher des lumières qui luisent la nuit au fond des bois, sous peine de se faire endormir par un ???.", ["Illuminating Pokémon", "Pokémon Luminescent"], null],
  "salandit": ["This sneaky Pokémon will slink behind its prey and immobilize it with poisonous gas before the prey even realizes ??? is there.", "Il s’approche de ses proies par-derrière et les asperge d’un gaz empoisonné avant qu’elles n’aient le temps de réagir, les clouant sur place.", ["Toxic Lizard Pokémon", "Pokémon Toxilézard"], null],
  "salazzle": ["The winner of competitions between ??? is decided by which one has the most male Salandit with it.", "Les conflits entre ??? seraient réglés par un simple calcul : le spécimen dont la suite comporte le plus de Tritox l’emporte.", ["Toxic Lizard Pokémon", "Pokémon Toxilézard"], null],
  "stufful": ["The way it protects itself by flailing its arms may be an adorable sight, but stay well away. This is flailing that can snap thick tree trunks.", "Sa façon de remuer les pattes pour se défendre semble adorable, mais ce Pokémon est si puissant qu’il pourrait fendre un tronc de la sorte.", ["Flailing Pokémon", "Pokémon Gigoteur"], null],
  "bewear": ["The moves it uses to take down its prey would make a martial artist jealous. It tucks subdued prey under its arms to carry them to its nest.", "Il abat ses proies à l’aide de techniques à faire pâlir d’envie des combattants professionnels, puis les emporte sous les bras dans sa tanière.", ["Strong Arm Pokémon", "Pokémon Biscoteaux"], null],
  "bounsweet": ["When under attack, it secretes a sweet and delicious sweat. The scent only calls more enemies to it.", "La sueur sucrée qu’il produit lorsqu’on l’attaque est délicieuse. L’odeur de celle-ci lui attire encore plus d’ennemis.", ["Fruit Pokémon", "Pokémon Fruit"], null],
  "steenee": ["Any Corvisquire that pecks at this Pokémon will be greeted with a smack from its sepals followed by a sharp kick.", "Lorsqu’un Bleuseille le picore, il commence par se défendre avec son calice, et lui assène ensuite de violents coups de pied.", ["Fruit Pokémon", "Pokémon Fruit"], null],
  "tsareena": ["A kick from the hardened tips of this Pokémon’s legs leaves a wound in the opponent’s body and soul that will never heal.", "Ce Pokémon frappe violemment ses ennemis de la pointe dure de ses jambes, ce qui leur inflige des dégâts irréversibles au corps et à l’âme.", ["Fruit Pokémon", "Pokémon Fruit"], null],
  "comfey": ["These Pokémon smell very nice. All ??? wear different flowers, so each of these Pokémon has its own individual scent.", "Ce Pokémon dégage un parfum agréable qui varie d’un spécimen à l’autre, car chaque ??? s’habille de fleurs différentes.", ["Posy Picker Pokémon", "Pokémon Tressefleur"], null],
  "oranguru": ["It knows the forest inside and out. If it comes across a wounded Pokémon, ??? will gather medicinal herbs to treat it.", "Il connaît la forêt sur le bout des doigts. Lorsqu’il trouve un Pokémon blessé, il cherche des plantes médicinales pour le soigner.", ["Sage Pokémon", "Pokémon Grand Sage"], null],
  "passimian": ["??? live in groups of about 20, with each member performing an assigned role. Through cooperation, the group survives.", "Ils vivent en groupes de vingt individus où chacun a un rôle précis, ce qui leur a permis de survivre dans un environnement impitoyable.", ["Teamwork Pokémon", "Pokémon Coopération"], null],
  "wimpod": ["??? gather in swarms, constantly on the lookout for danger. They scatter the moment they detect an enemy’s presence.", "Ils se déplacent en groupe, toujours en alerte. Dès qu’ils détectent une présence ennemie, ils s’enfuient dans toutes les directions.", ["Turn Tail Pokémon", "Pokémon Cavaleur"], null],
  "golisopod": ["They live in sunken ships or in holes in the seabed. When ??? and Grapploct battle, the loser becomes the winner’s meal.", "Il vit dans des trous ou des épaves au fond de l’océan. Il se bat souvent contre Krakos, et le perdant sert de repas au gagnant.", ["Hard Scale Pokémon", "Pokémon Blindé"], null],
  "sandygast": ["??? mainly inhabits beaches. It takes control of anyone who puts their hand into its mouth, forcing them to make its body bigger.", "Il vit principalement sur les plages de sable et peut agrandir son corps en prenant le contrôle des gens qui mettent la main dans sa gueule.", ["Sand Heap Pokémon", "Pokémon Pâtéd’Sable"], null],
  "palossand": ["This Pokémon lives on beaches, but it hates water. ??? can’t maintain its castle-like shape if it gets drenched by a heavy rain.", "Bien qu’il déteste l’eau, il vit sur les plages. Quand la pluie s’abat sur lui, il est incapable de conserver sa forme de château de sable.", ["Sand Castle Pokémon", "Pokémon Châtod’Sable"], null],
  "pyukumuku": ["It’s covered in a slime that keeps its skin moist, allowing it to stay on land for days without drying up.", "Le fluide visqueux qui le recouvre garde sa peau bien hydratée, ce qui lui permet de vivre plusieurs jours sur la terre ferme sans se dessécher.", ["Sea Cucumber Pokémon", "Pokémon Holothurie"], null],
  "type-null": ["It was modeled after a mighty Pokémon of myth. The mask placed upon it limits its power in order to keep it under control.", "Il a été créé artificiellement d’après un Pokémon mythique. Il est muni d’un masque afin de contenir sa puissance.", ["Synthetic Pokémon", "Pokémon Multigénome"], null],
  "silvally": ["The final factor needed to release this Pokémon’s true power was a strong bond with a Trainer it trusts.", "La relation de confiance qui le lie à son Dresseur est le facteur décisif qui lui permet de libérer tout son potentiel.", ["Synthetic Pokémon", "Pokémon Multigénome"], null],
  "minior": ["Although its outer shell is uncommonly durable, the shock of falling to the ground smashes the shell to smithereens.", "Sa carapace, pourtant très solide, éclate en mille morceaux quand il s’écrase sur la terre en tombant du ciel.", ["Meteor Pokémon", "Pokémon Météore"], null],
  "komala": ["It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet.", "Ce Pokémon passe sa vie entière à dormir à cause des composants anesthésiants qui se trouvent dans les feuilles qu’il mange.", ["Drowsing Pokémon", "Pokémon Rêveur"], null],
  "turtonator": ["Eating sulfur in its volcanic habitat is what causes explosive compounds to develop in its shell. Its droppings are also dangerously explosive.", "Il vit dans les volcans. Le soufre dont il se nourrit rend sa carapace explosive. Même ses selles sont dangereuses, car elles sont instables.", ["Blast Turtle Pokémon", "Pokémon Tortue Boum"], null],
  "togedemaru": ["When it’s in trouble, it curls up into a ball, makes its fur spikes stand on end, and then discharges electricity indiscriminately.", "En cas de danger, il se roule en boule, dresse ses épines dorsales et lance des décharges électriques au hasard.", ["Roly-Poly Pokémon", "Pokémon Roulenboule"], null],
  "mimikyu": ["There was a scientist who peeked under ???’s old rag in the name of research. The scientist died of a mysterious disease.", "Les malheureux chercheurs qui ont regardé sous son déguisement en lambeaux ont succombé à une mystérieuse maladie.", ["Disguise Pokémon", "Pokémon Fantômasque"], null],
  "bruxish": ["Its skin is thick enough to fend off Mareanie’s spikes. With its robust teeth, ??? crunches up the spikes and eats them.", "Sa peau est si épaisse que même les épines de Vorastérie ne peuvent la percer. Il les croque bruyamment grâce à ses dents solides.", ["Gnash Teeth Pokémon", "Pokémon Grincedent"], null],
  "drampa": ["??? is a kind and friendly Pokémon—up until it’s angered. When that happens, it stirs up a gale and flattens everything around.", "Il est d’un naturel sociable et aimable, mais quand il se met en colère, il déchaîne des bourrasques qui emportent tout sur leur passage.", ["Placid Pokémon", "Pokémon Nonchalant"], null],
  "dhelmise": ["After lowering its anchor, it waits for its prey. It catches large Wailord and drains their life-force.", "Il tend des guets-apens à ses proies en larguant son ancre dans la mer. Il peut absorber l’énergie vitale de grosses proies comme Wailord.", ["Sea Creeper Pokémon", "Pokémon Varech"], null],
  "jangmo-o": ["??? strikes its scales to communicate with others of its kind. Its scales are actually fur that’s become as hard as metal.", "Il communique avec ses congénères en faisant cliqueter ses écailles dures comme du métal.", ["Scaly Pokémon", "Pokémon Écailles"], null],
  "hakamo-o": ["Before attacking its enemies, it clashes its scales together and roars. Its sharp claws shred the opposition.", "Après avoir fait tinter ses écailles et poussé un terrible cri de guerre, il charge ses ennemis et les lacère de ses griffes acérées.", ["Scaly Pokémon", "Pokémon Écailles"], null],
  "kommo-o": ["Certain ruins have paintings of ancient warriors wearing armor made of ??? scales.", "Dans les ruines, on trouve parfois des fresques représentant des guerriers antiques qui portent des armures faites avec ses écailles.", ["Scaly Pokémon", "Pokémon Écailles"], null],
  "tapu-koko": ["The lightning-wielding guardian deity of Melemele, ??? is brimming with curiosity and appears before people from time to time.", "Il est le gardien de Mele-Mele et le maître de la foudre. D’un naturel curieux, il apparaît devant les humains de temps à autre.", ["Land Spirit Pokémon", "Pokémon Tutélaire"], null],
  "tapu-lele": ["Although called a guardian deity, ??? is devoid of guilt about its cruel disposition and can be described as nature incarnate.", "Bien qu’on le considère comme une divinité protectrice, cette incarnation parfaite de la nature est aussi innocente que cruelle.", ["Land Spirit Pokémon", "Pokémon Tutélaire"], null],
  "tapu-bulu": ["It makes ringing sounds with its tail to let others know where it is, avoiding unneeded conflicts. This guardian deity of Ula’ula controls plants.", "Il est le gardien d’Ula-Ula et le maître des plantes. Il évite les combats inutiles en faisant tinter sa queue pour signaler son arrivée.", ["Land Spirit Pokémon", "Pokémon Tutélaire"], null],
  "tapu-fini": ["Although it’s called a guardian deity, terrible calamities sometimes befall those who recklessly approach ???.", "Il ne faut pas se laisser berner par son statut de divinité protectrice : il lui arrive de mettre en pièces ceux qui osent s’approcher de trop près.", ["Land Spirit Pokémon", "Pokémon Tutélaire"], null],
  "cosmog": ["??? is very curious but not very cautious, often placing itself in danger. If things start to look dicey, it teleports away.", "De nature curieuse et peu méfiante, il se retrouve souvent dans des situations dangereuses. Il peut se téléporter en cas de danger.", ["Nebula Pokémon", "Pokémon Nébuleuse"], null],
  "cosmoem": ["It sucks in dust from the air at an astounding rate, frantically building up energy within its core as preparation for evolution.", "Il aspire avec force la poussière de l’atmosphère et travaille sans relâche pour produire dans son noyau l’énergie nécessaire à son évolution.", ["Protostar Pokémon", "Pokémon Proto-Étoile"], null],
  "solgaleo": ["??? was once known as the Beast That Devours the Sun. Energy in the form of light radiates boundlessly from it.", "Jadis, on le surnommait « celui qui dévore le soleil ». Une lumière inextinguible rayonne de son corps.", ["Sunne Pokémon", "Pokémon Halo Solaire"], null],
  "lunala": ["It steals the light from its surroundings and then becomes the full moon, showering its own light across the night sky.", "Il capture toute la lumière qui l’entoure pour prendre la forme de la pleine lune et éclairer les ténèbres nocturnes.", ["Moone Pokémon", "Pokémon Halo Lunaire"], null],
  "nihilego": ["It appeared in this world from an Ultra Wormhole. ??? appears to be a parasite that lives by feeding on people and Pokémon.", "Il est venu dans ce monde à travers une Ultra-Brèche. Tel un parasite, il aurait besoin d’un hôte, Pokémon ou humain, pour survivre.", ["Parasite Pokémon", "Pokémon Parasite"], null],
  "buzzwole": ["??? goes around showing off its abnormally swollen muscles. It is one kind of Ultra Beast.", "Ce type d’Ultra-Chimère adore exhiber ses muscles gonflés à l’extrême.", ["Swollen Pokémon", "Pokémon Enflé"], null],
  "pheromosa": ["Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives.", "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.", ["Lissome Pokémon", "Pokémon Gracile"], null],
  "xurkitree": ["They’ve been dubbed Ultra Beasts. Some of them stand unmoving, like trees, with their arms and legs stuck into the ground.", "Certains spécimens de ce type d’Ultra-Chimère plantent leurs membres dans le sol à la manière d’un arbre et restent immobiles.", ["Glowing Pokémon", "Pokémon Luminaire"], null],
  "celesteela": ["Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives.", "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.", ["Launch Pokémon", "Pokémon Décollage"], null],
  "kartana": ["Although it’s alien to this world and a danger here, it’s apparently a common organism in the world where it normally lives.", "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.", ["Drawn Sword Pokémon", "Pokémon Battô"], null],
  "guzzlord": ["An unknown life-form called a UB. It may be constantly hungry—it is certainly always devouring something.", "Cette créature inconnue appelée « Ultra-Chimère » semble constamment affamée : elle mange en permanence.", ["Junkivore Pokémon", "Pokémon Bizarrovore"], null],
  "necrozma": ["It needs light to survive, and it goes on a rampage seeking it out. Its laser beams will cut anything to pieces.", "Sa quête de lumière, sa source de vie, le rend violent. Il détruit tout sur son passage avec ses rayons laser.", ["Prism Pokémon", "Pokémon Prisme"], null],
  "magearna": ["Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form.", "Il a été créé par un scientifique il y a environ 500 ans de cela. Sa véritable essence est un organe nommé Animacœur.", ["Artificial Pokémon", "Pokémon Artificiel"], null],
  "marshadow": ["This Pokémon can conceal itself in any shadow, so it went undiscovered for a long time.", "Ce Pokémon ayant la capacité de se dissimuler dans les ombres, il est resté très longtemps caché aux yeux du monde.", ["Gloomdweller Pokémon", "Pokémon Ombrefuge"], null],
  "poipole": ["An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head.", "Cette Ultra-Chimère venue d’un autre monde ricane lorsqu’elle asperge ses proies de venin grâce au dard qu’elle a sur la tête.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "naganadel": ["One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive.", "Cette Ultra-Chimère utilise son aiguillon pour sécréter un venin toxique, luisant et gluant.", ["Poison Pin Pokémon", "Pokémon Vénépic"], null],
  "stakataka": ["When stone walls started moving and attacking, the brute’s true identity was this mysterious life-form, which brings to mind an Ultra Beast.", "On suppose que cette mystérieuse forme de vie est une Ultra-Chimère. Si un mur se met en branle et vous attaque sans prévenir, c’est lui.", ["Rampart Pokémon", "Pokémon Muraille"], null],
  "blacephalon": ["A UB that appeared from an Ultra Wormhole, it causes explosions, then takes advantage of opponents’ surprise to rob them of their vitality.", "Cette Ultra-Chimère sortie d’une Ultra-Brèche provoque des explosions pour surprendre l’ennemi et en profite pour voler son énergie.", ["Fireworks Pokémon", "Pokémon Artificier"], null],
  "zeraora": ["Electricity sparks from the pads on its limbs. Wherever ??? runs, lightning flashes and thunder echoes.", "Il envoie des décharges électriques avec les coussinets de ses pattes. Quand il court, on peut voir des éclairs et entendre la foudre.", ["Thunderclap Pokémon", "Pokémon Vif Éclair"], null],
  "meltan": ["They live as a group, but when the time comes, one strong ??? will absorb all the others and evolve.", "Les ??? vivent en groupe. Quand l’heure de l’évolution a sonné, le plus fort d’entre eux absorbe ses camarades pour changer de forme.", ["Hex Nut Pokémon", "Pokémon Écrou"], null],
  "melmetal": ["Centrifugal force is behind the punches of ???’s heavy hex-nut arms. ??? is said to deliver the strongest punches of all Pokémon.", "On dit que, grâce à la force centrifuge, les coups de poing qu’il assène avec ses lourds écrous seraient les plus dévastateurs parmi les Pokémon.", ["Hex Nut Pokémon", "Pokémon Écrou"], null],
  "grookey": ["It attacks with rapid beats of its stick. As it strikes with amazing speed, it gets more and more pumped.", "Il attaque en frappant frénétiquement avec son bâton. Son enthousiasme grandit à mesure que le rythme s’accélère.", ["Chimp Pokémon", "Pokémon Chimpanzé"], null],
  "thwackey": ["When it’s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won’t even notice that it’s already knocked out its opponent.", "Il est tellement concentré à battre à un rythme effréné que même lorsque son adversaire tombe K.O., il ne s’en rend pas compte.", ["Beat Pokémon", "Pokémon Percussions"], null],
  "rillaboom": ["The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group.", "Celui qui possède les meilleures techniques de percussion devient le chef. De nature calme, il privilégie l’harmonie du groupe.", ["Drummer Pokémon", "Pokémon Batteur"], null],
  "scorbunny": ["It has special pads on the backs of its feet, and one on its nose. Once it’s raring to fight, these pads radiate tremendous heat.", "Quand il est prêt à se battre, la partie qui surmonte son museau ainsi que les coussinets de ses pattes postérieures émettent de la chaleur.", ["Rabbit Pokémon", "Pokémon Lapin"], null],
  "raboot": ["It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork.", "Pour parfaire son jeu de jambes, il cueille des Baies puis drible avec, le tout sans se servir de ses mains.", ["Rabbit Pokémon", "Pokémon Lapin"], null],
  "cinderace": ["It’s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.", "Exceptionnel en attaque comme en défense, il s’exalte quand on l’encourage, mais il lui arrive de se mettre en danger en jouant solo.", ["Striker Pokémon", "Pokémon Buteur"], null],
  "sobble": ["When it gets wet, its skin changes color, and this Pokémon becomes invisible as if it were camouflaged.", "Sa peau change de couleur et le rend invisible quand elle est mouillée, comme un camouflage.", ["Water Lizard Pokémon", "Pokémon Lézard’Eau"], null],
  "drizzile": ["Highly intelligent but also very lazy, it keeps enemies out of its territory by laying traps everywhere.", "Paresseux, mais malin, il parsème son territoire de pièges pour empêcher ses ennemis d’y pénétrer.", ["Water Lizard Pokémon", "Pokémon Lézard’Eau"], null],
  "inteleon": ["Its nictitating membranes let it pick out foes’ weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.", "Il repère le point faible de l’ennemi grâce à sa membrane nictitante, puis il transperce sa cible en tirant des jets d’eau à Mach 3 du bout des doigts.", ["Secret Agent Pokémon", "Pokémon Agent Secret"], null],
  "skwovet": ["It eats berries nonstop—a habit that has made it more resilient than it looks. It’ll show up on farms, searching for yet more berries.", "Comme il mange tout le temps des Baies, il est plus costaud qu’il n’en a l’air. Il parcourt les champs à la recherche de sa précieuse denrée.", ["Cheeky Pokémon", "Pokémon Joufflu"], null],
  "greedent": ["Common throughout the Galar region, this Pokémon has strong teeth and can chew through the toughest of berry shells.", "On rencontre souvent ce Pokémon à Galar. Aucune coquille de Baie ne résiste à ses incisives, dont il est très fier.", ["Greedy Pokémon", "Pokémon Goulu"], null],
  "rookidee": ["Jumping nimbly about, this small-bodied Pokémon takes advantage of even the slightest opportunity to disorient larger opponents.", "Son petit corps lui permet de se jouer d’ennemis bien plus grands que lui en volant à toute vitesse pour les piquer où ils sont vulnérables.", ["Tiny Bird Pokémon", "Pokémon Minoiseau"], null],
  "corvisquire": ["The lessons of many harsh battles have taught it how to accurately judge an opponent’s strength.", "Après avoir surmonté tant de rudes combats, il a appris à déterminer avec précision la puissance de ses adversaires.", ["Raven Pokémon", "Pokémon Corbeau"], null],
  "corviknight": ["With their great intellect and flying skills, these Pokémon very successfully act as the Galar region’s airborne taxi service.", "Grâce à son adresse remarquable en vol et sa grande intelligence, il travaille comme taxi volant de Galar.", ["Raven Pokémon", "Pokémon Corbeau"], null],
  "blipbug": ["Often found in gardens, this Pokémon has hairs on its body that it uses to assess its surroundings.", "On le voit souvent dans les champs. Les poils de son corps lui servent à capter ce qu’il se passe autour de lui.", ["Larva Pokémon", "Pokémon Larve"], null],
  "dottler": ["As it grows inside its shell, it uses its psychic abilities to monitor the outside world and prepare for evolution.", "Il se développe dans sa coquille et se prépare à évoluer en sondant les alentours grâce à ses pouvoirs psychiques.", ["Radome Pokémon", "Pokémon Radôme"], null],
  "orbeetle": ["It emits psychic energy to observe and study what’s around it—and what’s around it can include things over six miles away.", "Il déploie ses pouvoirs psychiques pour sonder les alentours, sur un rayon pouvant atteindre 10 km.", ["Seven Spot Pokémon", "Pokémon Sept Points"], null],
  "nickit": ["Cunning and cautious, this Pokémon survives by stealing food from others. It erases its tracks with swipes of its tail as it makes off with its plunder.", "Rusé et vigilant, il prend la poudre d’escampette après avoir volé de la nourriture en prenant soin d’effacer ses traces de pas avec sa queue.", ["Fox Pokémon", "Pokémon Renard"], null],
  "thievul": ["With a lithe body and sharp claws, it goes around stealing food and eggs. Boltund is its natural enemy.", "Grâce à son corps leste et ses griffes acérées, il va et vient en dérobant Œufs et nourriture. Son ennemi juré est Fulgudog.", ["Fox Pokémon", "Pokémon Renard"], null],
  "gossifleur": ["It whirls around in the wind while singing a joyous song. This delightful display has charmed many into raising this Pokémon.", "Nombreux sont ceux qui ont décidé d’en élever un après avoir été charmés par sa manière de chanter en virevoltant au gré de la brise.", ["Flowering Pokémon", "Pokémon Chef-Fleur"], null],
  "eldegoss": ["The cotton on the head of this Pokémon can be spun into a glossy, gorgeous yarn—a Galar regional specialty.", "Les fils tissés à partir du duvet sur sa tête sont satinés et absolument somptueux. Le textile ainsi créé est typique de la région de Galar.", ["Cotton Bloom Pokémon", "Pokémon Chef-Coton"], null],
  "wooloo": ["If its fleece grows too long, ??? won’t be able to move. Cloth made with the wool of this Pokémon is surprisingly strong.", "Si ses poils poussent trop, il ne peut plus bouger. Les étoffes tissées avec son pelage sont étonnamment solides.", ["Sheep Pokémon", "Pokémon Mouton"], null],
  "dubwool": ["Its majestic horns are meant only to impress the opposite gender. They never see use in battle.", "Ses splendides cornes lui servent à attirer les membres de l’autre sexe. Il ne s’en sert jamais pour se battre.", ["Sheep Pokémon", "Pokémon Mouton"], null],
  "chewtle": ["It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokémon bites down and never lets go.", "La corne sur sa tête est aussi dure que la roche. Il s’en sert pour se battre et lorsque l’ennemi flanche, il le mord et ne le lâche plus.", ["Snapping Pokémon", "Pokémon Mordillage"], null],
  "drednaw": ["This Pokémon rapidly extends its retractable neck to sink its sharp fangs into distant enemies and take them down.", "Son cou extensible lui permet d’atteindre des ennemis éloignés en un instant pour leur porter un coup décisif avec ses crocs aiguisés.", ["Bite Pokémon", "Pokémon Morsure"], null],
  "yamper": ["This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity.", "Ce glouton assiste les humains dans leur travail en échange de friandises. Il court sans arrêt, le corps enveloppé d’électricité.", ["Puppy Pokémon", "Pokémon Chiot"], null],
  "boltund": ["It sends electricity through its legs to boost their strength. Running at top speed, it easily breaks 50 mph.", "Il se sert de l’énergie électrique pour augmenter la puissance de ses membres. Sa vitesse maximale dépasse de peu les 90 km/h.", ["Dog Pokémon", "Pokémon Chien"], null],
  "rolycoly": ["It can race around like a unicycle, even on rough, rocky terrain. Burning coal sustains it.", "Il parcourt sans difficulté les sentiers rocheux accidentés à la manière d’un monocycle. Il a besoin de brûler du charbon pour vivre.", ["Coal Pokémon", "Pokémon Charbon"], null],
  "carkol": ["By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,800 degrees Fahrenheit.", "Il peut faire tourner ses pattes très vite pour se déplacer à une vitesse de 30 km/h. Il peut aussi souffler des flammes à 1 000 °C.", ["Coal Pokémon", "Pokémon Charbon"], null],
  "coalossal": ["While it’s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area.", "Lorsqu’il s’engage dans un combat, son tas de charbon brûle et vire au rouge, ce qui répand de petites étincelles qui calcinent ce qui l’entoure.", ["Coal Pokémon", "Pokémon Charbon"], null],
  "applin": ["As soon as it’s born, it burrows into an apple. Not only does the apple serve as its food source, but the flavor of the fruit determines its evolution.", "À la naissance, il s’installe dans une pomme et grandit en se nourrissant de sa chair. Son évolution dépend de la saveur du fruit.", ["Apple Core Pokémon", "Pokémon Nid Pomme"], null],
  "flapple": ["It flies on wings of apple skin and spits a powerful acid. It can also change its shape into that of an apple.", "Il vole avec ses ailes faites de pelures de pomme et crache une substance très acide. Il peut aussi prendre la forme de ce fruit.", ["Apple Wing Pokémon", "Pokémon Ailes Pomme"], null],
  "appletun": ["Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack.", "Son corps est recouvert de nectar. La peau de son dos, particulièrement sucrée, constituait jadis le goûter des enfants.", ["Apple Nectar Pokémon", "Pokémon Jus Pomme"], null],
  "silicobra": ["It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.", "En expulsant du sable par les narines, il aveugle son adversaire et en profite pour se cacher sous terre.", ["Sand Snake Pokémon", "Pokémon Serpensable"], null],
  "sandaconda": ["Its unique style of coiling allows it to blast sand out of its sand sac more efficiently.", "S’il s’enroule d’une manière aussi particulière, c’est pour optimiser l’expulsion de sable par ses narines.", ["Sand Snake Pokémon", "Pokémon Serpensable"], null],
  "cramorant": ["This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey.", "Très glouton, il avale les Embrochet d’une seule bouchée, mais il lui arrive de se tromper et de tenter de gober un autre Pokémon.", ["Gulp Pokémon", "Pokémon Avaltouron"], null],
  "arrokuda": ["After it’s eaten its fill, its movements become extremely sluggish. That’s when Cramorant swallows it up.", "Lorsqu’il a le ventre plein, il a beaucoup plus de mal à se déplacer, et c’est à ce moment précis qu’il se fait gober par les Nigosier.", ["Rush Pokémon", "Pokémon Fonceur"], null],
  "barraskewda": ["It spins its tail fins to propel itself, surging forward at speeds of over 100 knots before ramming prey and spearing into them.", "Il charge d’un coup en faisant tourner sa nageoire caudale. Il peut transpercer ses proies à une vitesse dépassant les 100 nœuds.", ["Skewer Pokémon", "Pokémon Transperceur"], null],
  "toxel": ["It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis.", "Par un procédé chimique, il change son poison en électricité. L’intensité du courant est faible, mais peut engourdir un ennemi.", ["Baby Pokémon", "Pokémon Poupon"], null],
  "toxtricity": ["This short-tempered and aggressive Pokémon chugs stagnant water to absorb any toxins it might contain.", "Impatient et bagarreur, ce Pokémon avale de grandes gorgées d’eau croupie pour en absorber toute la toxicité.", ["Punk Pokémon", "Pokémon Punk"], null],
  "sizzlipede": ["It wraps prey up with its heated body, cooking them in its coils. Once they’re well-done, it will voraciously nibble them down to the last morsel.", "Il enserre fermement ses proies avec son corps brûlant et, quand elles sont bien grillées, il les dévore.", ["Radiator Pokémon", "Pokémon Calorifère"], null],
  "centiskorch": ["While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs.", "Il est de nature agressive. Non seulement son corps brûlant est dangereux, mais il possède en plus d’énormes crocs très pointus.", ["Radiator Pokémon", "Pokémon Calorifère"], null],
  "clobbopus": ["Its tentacles tear off easily, but it isn’t alarmed when that happens—it knows they’ll grow back. It’s about as smart as a three-year-old.", "Il a l’intelligence d’un enfant de trois ans. Il perd souvent ses tentacules, mais comme ils repoussent, il ne s’en soucie guère.", ["Tantrum Pokémon", "Pokémon Caprice"], null],
  "grapploct": ["Searching for an opponent to test its skills against, it emerges onto land. Once the battle is over, it returns to the sea.", "Mû par le besoin de tester la force de ses bras, il se rend sur la terre ferme pour trouver un adversaire. Il retourne à l’eau après le combat.", ["Jujitsu Pokémon", "Pokémon Jujitsu"], null],
  "sinistea": ["The teacup in which this Pokémon makes its home is a famous piece of antique tableware. Many forgeries are in circulation.", "Il élit domicile dans des tasses de thé anciennes de grand renom. Parmi celles-ci se trouvent de nombreuses contrefaçons.", ["Black Tea Pokémon", "Pokémon Thé Noir"], null],
  "polteageist": ["Leaving leftover black tea unattended is asking for this Pokémon to come along and pour itself into it, turning the tea into a new ???.", "Dès qu’il voit un reste de thé noir, il se verse dedans pour donner naissance à un ???.", ["Black Tea Pokémon", "Pokémon Thé Noir"], null],
  "hatenna": ["If this Pokémon senses a strong emotion, it will run away as fast as it can. It prefers areas without people.", "Il aime les lieux inhabités. S’il perçoit des émotions trop fortes, il s’enfuit aussi vite que possible.", ["Calm Pokémon", "Pokémon Calme"], null],
  "hattrem": ["Using the braids on its head, it pummels foes to get them to quiet down. One blow from those braids would knock out a professional boxer.", "Il frappe ses ennemis avec ses tresses pour les faire taire. Sa puissance est telle qu’il peut mettre K.O. un boxeur professionnel d’un seul coup.", ["Serene Pokémon", "Pokémon Serein"], null],
  "hatterene": ["If you’re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch.", "On l’appelle aussi la « sorcière de la forêt ». Ce Pokémon lacère quiconque fait trop de bruit avec les griffes de son tentacule.", ["Silent Pokémon", "Pokémon Silencieux"], null],
  "impidimp": ["It sneaks into people’s homes, stealing things and feasting on the negative energy of the frustrated occupants.", "Il se glisse dans les foyers pour commettre un larcin et en profite pour se nourrir de l’énergie négative des habitants contrariés.", ["Wily Pokémon", "Pokémon Malin"], null],
  "morgrem": ["With sly cunning, it tries to lure people into the woods. Some believe it to have the power to make crops grow.", "La nuit, il ruse pour attirer ses proies dans la forêt. On raconte qu’il a le pouvoir de faire pousser les cultures agricoles.", ["Devious Pokémon", "Pokémon Scélérat"], null],
  "grimmsnarl": ["Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would.", "Ses cheveux sont comme des muscles filandreux qu’il peut détacher pour saisir ses adversaires, tels des tentacules.", ["Bulk Up Pokémon", "Pokémon Gonflette"], null],
  "obstagoon": ["It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch.", "Il a évolué après avoir enchaîné de nombreux combats. Le cri qu’il pousse lorsqu’il fait un « X » avec ses bras ébranle n’importe quel ennemi.", ["Blocking Pokémon", "Pokémon Barrage"], null],
  "perrserker": ["After many battles, it evolved dangerous claws that come together to form daggers when extended.", "Il s’est tant adonné au combat qu’il a évolué : il est désormais doté de griffes redoutables qui prennent la forme de dagues en s’allongeant.", ["Viking Pokémon", "Pokémon Viking"], null],
  "cursola": ["Be cautious of the ectoplasmic body surrounding its soul. You’ll become stiff as stone if you touch it.", "Ceux qui ont le malheur de toucher le corps spirituel qui protège son noyau se retrouveront immobilisés, comme changés en pierre.", ["Coral Pokémon", "Pokémon Corail"], null],
  "sirfetchd": ["After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food.", "Il pare les attaques avec le tranchant de son solide poireau, et contre-attaque avec la pointe de la tige. Son arme est également comestible.", ["Wild Duck Pokémon", "Pokémon Canard Fou"], null],
  "mr-rime": ["Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.", "Ses gestes hilarants le rendent très populaire. Il peut libérer ses pouvoirs psychiques depuis le motif sur son ventre.", ["Comedian Pokémon", "Pokémon Comédien"], null],
  "runerigus": ["Never touch its shadowlike body, or you’ll be shown the horrific memories behind the picture carved into it.", "Quiconque touchera son corps semblable à une ombre devra endurer la vision des souvenirs effroyables gravés dans ses motifs.", ["Grudge Pokémon", "Pokémon Rancune"], null],
  "milcery": ["They say that any patisserie visited by ??? is guaranteed success and good fortune.", "Les pâtissiers connaissent tous ce vieil adage : Quand ??? apparaît, le succès est assuré.", ["Cream Pokémon", "Pokémon Crème"], null],
  "alcremie": ["When ??? is content, the cream it secretes from its hands becomes sweeter and richer.", "Quand il est heureux, la crème qu’il produit avec ses mains devient plus sucrée et plus onctueuse.", ["Cream Pokémon", "Pokémon Crème"], null],
  "falinks": ["The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.", "À six, ils représentent un Pokémon unique. Ils peuvent changer de formation et comptent sur leur travail d’équipe en combat.", ["Formation Pokémon", "Pokémon Escadron"], null],
  "pincurchin": ["It stores electricity in each spine. Even if one gets broken off, it still continues to emit electricity for at least three hours.", "Chacune de ses épines est chargée en électricité. S’il en perd une, celle-ci continue d’émettre un courant électrique pendant trois heures.", ["Sea Urchin Pokémon", "Pokémon Oursin"], null],
  "snom": ["It eats snow that piles up on the ground. The more snow it eats, the bigger and more impressive the spikes on its back grow.", "Il se nourrit de la neige entassée sur le sol. Plus il en mange, plus les épines sur son dos grandissent.", ["Worm Pokémon", "Pokémon Ver"], null],
  "frosmoth": ["It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.", "Sans pitié pour les vandales, il bat ses ailes gelées pour provoquer des blizzards et punir quiconque ose souiller les champs et les collines.", ["Frost Moth Pokémon", "Pokémon Mite Givre"], null],
  "stonjourner": ["Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle.", "Tous les ans à la même date, ils arrivent de nulle part pour se réunir en cercle. C’est une de leurs coutumes.", ["Big Rock Pokémon", "Pokémon Mégalithe"], null],
  "eiscue": ["This Pokémon keeps its heat-sensitive head cool with ice. It fishes for its food, dangling its single hair into the sea to lure in prey.", "Ne supportant pas la chaleur, il se rafraîchit toujours la tête avec de la glace. Il pêche de quoi se nourrir à l’aide de son cheveu.", ["Penguin Pokémon", "Pokémon Pingouin"], null],
  "indeedee": ["Through its horns, it can pick up on the emotions of creatures around it. Positive emotions are the source of its strength.", "Avec ses cornes, il peut percevoir les émotions des êtres vivants alentour. Celles qui sont positives lui servent de source d’énergie.", ["Emotion Pokémon", "Pokémon Émotion"], null],
  "morpeko": ["It carries electrically roasted seeds with it as if they’re precious treasures. No matter how much it eats, it always gets hungry again in short order.", "Il a beau manger, il a tout le temps faim. Il a toujours des graines grillées à l’électricité sur lui.", ["Two-Sided Pokémon", "Pokémon Volt Face"], null],
  "cufant": ["If a job requires serious strength, this Pokémon will excel at it. Its copper body tarnishes in the rain, turning a vibrant green color.", "Les travaux physiques, c’est son affaire. Son corps de cuivre rouille sous la pluie et prend une vive couleur verte.", ["Copperderm Pokémon", "Pokémon Pachycuivre"], null],
  "copperajah": ["These Pokémon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks into powder.", "Ces Pokémon vivent en troupeau. L’étreinte de leur trompe est si forte qu’elle suffit à réduire un rocher en poussière.", ["Copperderm Pokémon", "Pokémon Pachycuivre"], null],
  "dracozolt": ["The powerful muscles in its tail generate its electricity. Compared to its lower body, its upper half is entirely too small.", "Il envoie des décharges avec les muscles puissants de sa queue. La partie supérieure de son corps est trop petite par rapport à la partie inférieure.", ["Fossil Pokémon", "Pokémon Fossile"], null],
  "arctozolt": ["This Pokémon lived on prehistoric seashores and was able to preserve food with the ice on its body. It went extinct because it moved so slowly.", "Autrefois, il vivait en bord de mer et conservait sa nourriture dans la glace de son corps, mais il s’est éteint, car il avait du mal à se déplacer.", ["Fossil Pokémon", "Pokémon Fossile"], null],
  "dracovish": ["Its mighty legs are capable of running at speeds exceeding 40 mph, but this Pokémon can’t breathe unless it’s underwater.", "Ses pattes robustes lui permettent de courir à plus de 60 km/h, mais en revanche, il ne peut respirer que sous l’eau.", ["Fossil Pokémon", "Pokémon Fossile"], null],
  "arctovish": ["The skin on its face is impervious to attack, but breathing difficulties made this Pokémon go extinct anyway.", "Aucune attaque ne pouvait égratigner la peau de son visage, mais il s’est éteint, car il avait du mal à respirer.", ["Fossil Pokémon", "Pokémon Fossile"], null],
  "duraludon": ["The special metal that composes its body is very light, so this Pokémon has considerable agility. It lives in caves because it dislikes the rain.", "Son corps, composé d’un métal spécial, est léger et lui offre une excellente mobilité. Il est toutefois sensible à la pluie et vit donc dans les grottes.", ["Alloy Pokémon", "Pokémon Alliage"], null],
  "dreepy": ["If this weak Pokémon is by itself, a mere child could defeat it. But if ??? has friends to help it train, it can evolve and become much stronger.", "Seul, il est si faible qu’il ne saurait rivaliser avec un enfant, mais en coopérant avec ses semblables, il peut devenir assez fort pour évoluer.", ["Lingering Pokémon", "Pokémon Âme Errante"], null],
  "drakloak": ["Without a Dreepy to place on its head and care for, it gets so uneasy it’ll try to substitute any Pokémon it finds for the missing Dreepy.", "Il prend soin du Fantyrm sur sa tête. Quand ce dernier n’est plus là, il panique et tente de le remplacer par un autre Pokémon.", ["Caretaker Pokémon", "Pokémon Baby-sitter"], null],
  "dragapult": ["Apparently the Dreepy inside ???’s horns eagerly look forward to being launched out at Mach speeds.", "Il paraît que les Fantyrm installés dans ses cornes attendent impatiemment le moment où ils seront propulsés à la vitesse du son.", ["Stealth Pokémon", "Pokémon Furtif"], null],
  "zacian": ["This Pokémon has slumbered for many years. Some say it’s Zamazenta’s elder sister—others say the two Pokémon are rivals.", "On dit qu’il s’agit de la figure fraternelle et du rival de Zamazenta, un Pokémon plongé dans un long sommeil.", ["Warrior Pokémon", "Pokémon Valeureux"], null],
  "zamazenta": ["This Pokémon slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed.", "Ce Pokémon, changé en statue, est resté pétrifié si longtemps qu’il a failli tomber dans l’oubli.", ["Warrior Pokémon", "Pokémon Valeureux"], null],
  "eternatus": ["It was inside a meteorite that fell 20,000 years ago. There seems to be a connection between this Pokémon and the Dynamax phenomenon.", "Il se trouvait dans une météorite qui s’est écrasée il y a 20 000 ans. Il semble y avoir un lien entre ce Pokémon et le phénomène Dynamax.", ["Gigantic Pokémon", "Pokémon Giga"], null],
  "kubfu": ["If ??? pulls the long white hair on its head, its fighting spirit heightens and power wells up from the depths of its belly.", "Lorsqu’il tire sur les longs poils blancs sur sa tête, il devient plus combatif et de l’énergie jaillit de sous son nombril.", ["Wushu Pokémon", "Pokémon Kung-fu"], null],
  "urshifu": ["Inhabiting the mountains of a distant region, this Pokémon races across sheer cliffs, training its legs and refining its moves.", "Il vit dans une lointaine région montagneuse où il peaufine ses techniques et muscle ses jambes en courant le long des falaises abruptes.", ["Wushu Pokémon", "Pokémon Kung-fu"], null],
  "zarude": ["Once the vines on ???’s body tear off, they become nutrients in the soil. This helps the plants of the forest grow.", "Lorsque ses lianes se détachent de son corps, elles fertilisent le sol et favorisent la croissance des plantes de la forêt.", ["Rogue Monkey Pokémon", "Pokémon Vilain Singe"], null],
  "regieleki": ["Its entire body is made up of a single organ that generates electrical energy. ??? is capable of creating all Galar’s electricity.", "Son corps est entièrement composé d’organes générant de l’électricité. Il peut produire assez d’énergie pour alimenter tout Galar.", ["Electron Pokémon", "Pokémon Électron"], null],
  "regidrago": ["Its body is composed of crystallized dragon energy. ??? is said to have the powers of every dragon Pokémon.", "Son corps est entièrement composé de cristaux d’énergie draconique. Il possèderait les pouvoirs de tous les Pokémon Dragon.", ["Dragon Orb Pokémon", "Pokémon Boule Dragon"], null],
  "glastrier": ["??? has tremendous physical strength, and the mask of ice covering its face is 100 times harder than diamond.", "Ce Pokémon à la force hors du commun porte un masque composé de glace cent fois plus solide que le diamant.", ["Wild Horse Pokémon", "Pokémon Cheval Rétif"], null],
  "spectrier": ["As it dashes through the night, ??? absorbs the life-force of sleeping creatures. It craves silence and solitude.", "Ce Pokémon friand de silence et de solitude galope à travers les ténèbres nocturnes et aspire l’énergie vitale des êtres endormis.", ["Swift Horse Pokémon", "Pokémon Cheval Vif"], null],
  "calyrex": ["??? is known in legend as a king that ruled over Galar in ancient times. It has the power to cause hearts to mend and plants to spring forth.", "Ce roi légendaire qui a régné sur Galar il y a fort longtemps possède le pouvoir d’apaiser les cœurs et de faire germer les plantes.", ["King Pokémon", "Pokémon Roi"], null],
};
